const _glCtx = acquireGL(canvas, {
    onLost: () => console.error("[gl] WebGL2 context LOST -- GPU reset or context limit hit; reload to recover."),
    onRestored: () => console.warn("[gl] WebGL2 context restored."),
});
const gl = _glCtx.gl;   // real context, or a no-op stub when WebGL2 is unavailable (see glBootstrap)
const glOk = _glCtx.ok;
// v2778 - graceful fallback: paint the reason on the canvas instead of leaving a black screen
if (!glOk) showGLUnavailable(canvas, "WebGL2 unavailable\nHardware acceleration may be off, or the GPU process was lost.\nOpen chrome://gpu, enable graphics acceleration, then reload.");

