frameDirty.addSource("domAnimation", domAnimationProbe(), { covers: ["cssAnimation", "cssTransition", "webAnimations"] });

// ...and the readable form of the same question, so a page that will not go quiet can be ASKED WHY rather
// than merely being slow. window.frameDirty.domStatus() names every animation currently running, and lists
// separately the endless ones -- an infinite CSS spin holds the flag open forever by design, and that is a
// thing to know about a HUD rather than a thing to discover with a profiler.
frameDirty.domStatus = () => domAnimationStatus();

/**
 * window.frameDirty.census() -- how far the census has to go before this may be enabled by default.
 *
 * *** IT FETCHES main.js AND READS IT, WHICH IS THE ONLY HONEST WAY TO DO THIS IN A BROWSER. *** The census
 * is derived from the loop's source, and a page does not have its own source as text. Baking a list in at
 * build time would produce a census that silently described a file that no longer exists -- the staleness
 * this whole mechanism is arranged against. Async because a fetch is.
 */
frameDirty.census = async function census() {
    let src = "";
    try {
        const r = await fetch("/main.js");
        if (!r.ok) throw new Error("HTTP " + r.status);
        src = await r.text();
    } catch (e) {
        console.warn("[FRAMEDIRTY] could not read main.js to census it (" + (e?.message || e) + "). Run tools: node engine/frameDirtyCensus-selfcheck.mjs");
        return null;
    }
    const c = frameDirtyCensus(src, frameDirty.sources());
    console.log(frameDirtyReport(src, frameDirty.sources()));
    if (c.unguarded.length) {
        console.log("[FRAMEDIRTY] " + c.unguarded.length + " animator(s) can still change the picture with no registered source. " +
                    "That number, not an opinion, is what decides when setEnabled(true) becomes the default.");
    }
    return c;
};

// v4179 -- *** WEBXR, AND THE FIRST THING TO SAY IS WHY THE USUAL ANSWER DOES NOT APPLY HERE. *** Every guide
// says renderer.xr.enabled = true and renderer.setAnimationLoop(fn). Those are three.js WebGLRenderer methods
// and THIS FILE NEVER IMPORTS three -- the engine draws through render/voxelrenderer.js over raw WebGL2. So
// the path is the raw one: navigator.xr, XRWebGLLayer, session.requestAnimationFrame, one draw per eye.
//
// The session lifecycle and all the matrix work live in engine/xrSession.mjs, which has no GL in it and is
// gated in node against XRView-shaped fixtures. What is HERE is the part that genuinely needs a context: the
// XRWebGLLayer, and the per-eye draw.
// v4212 -- controllers. Keyed on the inputSource object (not on handedness -- two sources can both report
// "none"), reports EDGES rather than levels, and synthesises a release for a controller that vanishes
// mid-press. All of that is gated in node in tools/ship/xrStereo-selfcheck.mjs against fixtures.
const xrInput = new XRInputTracker();
// v4219 -- *** v4212 READ THE STICKS AND NOTHING MOVED. *** The comment in _renderXRFrame said a locomotion
// vector "is applied to the camera this frame" and nothing consumed moveVector(). Left stick walks, right
// stick snap-turns; see engine/xrLocomotion.mjs for why this is a reference space and not the camera.
const xrLocomotion = new Locomotion();
let _xrLastFrameTime = 0;
const xr = new XRSessionManager({
    requestSession: async (mode, init) => {
        // The context must be told it will be used with XR BEFORE the session is created, or the session
        // cannot use it. Async, and easy to forget because everything still works on the desktop without it.
        if (typeof gl.makeXRCompatible === "function") await gl.makeXRCompatible();
        const session = await navigator.xr.requestSession(mode, init);
        session.updateRenderState({ baseLayer: new XRWebGLLayer(session, gl) });
        return session;
    },
    onStateChange: (state) => {
        // *** ENTERING VR MUST WAKE THE DIRTY FLAG AND MUST KEEP IT AWAKE. *** engine/frameDirty.js skips a
        // frame when the scene has not changed, which is right on a monitor and wrong in a headset: the
        // display keeps its rate regardless, and a skipped frame is REPROJECTED from the last one. Reprojection
        // of a stale frame is exactly what makes people ill, so a skipped frame in VR is not a saved frame,
        // it is a wrong one. The flag is disabled for the duration and restored on exit.
        if (state === "active") { xr._fdWas = frameDirty.enabled; frameDirty.setEnabled(false); }
        else if (state === "idle" && xr._fdWas !== undefined) { frameDirty.setEnabled(xr._fdWas); xr._fdWas = undefined; }
        // *** v4212 -- THE POST CHAIN'S BUFFERS ARE SIZED TO THE CANVAS, AND IN VR THE TARGET IS NOT THE
        // CANVAS. *** An XRWebGLLayer has its own framebufferWidth/Height -- typically larger than the
        // canvas and a different shape -- so a scene FBO left at canvas size would put every eye viewport
        // in the wrong place within it. Resize on entry, restore on exit.
        // AND setEyeRect(null) ON THE WAY OUT IS NOT OPTIONAL: the rect is sticky, so a desktop frame after
        // leaving VR would otherwise keep rendering into half a frame with a vignette centred off to one side.
        try {
            if (state === "active") {
                const lay = xr.session?.renderState?.baseLayer;
                if (lay && bloomPass) {
                    xr._postWas = [canvas.width, canvas.height];
                    bloomPass.resize(lay.framebufferWidth, lay.framebufferHeight);
                }
                xrInput.reset();
            } else if (state === "idle") {
                if (bloomPass) { bloomPass.setEyeRect(null); if (xr._postWas) bloomPass.resize(xr._postWas[0], xr._postWas[1]); }
                xr._postWas = undefined;
                xrInput.reset();
                haptics.cancel();   // v4213 -- a scheduled pulse outliving its session is a buzz with no owner
            }
        } catch (e) { console.warn("[VR] post-chain resize:", e && e.message); }
        frameDirty.markDirty("xr:" + state);
        console.log("[VR] " + state);
        try { window._toaster?.show?.({ title: state === "active" ? "🥽 In VR" : "🥽 VR " + state, msg: state === "active" ? "headset has the frame clock" : "", type: "system", duration: 3000 }); } catch (e) {}
    },
});
window.swekVR = {
    /** Is a headset actually reachable? Three different answers, not one flat false -- see describeSupport. */
    async check() { const r = await describeSupport(); console.log("[VR] " + r.reason); return r; },
    async enter() {
        const sup = await describeSupport();
        if (!sup.ok) { console.warn("[VR] " + sup.reason); return sup; }
        const r = await xr.enter();
        if (!r.ok) console.warn("[VR] " + r.reason);
        return r;
    },
    async exit() { return xr.exit(); },
    status() { return xr.stats(); },
};
window.swekHaptics = {
    /** Play a named effect on the phone/desktop path. window.swekHaptics.play("success") */
    play: (name) => haptics.play(name),
    /** What is available, and WHY not -- iOS Safari has never shipped the Vibration API. */
    check: () => { const r = haptics.supported(); console.log("[haptics] " + r.reason); return r; },
    strength: (k) => haptics.setStrength(k),
    enable: (on) => haptics.setEnabled(on !== false),
    names: () => Object.keys(hapticEffects.EFFECTS),
};
// v4215 -- *** THE TREE ANIMATED BUT COULD NOT SEQUENCE. *** domAnimation.mjs, springMotion.js and
// stagger.mjs each animate ONE thing from now; nothing could say "at t=2.5 start the disintegrate, at t=4
// cross-fade". fx/timeline.mjs is the missing piece, and the part that makes it worth having over a pile of
// setTimeouts is that IT IS CORRECT WHEN YOU SCRUB: a jump backwards exits what it should, and a jump that
// steps clean over a short clip REPORTS IT rather than silently not running it.
//
// The clip's `effect` is a plain function the caller supplies. This wiring does not invent an effect
// registry -- window.fireworks, window.domFx, window.transitions and the rest are already the registry, and
// a second one would be the third copy of an idea the tree keeps warning itself about.
const _timelines = new Map();
window.swekTimeline = {
    /**
     * Make a named timeline. clips: [{id, start, end, layer?, effect?}] where effect is
     * (progress, ctx) => void, and ctx carries { phase: "start"|"update"|"end"|"skipped", dt, time }.
     */
    make(name, clips) {
        const made = clips.map((c) => tlClip(c));
        const problems = validateClips(made);
        if (problems.length) { console.warn("[timeline] " + name + ":", problems); return { ok: false, problems }; }
        _timelines.set(name, { tl: new Timeline(made), fx: new Map(made.map((c) => [c.id, c.effect])) });
        return { ok: true, name, duration: durationOfClips(made) };
    },
    /** Evaluate at an absolute time and run the effects. Returns what changed, so a caller can log it. */
    at(name, t) {
        const e = _timelines.get(name);
        if (!e) return { ok: false, error: "no timeline named " + name };
        const r = e.tl.evaluate(t);
        const call = (c, phase, progress) => { const f = e.fx.get(c.id); if (typeof f === "function") { try { f(progress, { phase, dt: r.dt, time: r.time }); } catch (err) { console.warn("[timeline] " + c.id + " " + phase + ":", err && err.message); } } };
        for (const c of r.entered) call(c, "start", 0);
        for (const a of r.active) call(a.clip, "update", a.progress);
        for (const c of r.exited) call(c, "end", 1);
        // A skipped clip is REPORTED, never quietly run and never quietly dropped -- the caller decides.
        for (const c of r.skipped) call(c, "skipped", 1);
        return { ok: true, entered: r.entered.map((c) => c.id), exited: r.exited.map((c) => c.id),
                 skipped: r.skipped.map((c) => c.id), active: r.active.map((a) => a.clip.id), dt: r.dt };
    },
    /** Back to "never evaluated" -- without this a re-run emits end() for effects it never started. */
    reset(name) { const e = _timelines.get(name); if (e) e.tl.reset(); return !!e; },
    list() { return Array.from(_timelines.keys()); },
};
function durationOfClips(cs) { let d = 0; for (const c of cs) if (c.end > d) d = c.end; return d; }
console.log("[timeline] window.swekTimeline.make(name, clips) / .at(name, t). Correct under a scrub: a jump over a clip is REPORTED, not silently skipped.");
console.log("[haptics] window.swekHaptics.check() / .play('success'). VR controllers buzz on trigger and squeeze.");
console.log("[VR] window.swekVR.check() to see whether a headset is reachable · .enter() / .exit(). The engine is raw WebGL2, so this is the raw WebXR path, not three's.");

// The stereo draw. Deliberately NOT the full desktop render block: that block runs shadow cascades, the post
// chain and the HUD, all of which assume ONE camera and one full-screen quad. Two eyes through a full-screen
// post pass is its own piece of work. What this draws is the world, twice, correctly -- which is the half
// that makes the headset show the place you are standing in.
function _renderXRFrame(frame) {
    const layer = xr.session?.renderState?.baseLayer;
    if (!layer) return false;
    const views = xr.viewsFor(frame, layer, camera);
    if (!views.length) return false;                 // no pose: draw NOTHING rather than the last one

    // v4212 -- controllers. Read BEFORE the draw so a press acts on the frame it happened in rather than the
    // next one, and so the locomotion step below moves the reference space before this frame's views are
    // taken from it. (Until v4219 this comment said "applied to the camera this frame" and nothing consumed
    // moveVector() at all -- a comment describing an intention rather than the code under it.)
    try {
        const evs = xrInput.update(xr.session.inputSources, (src) =>
            (src.targetRaySpace && xr.refSpace) ? frame.getPose(src.targetRaySpace, xr.refSpace) : null);
        for (const e of evs) {
            // v4213 -- *** v4212 SHIPPED THE EDGE DETECTION AND NOTHING TO ANSWER IT WITH. *** A trigger that
            // reports exactly one press and produces no sensation is a control you have to look at to trust.
            // The effect goes to the controller THAT FIRED IT (e.source), not to "the controller" -- a buzz
            // in the wrong hand is worse than none.
            if (e.type === "select")  { try { haptics.play("trigger", e.source); } catch (_) {} }
            if (e.type === "squeeze") { try { haptics.play("grab", e.source); } catch (_) {} }
            if (e.type === "select") { try { window._onXRSelect?.(e); } catch (_) {} }
        }
    } catch (e) {}

    // v4219 -- *** LOCOMOTION, WHICH IS THE THING THE COMMENT ABOVE PROMISED SINCE v4212. *** The left stick
    // walks on the floor plane relative to where the head is LOOKING (yaw only -- pitching up must not fly
    // you), the right stick snap-turns about the head. Both accumulate into an absolute player pose, and the
    // reference space is rebuilt from the BASE space each time so the total is never applied twice.
    try {
        const now = (typeof performance !== "undefined" ? performance.now() : Date.now()) / 1000;
        const dt = _xrLastFrameTime ? now - _xrLastFrameTime : 0;
        _xrLastFrameTime = now;
        const pose = (typeof frame.getViewerPose === "function" && xr.refSpace) ? frame.getViewerPose(xr.refSpace) : null;
        const head = pose && pose.transform ? pose.transform : null;
        const step = xrLocomotion.update({
            moveStick: xrInput.moveVector("left"),
            turnStick: xrInput.moveVector("right").x,
            headQuat: head ? head.orientation : null,
            headPos: head ? head.position : null,
            dt,
        });
        if (step.moved || step.turned) {
            xr.applyOffset(step.transform);
            // A snap turn is a discrete event and reads better with a confirmation you can feel. The effect
            // is "selection" -- the detent tick -- and it goes to the hand that TURNED. (The first draft of
            // this line asked for "tick", which is not an effect name: play() would have returned
            // {ok:false, reason:"unknown effect: tick"} and buzzed nothing, silently, forever.)
            if (step.turned) {
                try {
                    let hand = null;
                    for (const src of xr.session.inputSources) if (src.handedness === "right") { hand = src; break; }
                    haptics.play("selection", hand);
                } catch (_) {}
            }
        }
    } catch (e) {}

    const visible = world.getVisibleChunks();

    // *** v4212 -- THE POST CHAIN, PER EYE. *** engine/xrPost.mjs works out each eye's rect within the
    // layer's SHARED framebuffer and what that costs if it is ignored: the 9-tap half-res blur reaches 8
    // full-resolution pixels across the seam, and the vignette's `vUV - 0.5` centre lands ON the seam,
    // 0.25 in UV from where each eye's centre actually is. Both numbers are measured in the gate.
    // The scene is drawn for BOTH eyes into the shared scene FBO first, then the chain is applied once per
    // eye with that eye's rect -- the clamp in the shader stops the blur READING across the seam, and the
    // scissor in apply() stops the two composites WRITING over each other. Neither substitutes for the other.
    const plan = postPlanFor(views, layer, { screenSpaceSources: false });
    const post = !!bloomPass && plan.perEye.length === views.length;

    if (post) {
        bloomPass.bind();
        gl.clearColor(0.52, 0.64, 0.76, 1);
        gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
        for (const v of views) {
            try { renderer.render(visible, v.camera, { viewport: v.viewport }); } catch (e) {}
        }
        bloomPass.outputFBO = layer.framebuffer;
        for (let i = 0; i < views.length; i++) {
            bloomPass.setEyeRect(plan.perEye[i]);
            try { bloomPass.apply(views[i].viewport); } catch (e) {}
        }
        bloomPass.outputFBO = null;
        bloomPass.setEyeRect(null);
    } else {
        // The v4179 path, unchanged, and it stays because it is the one that WORKS when the post chain is
        // absent or the rects could not be built. A headset showing the world without bloom is a headset
        // showing the world; a headset showing nothing because a plan came back short is not.
        gl.bindFramebuffer(gl.FRAMEBUFFER, layer.framebuffer);
        gl.clearColor(0.52, 0.64, 0.76, 1);
        gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);   // ONCE, not per eye -- the eyes share a framebuffer
        for (const v of views) {
            try { renderer.render(visible, v.camera, { viewport: v.viewport }); } catch (e) {}
        }
    }
    return true;
}

// v341 — Gaussian Splat support. _activeSplats is what the main loop
// draws each frame (after particles, before bloom). window.splat is the
// user API: drop a .ply/.splat URL, get a renderer back, position it
// where you want.
const _activeSplats = [];
window.splat = {
    /** Load a .ply or .splat from a URL and add to the world. */
    load: async (url, opts = {}) => {
        console.log("[splat] loading", url);
        // v4199 -- *** THIS REPORTED NOTHING AT ALL UNTIL NOW. *** A .ply is routinely tens of megabytes and
        // the only feedback was the console line above, then silence until it either appeared or did not.
        // net/fetchProgress.js streams the body and reports what has arrived; ui/localModelRun.js's
        // progressLine() turns that into a line WITHOUT inventing a percentage when the server's
        // Content-Length cannot be compared to the decoded bytes it counts.
        const got = await fetchWithProgress(url, {
            cache: "no-store", file: url,
            onProgress: opts.onProgress || ((ev) => {
                if (ev.total) console.log(`[splat] ${((ev.loaded / ev.total) * 100).toFixed(0)}% (${ev.loaded} of ${ev.total} bytes)`);
                else console.log(`[splat] ${ev.loaded} bytes -- ${ev.totalUnknownBecause}`);
            }),
        });
        if (!got.ok) throw new Error(`splat fetch failed: ${got.status} ${url}`);
        const buf = got.bytes.buffer.slice(got.bytes.byteOffset, got.bytes.byteOffset + got.bytes.byteLength);
        const parsed = parseSplatFile(buf, url);
        console.log(`[splat] parsed ${parsed.count} gaussians from ${url}; bbox center=`, parsed.bbox.center, "size=", parsed.bbox.size);
        const sr = new SplatRenderer(gl, parsed);
        if (opts.position) sr.position = opts.position.slice();
        else {
            // Drop ~10 units in front of the camera at eye height by default
            sr.position = [
                (camera.position?.x ?? 0),
                (camera.position?.y ?? 5),
                (camera.position?.z ?? 0) - 10,
            ];
        }
        if (typeof opts.scale === "number") sr.scale = opts.scale;
        _activeSplats.push(sr);
        console.log(`[splat] added at`, sr.position, `scale=${sr.scale}. ${_activeSplats.length} active`);
        return sr;
    },
    /**
     * v358 — add an already-parsed splat struct directly (skipping
     * .ply fetch/decode). Use with engine/splatGenerator.js outputs
     * or any compatible struct: {count, positions, scales, quats,
     * colors, opacities, bbox}.
     */
    add: (splat, opts = {}) => {
        if (!splat || typeof splat.count !== "number" || !splat.positions) {
            throw new Error("splat.add: expects {count, positions, scales, quats, colors, opacities, bbox}");
        }
        const sr = new SplatRenderer(gl, splat);
        sr.position = opts.position ? opts.position.slice() : [
            (camera.position?.x ?? 0),
            (camera.position?.y ?? 5),
            (camera.position?.z ?? 0) - 10,
        ];
        if (typeof opts.scale === "number") sr.scale = opts.scale;
        _activeSplats.push(sr);
        console.log(`[splat] added inline ${splat.count} gaussians at`, sr.position, `scale=${sr.scale}. ${_activeSplats.length} active`);
        return sr;
    },
    // v1014 — BAKE a loaded splat to a compact, recentered, height-normalized
    // point set {positions, colors, count} (downsampled to maxPoints). Reusable:
    // feed it back via splat.add, or hand it to the avatar room as a grabbable.
    bake: (src, opts = {}) => {
        let sr = src;
        if (src == null) sr = _activeSplats[_activeSplats.length - 1];      // most recent
        else if (typeof src === "number") sr = _activeSplats[src];
        const sp = sr && sr.splat;
        if (!sp || !sp.positions) { console.warn("[splat] bake: no loaded splat to bake"); return null; }
        const N = sp.count || (sp.positions.length / 3 | 0);
        const maxN = Math.max(64, opts.maxPoints || 2000);
        const stride = Math.max(1, Math.floor(N / maxN));
        const outN = Math.floor(N / stride);
        let cx = 0, cy = 0, cz = 0, mnY = Infinity, mxY = -Infinity;
        for (let j = 0, i = 0; j < outN; j++, i += stride) {
            const y = sp.positions[i * 3 + 1];
            cx += sp.positions[i * 3]; cy += y; cz += sp.positions[i * 3 + 2];
            if (y < mnY) mnY = y; if (y > mxY) mxY = y;
        }
        cx /= outN; cy /= outN; cz /= outN;
        const s = 1 / ((mxY - mnY) || 1);                                   // height → ~1 unit
        const pos = new Float32Array(outN * 3), col = new Float32Array(outN * 3);
        for (let j = 0, i = 0; j < outN; j++, i += stride) {
            pos[j * 3]     = (sp.positions[i * 3]     - cx) * s;
            pos[j * 3 + 1] = (sp.positions[i * 3 + 1] - cy) * s;
            pos[j * 3 + 2] = (sp.positions[i * 3 + 2] - cz) * s;
            if (sp.colors) { col[j * 3] = sp.colors[i * 3]; col[j * 3 + 1] = sp.colors[i * 3 + 1]; col[j * 3 + 2] = sp.colors[i * 3 + 2]; }
            else { col[j * 3] = 0.7; col[j * 3 + 1] = 0.8; col[j * 3 + 2] = 0.95; }
        }
        console.log(`[splat] baked ${outN} of ${N} gaussians (stride ${stride})`);
        return { positions: pos, colors: col, count: outN };
    },
    // v1014 — bake the current splat + drop it into the avatar room (the KPop
    // panel diorama) as a grabbable the avatar can fetch. splat.bakeToRoom().
    bakeToRoom: (opts = {}) => {
        const baked = window.splat.bake(opts.src, opts);
        if (!baked) return null;
        const ifr = document.querySelector('iframe[src*="avatarstage"]');
        if (!ifr || !ifr.contentWindow) { console.warn("[splat] bakeToRoom: the avatar panel isn\'t open (pip.show())"); return baked; }
        ifr.contentWindow.postMessage({ type: "grab:add", splat: { positions: baked.positions, colors: baked.colors }, x: (typeof opts.x === "number" ? opts.x : -0.35) }, "*");
        console.log("[splat] baked splat handed to the avatar room as a grabbable");
        return baked;
    },
    /**
     * v4195 -- WRITE a loaded splat back out as .ply or .splat. The export half: until now this tree could
     * read four splat formats and produce none of them, so a scene loaded here could never leave.
     *
     * *** COLOUR IS THE ONE FIELD THAT DOES NOT SURVIVE A ROUND TRIP, AND IT IS WORTH SAYING SO HERE. ***
     * engine/splatParser.js CLAMPS f_dc to a displayable 0..1 on the way in, so a splat whose coefficient
     * saturated cannot be recovered: 0.5 + SH_C0 * 9.0 clamps to 1.0, and the inverse of 1.0 is 1.773.
     * Measured on the gate's fixture: 1.5e-7 worst error where the colour did not saturate, 7.23 where it
     * did. Position, scale, rotation and opacity are byte-exact. Higher SH bands were never read at all
     * (f_rest_*, 45 floats a splat), so they are not written either -- this exports what it imported.
     */
    save: (src, opts = {}) => {
        let sr = src;
        if (src == null) sr = _activeSplats[_activeSplats.length - 1];
        else if (typeof src === "number") sr = _activeSplats[src];
        const sp = (sr && sr.splat) || sr;
        if (!sp || !sp.positions || !sp.quats) { console.warn("[splat] save: no loaded splat with a shader-convention struct"); return null; }
        const gaussians = fromShaderConvention(sp);
        const fmt = (opts.format || "ply").toLowerCase();
        const bytes = fmt === "splat" ? writeSplat(gaussians)
                                      : writePly(gaussians, { format: opts.plyFormat || "binary_little_endian" });
        console.log(`[splat] wrote ${gaussians.length} gaussians as .${fmt} (${bytes.length} bytes)`);
        if (opts.download !== false && typeof document !== "undefined") {
            const a = document.createElement("a");
            a.href = URL.createObjectURL(new Blob([bytes], { type: "application/octet-stream" }));
            a.download = opts.name || `swek-splat.${fmt}`;
            a.click();
            setTimeout(() => URL.revokeObjectURL(a.href), 10000);
        }
        return bytes;
    },
    list: () => _activeSplats.slice(),
    clear: () => {
        for (const sp of _activeSplats) {
            try { sp.dispose(); } catch {}
        }
        _activeSplats.length = 0;
        console.log("[splat] cleared all");
    },
    remove: (sr) => {
        const i = _activeSplats.indexOf(sr);
        if (i >= 0) {
            try { sr.dispose(); } catch {}
            _activeSplats.splice(i, 1);
        }
    },
};
console.log("[SPLAT] ready — drop a .ply/.splat: splat.load('http://.../scene.ply')");

// v4199 — DOM DISINTEGRATION. ui/domToTexture.js rasterises a live subtree (v4120, and it refused
// html2canvas by name); ui/domDisintegrate.js samples that into ui/gestureVfx.js's own particles, colour and
// all. Console: domFx.disintegrate(document.querySelector('#someHud')).
window.domFx = {
    /** @returns { particles, canvas, why } -- `why` is non-null ONLY when the list is empty, so an empty
     *  result names its cause instead of being a silent nothing. */
    disintegrate: async (el, opts = {}) => {
        const target = typeof el === "string" ? document.querySelector(el) : el;
        if (!target) { console.warn("[domFx] no such element:", el); return null; }
        const out = await disintegrate(target, opts);
        if (!out.particles.length) console.warn("[domFx] no particles —", out.why);
        else console.log(`[domFx] ${out.particles.length} particles from`, target);
        return out;
    },

    // v4202 — LIQUEFY. render/liquefyModel.mjs holds a displacement field that REMEMBERS: strokes push
    // pixels, and the push decays back to nothing. Every other displacement in this engine — the five
    // radial shaders of v4196 among them — recomputes itself from `time` and animates forever. This one
    // settles, and PROVES it has settled: lq.probe() is !isQuiet(field), which is exactly the
    // level-triggered source engine/frameDirty.js wants. Console: domFx.liquefy('#hud').
    liquefy: async (el, opts = {}) => {
        const target = typeof el === "string" ? document.querySelector(el) : el;
        if (!target) { console.warn("[domFx] no such element:", el); return null; }
        const out = await liquefyElement(target, opts);
        if (!out.liquefy) { console.warn("[domFx] no liquefy —", out.why); return out; }
        target.parentNode?.insertBefore(out.canvas, target.nextSibling);
        console.log(`[domFx] liquefy ready on a ${out.canvas.width}x${out.canvas.height} canvas — drag it. ` +
                    `lq.probe() is the frameDirty source; lq.destroy() removes every listener.`);
        return out;
    },
};
console.log("[DOMFX] ready — domFx.disintegrate('#hud') turns an element into coloured particles, " +
            "domFx.liquefy('#hud') lets you smudge one");

// v4201 — INVERT ANY PURE FUNCTION. math/inverseSolve.mjs finds inputs that produce a wanted output, using
// only evaluations — no derivative required, which is the whole point: nothing else in this engine has one
// written down. Idea from bijection/g9 (MIT), whose trick is that a draw function becomes draggable.
//
//   solveFor(([r, g]) => [r * 0.299 + g * 0.587], [0.5], [0, 0])   // which r,g hit that luma?
window.solveFor = (fn, target, start, opts = {}) => {
    if (typeof fn !== "function") { console.warn("[solve] first argument must be a function"); return null; }
    const r = solve(fn, target, start, opts);
    // *** THE RESIDUAL AND THE DEAD INPUTS ARE REPORTED, NOT JUST THE ANSWER. *** A solver that printed only
    // `x` would read as authoritative when it had stopped at a local minimum, and would say nothing about an
    // input that moved no output at all — which is tools/roundhouse/knobLiveness.mjs's "moves nothing", here
    // as a number rather than a verdict.
    const dead = r.sensitivity.map((v, i) => (v === 0 ? i : -1)).filter((i) => i >= 0);
    console.log(`[solve] ${r.ok ? "solved" : "DID NOT SOLVE"} — ${r.why}; residual ${r.residual.toExponential(3)} after ${r.iterations} iterations`);
    console.log("[solve] x =", r.x, " sensitivity =", r.sensitivity);
    if (dead.length) console.log(`[solve] input(s) ${dead.join(", ")} moved NOTHING — they are not part of this answer`);
    return r;
};
window.sensitivityOf = (fn, at) => sensitivity(fn, at);
console.log("[SOLVE] ready — solveFor(fn, target, start) inverts any pure function; sensitivityOf(fn, at) says which inputs matter");

// v4203 — THE READ-AND-NOT-TAKEN REGISTER, REACHABLE. world/reachedLicences.mjs shipped at v4198 and
// nothing but its own gate imported it, so the one fact it exists to preserve — "we looked at this and
// chose not to vendor it, and here is why" — was unreadable without opening a source file. It is the
// counterpart to world/orrery.mjs, which can only see what WAS taken because its evidence is a file on disk.
//   licences.list()        every source, its licence posture and what (if anything) was taken
//   licences.quote(id)     a licence text with the URLs it was read from and its sha256
//   licences.drift()       the codrops finding: one licence restated, not two
window.licences = {
    list: () => {
        for (const e of REACHED_SOURCES) console.log(`  [${severityOf(e)} ${SEVERITY_NAMES[severityOf(e)]}] ${describeSource(e)}`);
        console.log(`[licences] ${REACHED_SOURCES.length} sources read and not vendored. ` +
                    `Severity is how FAR the restriction reaches, not how bad it is.`);
        return REACHED_SOURCES;
    },
    quote: (id) => {
        const q = LICENCE_TEXTS[id];
        if (!q) { console.warn("[licences] no such quotation:", id, "— try:", Object.keys(LICENCE_TEXTS).join(", ")); return null; }
        console.log(`[licences] ${id} — ${q.words} words, sha256 ${q.sha256.slice(0, 12)}, read ${q.retrieved}`);
        console.log(q.text);
        console.log("[licences] read it yourself:", q.sourceUrls.join("  "));
        return q;
    },
    drift: () => { const d = codropsDrift(); console.log("[licences]", d.verdict, d); return d; },
};
console.log("[LICENCES] ready — licences.list() shows every source read and not vendored, with why");

// v4204 — GL TRANSITION SPEC v1. A conforming transition is `vec4 transition(vec2 uv)` and may use
// progress, ratio, getFromColor(uv) and getToColor(uv) without declaring them; the host supplies all four.
// That is the whole portability story: the shader never binds a texture, so it cannot know whether it is
// running over two videos, two DOM rasterisations or two framebuffers. The spec and the validator were
// taken from gl-transitions (MIT); none of its 100 shaders were.
//   transitions.check(glsl)          what is wrong with it, before you spend a compile on it
//   transitions.make(gl, glsl)       a pass, or a refusal that says why
//   transitions.describe(glsl)       author, licence, and the parameters with their defaults
window.transitions = {
    check: (glsl) => {
        const problems = validateTransition(glsl);
        if (!problems.length) console.log("[transitions] conforms");
        else for (const p of problems) console.warn("[transitions] " + p);
        return problems;
    },
    make: (gl, glsl, opts = {}) => {
        const pass = makeTransitionPass(gl, glsl, opts);
        if (pass.error) console.warn("[transitions] " + pass.error + "\n  " + pass.problems.join("\n  "));
        return pass;
    },
    describe: (glsl) => {
        const t = parseTransition(glsl);
        console.log(`[transitions] ${t.meta.name || "unnamed"} by ${t.meta.author || "unknown"} (${t.meta.license || "no licence declared"})`);
        for (const p of t.params) console.log(`    ${p.type} ${p.name} = ${p.default === null ? "(supplied by the host)" : p.default}`);
        return t;
    },
};
console.log("[TRANSITIONS] ready — transitions.check(glsl) validates against the GL Transition spec before you compile it");

// v4205 — SHELLS. A projectile that FALLS: gravity, quadratic drag, and a launch solution with its two
// roots. For any reachable target there are normally TWO elevations that hit it — a FLAT one that arrives
// fast, and a LOB that goes high and drops steeply — and picking between them is the whole tactical content
// of a gun. They meet at maximum range, which is how you know you are at the edge of it.
//   shells.solve(range, rise, speed)     both elevations, or null when nothing reaches
//   shells.fire(range, rise, speed, o)   fly it and report where it actually lands
//   shells.envelope(speed, {drag})       the real max range, which drag cuts by more than half
//   shells.lead(sp, sv, tp, tv, speed)   aim from a MOVING shooter at a moving target
window.shells = {
    solve: (range, rise = 0, speed = 100, g = GRAVITY) => {
        const a = launchAngles(range, rise, speed, g);
        if (!a) { console.warn(`[shells] ${range} m is out of range at ${speed} m/s — max is ${maxRange(speed, rise, g).toFixed(1)} m`); return null; }
        const D = 180 / Math.PI;
        console.log(`[shells] flat ${(a.flat * D).toFixed(2)}° · lob ${(a.lob * D).toFixed(2)}°` + (a.grazing ? " · GRAZING, the roots have met" : ""));
        return a;
    },
    fire: (range, rise = 0, speed = 100, opts = {}) => {
        const a = launchAngles(range, rise, speed, opts.gravity || GRAVITY);
        if (!a) { console.warn("[shells] out of range"); return null; }
        const e = opts.prefer === "lob" ? a.lob : a.flat;
        const r = flyShell({ vx: speed * Math.cos(e), vy: speed * Math.sin(e) }, { groundY: rise, ...opts });
        console.log(`[shells] landed ${r.landed} at ${r.x.toFixed(2)} m after ${r.t.toFixed(2)} s, apex ${r.apex.toFixed(1)} m (wanted ${range} m)`);
        return r;
    },
    envelope: (speed = 100, opts = {}) => {
        const m = maxRangeDrag(speed, opts);
        console.log(`[shells] reach ${m.range.toFixed(1)} m at ${(m.elevation * 180 / Math.PI).toFixed(2)}°` +
                    (opts.drag ? ` — vacuum would say ${maxRange(speed).toFixed(1)} m, so drag takes ${(100 * (1 - m.range / maxRange(speed))).toFixed(1)}%` : " (vacuum, exact)"));
        return m;
    },
    reachable,
    solveElevation,
    lead: (sp, sv, tp, tv, speed) => {
        const r = leadMoving(sp, sv, tp, tv, speed);
        if (!r) { console.warn("[shells] no intercept — the target outruns the shell"); return null; }
        console.log(`[shells] intercept in ${r.t.toFixed(3)} s, aim ${r.aim.map((x) => x.toFixed(1)).join(", ")}`);
        return r;
    },
};
console.log("[SHELLS] ready — shells.solve(range) gives both launch angles; shells.envelope(v,{drag}) the real reach");

// v4206 — TWO GUNNERY BRAINS, ONE OCEAN. Each scores every unknown cell with a weight vector — the same
// shape brain/csTacticsPolicy.js uses for "which enemy does the brain shoot first?" — and fires a REAL
// shell, whose scatter comes from the trajectory rather than from a fudge factor.
//
// The measured finding is a negative one and worth knowing: density and hunt carry the whole result, while
// the ballistics-derived aim feature is worth nothing outside the noise. Knowing where the ship probably is
// beats knowing where the shell will certainly go.
//   naval.duel(seed)           one reproducible duel, hand policy vs blind
//   naval.series(n)            a record over n games, with the mean salvos each
//   naval.ablate(n)            what each feature is worth, against a measured noise floor
window.naval = {
    duel: (seed = 1, opts = {}) => {
        const d = duel(handWeights(), blindWeights(), seed, { v: 12.5, aimError: 2, ...opts });
        console.log(`[naval] seed ${seed}: hand ${d.a.salvos} salvos (${d.a.hits} hits, ${d.a.wasted} wasted) · ` +
                    `blind ${d.b.salvos} · winner ${d.winner}`);
        return d;
    },
    series: (games = 50, opts = {}) => {
        const s = series(handWeights(), blindWeights(), { games, v: 12.5, aimError: 2, ...opts });
        console.log(`[naval] ${games} games — hand ${s.meanSalvosA.toFixed(1)} salvos, blind ${s.meanSalvosB.toFixed(1)}, ${s.a}/${games} wins`);
        return s;
    },
    ablate: (games = 40, opts = {}) => {
        const H = handWeights(), o = { games, v: 12.5, aimError: 2, ...opts };
        const means = [1, 101, 201, 301].map((seed0) => series(H, H, { ...o, seed0 }).meanSalvosA);
        const mu = means.reduce((a, b) => a + b) / means.length;
        const sd = Math.sqrt(means.reduce((a, b) => a + (b - mu) ** 2, 0) / (means.length - 1));
        console.log(`[naval] noise floor ${(2 * sd).toFixed(1)} salvos (sd ${sd.toFixed(2)} across ${means.length} blocks) — read every delta against this`);
        const out = {};
        for (const [name, w] of [["density", { ...H, wDensity: 0 }], ["hunt", { ...H, wHunt: 0 }],
                                 ["aim", { ...H, wAim: 1.5 }], ["parity", { ...H, wParity: 0.35 }]]) {
            let t = 0;
            for (const seed0 of [1, 101, 201]) { const s = series(H, w, { ...o, seed0 }); t += s.meanSalvosB - s.meanSalvosA; }
            out[name] = t / 3;
            console.log(`[naval]   ${name.padEnd(8)} ${(t / 3).toFixed(1).padStart(6)} salvos  ${Math.abs(t / 3) > 2 * sd ? "REAL" : "within noise"}`);
        }
        return { floor: 2 * sd, ...out };
    },
    handWeights, blindWeights, untunedWeights, chooseShot,
};
console.log("[NAVAL] ready — naval.series() duels two gunnery brains; naval.ablate() says which features actually matter");

// v4207 — WGSL CONFORMANCE, in the same mould as v4204's GL Transition check: read the shader, check it
// against the contract, refuse it BEFORE a compile is spent. Sharper here than for GLSL, because WGSL can
// only be compiled by a live WebGPU device — so a shader in this repository was, statically, unchecked.
// It found three: scan.wgsl, mb-scan-blocks.wgsl and fused-single-workgroup.wgsl each ask for
// @workgroup_size(1024), four times the default maxComputeInvocationsPerWorkgroup, and nothing in this tree
// ever passes requiredLimits.
//   wgsl.check(src)          what is wrong with it, against the recorded default limits
//   wgsl.check(src, limits)  ...or against a real device's, e.g. wgsl.check(src, device.limits)
//   wgsl.limits()            the recorded defaults AND how they were sourced, which is the honest half
window.wgsl = {
    check: (src, limits) => {
        const problems = validateWgsl(src, limits ? { limits } : {});
        if (!problems.length) console.log("[wgsl] conforms" + (limits ? " against the limits you passed" : " against the recorded defaults"));
        else for (const p of problems) console.warn("[wgsl] " + p);
        return problems;
    },
    parse: (src) => {
        const p = parseWgsl(src);
        for (const e of p.entryPoints) console.log(`[wgsl] @${e.stage} ${e.name}` + (e.workgroupSize ? ` workgroup_size ${JSON.stringify(e.workgroupSize)}` : ""));
        for (const b of p.bindings) console.log(`[wgsl]   @group(${b.group}) @binding(${b.binding}) ${b.addressSpace}${b.access ? "," + b.access : ""} ${b.name}: ${b.type}`);
        return p;
    },
    limits: () => {
        console.log("[wgsl] recorded defaults:", DEFAULT_LIMITS);
        console.warn(`[wgsl] provenance: ${LIMITS_PROVENANCE.source} — verified against spec: ${LIMITS_PROVENANCE.verifiedAgainstSpec}, ` +
                     `against a device: ${LIMITS_PROVENANCE.verifiedAgainstDevice}. ${LIMITS_PROVENANCE.why}`);
        // v4407 -- THIS LINE USED TO ADVERTISE A CAPABILITY THE FRONT DOOR DID NOT USE. It printed "this
        // browser HAS WebGPU" and main.js reached no WebGPU code at all: measured with the tree's own
        // resolver, 692 modules reached and not one of gfx/device.js, render/tslSource.mjs, the six TSL
        // modules, ui/orreryPost.mjs or ui/webrtxBrowser.js. It now points at the door that does use it, and
        // it distinguishes WITHHELD from ABSENT, because navigator.gpu being undefined means both.
        if (navigator.gpu) console.log("[wgsl] this browser HAS WebGPU — window.gfx.open() opens it, and " +
            LIMITS_PROVENANCE.checkWith + " compares these numbers against it");
        else console.log("[wgsl] no navigator.gpu here — window.gfx.why() says whether that is your BROWSER " +
            "or your ADDRESS, which have different fixes");
        return { DEFAULT_LIMITS, LIMITS_PROVENANCE };
    },
    cannotDo: () => { for (const l of WGSL_LIMITS) console.log("[wgsl] LIMIT: " + l); return WGSL_LIMITS; },
};
console.log("[WGSL] ready — wgsl.check(src) validates WGSL without a GPU; wgsl.limits() says where its numbers came from");

// ---- v4407: THE FRONT DOOR REACHES THE DEVICE -----------------------------------------------------------------
//
// gfx/frontDoor.mjs is imported LAZILY, which is main.js's own idiom (123 other await import() sites) and is
// what keeps the cost at zero for a session that never asks. The reach is still real: tools/ship/moduleRefs.mjs
// counts a dynamic import as a route, so the import graph now runs main.js -> gfx/frontDoor.mjs -> gfx/device.js
// where before it stopped at main.js.
//
// WHAT IT DELIBERATELY DOES NOT DO: replace the render path. The default renderer is untouched. This is a door,
// on the pattern window.fire and window.repoTerrain already use, because on the origin the engine ships from
// there is no WebGPU to render with -- and a round that rerouted the front door before saying that out loud
// would make the LAN worse to fix the localhost.
window.gfx = {
    /** Open the device and report honestly. Returns the door's verdict; safe to call twice. */
    open: async (opts = {}) => {
        const d = await import("./gfx/frontDoor.mjs");
        const r = await d.open(opts);
        console.log("[gfx] " + (r.ready ? "backend " + r.backend : "no device") +
                    (r.why ? " — " + r.why : " — WebGPU present and used"));
        return r;
    },
    /** Why the better backend did not answer, in the terms that fix it. Opens the door if it is shut. */
    why: async () => {
        const d = await import("./gfx/frontDoor.mjs");
        const r = d.status() || await d.open();
        console.log("[gfx] origin " + (r.origin && r.origin.origin) + " secure=" + (r.origin && r.origin.secure));
        console.log("[gfx] webgpu is " + (r.state && r.state.webgpu) + ", webgl2 is " + (r.state && r.state.webgl2));
        if (r.why) console.log("[gfx] " + r.why);
        return r;
    },
    /** The origin verdict alone -- no adapter asked for, which is the order that stops v4118's mistake. */
    origin: async () => (await import("./gfx/frontDoor.mjs")).originVerdict(window),
};
console.log("[gfx] ready — window.gfx.open() reaches gfx/device.js; window.gfx.why() names the ADDRESS when " +
            "that is the reason rather than the machine");

// v4209 — FIREWORKS AS SHELLS. A firework is ONE ballistic object (v4205) that flies, decides a moment, and
// becomes many. Every star is then a ballistic body of its own, which is what lets a crossette break AGAIN —
// something a spawn-at-a-point particle system cannot express. The stars inherit the shell's velocity, so a
// rising shell carries the whole flower up with it instead of leaving a decal pinned in the air.
//   fireworks.launch(speed, opts)   fly a shell and burst it; reports if it never reached its fuse altitude
//   fireworks.patterns()            the six shell types and what makes each different
//   fireworks.sky(n)                n shells at assorted speeds, for a console-side show
window.fireworks = {
    launch: (speed = 55, opts = {}) => {
        const r = launchShell([0, 0, 0], [opts.drift ?? 0, speed, 0], { pattern: "peony", altitude: 40, ...opts });
        if (!r.burstAt) { console.warn("[fireworks] no burst — " + r.why); return r; }
        console.log(`[fireworks] ${opts.pattern || "peony"} burst at ${r.burstAt.y.toFixed(1)} m after ${r.burstAt.t.toFixed(2)} s ` +
                    `— ${r.stars.length} stars, apex ${r.apex.toFixed(1)} m`);
        if (r.shortOfFuse) console.warn(`[fireworks] it never reached its ${opts.altitude ?? 40} m fuse: short by ${r.shortBy.toFixed(1)} m, so it burst at apex`);
        return r;
    },
    step: stepStars,
    patterns: () => {
        for (const n of PATTERN_NAMES) {
            const p = PATTERNS[n];
            console.log(`[fireworks] ${n.padEnd(14)} ${String(p.n).padStart(3)} stars · ${p.speed} m/s · ${p.life}s life · drag ${p.drag}` +
                        (p.breakAfter ? ` · breaks into ${p.breakInto} at ${p.breakAfter}s` : ""));
        }
        return PATTERN_NAMES;
    },
    sky: (n = 5, opts = {}) => {
        const out = [];
        for (let i = 0; i < n; i++) {
            const pattern = PATTERN_NAMES[i % PATTERN_NAMES.length];
            out.push(window.fireworks.launch(45 + i * 6, { pattern, drift: (i - n / 2) * 3, ...opts }));
        }
        return out;
    },
    centroid, spreadRadius,
};
console.log("[FIREWORKS] ready — fireworks.launch() flies a real shell; fireworks.patterns() lists the six");

// v1016 — clean-house avatar registry. Survives a .glb going missing: the
// requested avatar's rename + saved rotation are kept (keyed by url, never
// clobbered by the fallback rig), and re-apply when the file returns.
//   avatarRegistry.setName(url, "Cesium")   name it (shows on the diorama overlay)
//   avatarRegistry.listMissing()            which avatars are currently 404'ing
//   avatarRegistry.recheck()                drop the file back, then call this to reload in place
window.avatarRegistry = Object.assign(avatarRegistry, {
    recheck() {
        const ifr = document.querySelector('iframe[src*="avatarstage"]');
        if (ifr && ifr.contentWindow) { ifr.contentWindow.postMessage({ type: "remount" }, "*"); console.log("[avatarRegistry] recheck \u2014 remounting the KPop diorama"); }
        else console.warn("[avatarRegistry] recheck: open the KPop Listener panel first");
        return avatarRegistry.listMissing();
    },
});
console.log("[avatarRegistry] ready \u2014 rename/recheck a missing avatar: avatarRegistry.setName(url,name) / .recheck()");

// v1018 — selfie gallery: the avatar diorama (single or duo) posts each captured
// pose up here; store it (downscaled) and let window.selfieGallery.open() browse.
window.selfieGallery = selfieGallery;
window.addEventListener("message", (e) => {
    const m = e && e.data;
    if (m && m.type === "selfie:captured" && m.dataURL) {
        Promise.resolve(selfieGallery.add(m.dataURL, { scene: m.scene })).then(() => {
            try { document.querySelector('iframe[src*="avatarstage"]')?.contentWindow?.postMessage({ type: "selfie:saved", count: selfieGallery.count() }, "*"); } catch {}
        });
    } else if (m && m.type === "selfie:openGallery") { try { selfieGallery.open(); } catch {} }
});
console.log("[selfieGallery] ready \u2014 tap the avatar camera; browse with selfieGallery.open()");

// v348 — P3D mesh integration. Like splats, but for the Pixal3D .p3d
// mesh format (12B header + float32 verts + uint16 indices, low-VRAM
// pipeline output). Renderer is multi-entity: each loaded mesh becomes
// a world entity with its own transform.
import { P3dRenderer }   from "./engine/P3dRenderer.js";       // round 348
import { decodeP3D }     from "./engine/p3dFormat.js";          // round 348
import { analyzeMesh, getSharedPoolStats } from "./engine/meshQcAnalyzer.js";   // round 357
import { showQcBadge }   from "./ui/MeshQcBadge.js";              // round 357
const _p3dRenderer = glOk ? new P3dRenderer({ gl }) : null;   // v2777/8 - skip optional effect on null gl

/**
 * Default placement: ~10 units in front of the camera at eye height.
 * Same convention as window.splat.load.
 */
function _p3dDefaultPosition(opts) {
    if (opts.position) return opts.position.slice();
    return [
        (camera.position?.x ?? 0),
        (camera.position?.y ?? 5),
        (camera.position?.z ?? 0) - 10,
    ];
}

window.p3d = {
    /** Load a .p3d binary from a URL and add as a world entity. */
    load: async (url, opts = {}) => {
        console.log("[p3d] loading", url);
        const r = await fetch(url, { cache: "no-store" });
        if (!r.ok) throw new Error(`p3d fetch failed: ${r.status} ${url}`);
        const buf = await r.arrayBuffer();
        const decoded = decodeP3D(buf);   // throws on bad magic
        console.log(`[p3d] parsed ${decoded.numVerts} verts / ${decoded.numFaces} tris from ${url}`);
        const id = _p3dRenderer.add({
            mesh: { vertices: decoded.vertices, indices: decoded.indices },
            position: _p3dDefaultPosition(opts),
            rotation: opts.rotation ?? 0,
            scale:    opts.scale    ?? 1,
            color:    opts.color    ?? [0.55, 0.85, 0.65],
            name:     opts.name     ?? url.split("/").pop(),
        });
        console.log(`[p3d] added id=${id} at`, _p3dRenderer.entities.find(e => e.id === id).position);
        // v357 — QC analysis after a successful load
        if (opts.skipQc !== true) {
            analyzeMesh(decoded.vertices, decoded.indices)
                .then(qc => {
                    try { showQcBadge(`p3d:${url.split("/").pop()}`, qc, getSharedPoolStats()); }
                    catch (e) { console.warn("[meshQc] badge display failed:", e?.message ?? e); }
                })
                .catch(e => console.warn("[meshQc] analysis failed:", e?.message ?? e));
        }
        return id;
    },
    /** Add an already-parsed mesh ({vertices, indices}) — bypasses fetch. */
    add: (mesh, opts = {}) => {
        const id = _p3dRenderer.add({
            mesh,
            position: _p3dDefaultPosition(opts),
            rotation: opts.rotation ?? 0,
            scale:    opts.scale    ?? 1,
            color:    opts.color    ?? [0.55, 0.85, 0.65],
            name:     opts.name     ?? `inline-${Date.now()}`,
        });
        console.log(`[p3d] added inline mesh id=${id} (${mesh.vertices.length / 3} verts / ${mesh.indices.length / 3} tris)`);
        // v357 — opportunistic mesh QC in a worker. Auto-display badge
        // unless opts.skipQc is true. The Promise rejects silently so
        // QC failures never block the render path.
        if (opts.skipQc !== true) {
            analyzeMesh(mesh.vertices, mesh.indices)
                .then(qc => {
                    try { showQcBadge(`p3d:${opts.name || `id-${id}`}`, qc, getSharedPoolStats()); }
                    catch (e) { console.warn("[meshQc] badge display failed:", e?.message ?? e); }
                })
                .catch(e => console.warn("[meshQc] analysis failed:", e?.message ?? e));
        }
        return id;
    },
    list:   () => _p3dRenderer.list(),
    clear:  () => { const n = _p3dRenderer.clear(); console.log(`[p3d] cleared ${n}`); return n; },
    remove: (id) => { const ok = _p3dRenderer.remove(id); console.log(`[p3d] remove(${id}) = ${ok}`); return ok; },
    update: (id, patch) => _p3dRenderer.update(id, patch),
    /** v354 — { drawn, culled, total } from the last render call */
    getCullStats: () => _p3dRenderer.getCullStats(),
};
console.log("[P3D] ready — load a .p3d: p3d.load('http://127.0.0.1:8188/view?filename=mesh.p3d')");

// v359 — direct console access to the mesh QC analyzer for testing
window.meshQc = {
    analyze: (positions, indices) => analyzeMesh(positions, indices),
    show:    (name, qc) => showQcBadge(name, qc, getSharedPoolStats()),
    poolStats: () => getSharedPoolStats(),
};

// v359 — world seed console API. Inspect / change the seed that
// CaveCarver + BiomeDecorPool (+ future generators) share. Set or
// regenerate, then reload to apply.
window.worldSeed = (async () => {
    const mod = await import("./engine/worldSeed.js");
    return {
        get:        () => mod.getWorldSeed(),
        set:        (n) => mod.setWorldSeed(n),
        regenerate: () => mod.regenerateSeed(),
    };
})();
// Resolve immediately so `worldSeed.get()` works after a tick
window.worldSeed.then(api => { window.worldSeed = api; });

// v362 — voice translation console API. Direct text-to-text translate
// via LibreTranslate, plus speech synthesis convenience.
