window.voice.then(api => { window.voice = api; });

// v365 — WAD parsing console API. Drop a WAD file via fetch+arrayBuffer
// and inspect it. Used by the v366 voxelizer + v367 texture extraction.
//   const buf = await fetch("/freedoom1.wad").then(r => r.arrayBuffer())
//   wad.parse(buf) → { magic, numLumps, lumps, maps }
//   wad.listMaps(wadFile) → ["E1M1", "E1M2", ...]
//   wad.dumpMap(wadFile, "E1M1") → { vertices, sectors, things, ... }
window.wad = (async () => {
    const mod = await import("./tools/wadLoader.js");
    const vox = await import("./tools/wadVoxelizer.js");
    const tex = await import("./tools/wadTextures.js");
    const wtex = await import("./tools/wadWallTextures.js");
    const mat = await import("./tools/wadMaterialPresets.js");
    const things = await import("./tools/wadThings.js");
    const wadThingSpawner = await import("./tools/wadThingSpawner.js");   // v412
    const sprites = await import("./tools/wadSprites.js");
    const thingSprites = await import("./tools/wadThingSprites.js");
    const billboards = await import("./tools/wadBillboards.js");
    const paletteSwap = await import("./tools/wadPaletteSwap.js");
    const animTex     = await import("./tools/wadAnimatedTextures.js");
    const sectorFx    = await import("./tools/wadSectorEffects.js");
    const wallAtlas   = await import("./tools/wadWallAtlas.js");
    return {
        parse:    (buf) => mod.WAD.parse(buf),
        parseMap: (wadFile, name, opts) => mod.WAD.parseMap(wadFile, name, opts),
        listMaps: (wadFile) => mod.WAD.listMaps(wadFile),
        dumpMap:  (wadFile, name) => mod.WAD.dumpMap(wadFile, name),
        THING_TYPES: mod.THING_TYPES,
        voxelize: (parsedMap, opts = {}) => {
            const result = vox.voxelizeWadMap(world, parsedMap, opts);
            if (opts.movecamera !== false && result.playerStart && window.camera) {
                if (window._safeMoveCamera) {
                    window._safeMoveCamera(window.camera,
                        result.playerStart.x,
                        result.playerStart.y,
                        result.playerStart.z);
                } else {
                    window.camera.position.x = result.playerStart.x;
                    window.camera.position.y = result.playerStart.y;
                    window.camera.position.z = result.playerStart.z;
                }
            }
            console.log(`[wad.voxelize] ${parsedMap.name}: ${result.wallVoxelsWritten} wall voxels, ${result.floorVoxelsWritten} floor voxels, ${result.textureLookups ?? 0} texture lookups`);
            return result;
        },
        voxelizeWadMap: vox.voxelizeWadMap,
        buildSectorPolys: vox.buildSectorPolys,
        pointInPolygon:   vox.pointInPolygon,
        palette:    (wadFile, idx) => tex.extractPalette(wadFile, idx ?? 0),
        colormap:   (wadFile) => tex.extractColormap(wadFile),
        listFlats:  (wadFile) => tex.listFlats(wadFile),
        flat:       (wadFile, name, pal) => tex.extractFlat(wadFile, name, pal),
        allFlats:   (wadFile, pal) => tex.extractAllFlats(wadFile, pal),
        walls:      (wadFile) => tex.locateWallTextures(wadFile),
        wallTexture:      (wadFile, name, pal) => wtex.decodeWallTexture(wadFile, name, pal ?? tex.extractPalette(wadFile, 0)),
        allWallTextures:  (wadFile, pal) => wtex.decodeAllWallTextures(wadFile, pal ?? tex.extractPalette(wadFile, 0)),
        wallTextureNames: (wadFile) => wtex.listWallTextureNames(wadFile),
        decodePatch:      wtex.decodePatch,
        defaultWallMaterial:  mat.defaultWallMaterial,
        defaultFloorMaterial: mat.defaultFloorMaterial,
        materials:             mat.WAD_DEFAULT_MATERIALS,
        things:           (parsedMap, opts) => things.thingsToPlacements(parsedMap, opts),
        thingsByKind:     (parsedMap, opts) => things.groupPlacementsByKind(things.thingsToPlacements(parsedMap, opts)),
        // v412 (WAD round) — spawn a map's MONSTER things as live kaiju.
        // Doom monster placements become an actual kaiju encounter on the
        // voxelized geometry, reusing the engine's entity rendering + AI
        // instead of a separate Doom sprite pass.
        //   const p = wad.things(map, { includeSpawns:false });
        //   wad.spawnThingsAsKaiju(p, { maxKaiju: 24 });
        //   wad.previewThingSpawn(p);   // → { total, byKind, byLabel }
        spawnThingsAsKaiju: (placements, opts) =>
            wadThingSpawner.spawnWadThingsAsKaiju(placements, kaijuManager, opts),
        previewThingSpawn:  (placements, opts) =>
            wadThingSpawner.previewWadThingSpawn(placements, opts),
        monsterToKaijuMap:  wadThingSpawner.getMonsterMap,
        thingHistogram:   (parsedMap, opts) => things.thingHistogram(parsedMap, opts),
        classifyThing:    things.classifyThing,
        THING_FLAG:       things.THING_FLAG,
        // v380 — sprite lump decoding. Reuses v377's picture format parser.
        //   wad.spriteNames(wadFile)                              → ["TROO", "POSS", ...]
        //   wad.spriteFrame(wadFile, "TROO", "A", 1, pal)        → {width, height, rgba}
        //   wad.spriteSet(wadFile, "TROO", pal)                    → Map<"A1", {...}>
        //   wad.spriteAnim(wadFile)                                  → {TROO:["A","B",...], ...}
        //   wad.spriteForThing(3001)                                  → "TROO"
        spriteNames:    sprites.listSpriteNames,
        spriteFrame:    (wadFile, name, frame, rotation, pal) =>
                          sprites.decodeSpriteFrame(wadFile, name, frame, rotation,
                                                       pal ?? tex.extractPalette(wadFile, 0)),
        spriteSet:      (wadFile, name, pal) =>
                          sprites.decodeSpriteSet(wadFile, name, pal ?? tex.extractPalette(wadFile, 0)),
        spriteAnim:     sprites.spriteAnimationMap,
        parseSpriteName: sprites.parseSpriteName,
        spriteForThing:  thingSprites.thingSpriteName,
        listThingSpriteMap: thingSprites.listThingSpriteMap,
        // v393 — billboard manager for sprite rendering.
        //   const bm = wad.createBillboardManager();
        //   wad.bulkRegisterSprites(bm, wadFile);
        //   bm.spawnFromPlacements(wad.things(map), wad.spriteForThing,
        //                            { unitsPerVoxel: 16 });
        //   ...each frame: bm.prepareFrame(window.camera) → quad list
        BillboardManager: billboards.BillboardManager,
        createBillboardManager: (opts) => new billboards.BillboardManager(opts),
        bulkRegisterSprites: (bm, wadFile, pal) => {
            const decoder = (name, frame, rot) =>
                sprites.decodeSpriteFrame(wadFile, name, frame, rot,
                                             pal ?? tex.extractPalette(wadFile, 0));
            const names = sprites.listSpriteNames(wadFile);
            const { registeredCount } = billboards.registerWadSprites(
                decoder, names, { manager: bm });
            // The helper builds its own manager; we want frames in
            // the caller's. Re-register via the supplied bm instead.
            let n = 0;
            for (const name of names) {
                for (const f of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") {
                    for (let r = 0; r <= 8; r++) {
                        const data = decoder(name, f, r);
                        if (data) { bm.registerFrame(name, f, r, data); n++; }
                    }
                }
            }
            return n;
        },
        // v394 — PLAYPAL → engine material swap. The voxelize
        // material picker can route texture names → a representative
        // palette color, giving Doom maps the Doom palette without
        // pixel-perfect texture atlasing.
        //   const pal = wad.palette(wadFile);
        //   const mats = wad.paletteToMaterials(pal, 100);   // 256 materials at ids 100..355
        //   const lookup = wad.buildFlatColorLookup(wadFile, pal, 100);
        //   wad.voxelize(map, { floorTextureMap: lookup });
        paletteToMaterials:  paletteSwap.paletteToMaterials,
        dominantColor:        paletteSwap.dominantColor,
        averageColor:          paletteSwap.averageColor,
        colorForFlatName:      (wadFile, name, pal) =>
                                  paletteSwap.colorForFlatName(tex.extractFlat, wadFile, name, pal),
        mixWithLight:           paletteSwap.mixWithLight,
        closestPaletteIndex:    paletteSwap.closestPaletteIndex,
        buildFlatColorLookup:    (wadFile, pal, baseMatId) =>
                                    paletteSwap.buildFlatColorLookup(
                                        { flat: tex.extractFlat }, wadFile, pal, baseMatId),
        // v395 — sector-light tint callback for voxelize. Produces a
        // function that routes (matId, sector) → dim PLAYPAL entry id.
        //   const tint = wad.buildSectorLightTint(pal, 100);
        //   wad.voxelize(map, { sectorLightTint: tint });
        buildSectorLightTint:    paletteSwap.buildSectorLightTint,
        // v396 — animated wall textures. Vanilla Doom cycles compiled
        // in; engine can register listeners that fire when a cycle
        // advances. Wire the listener body to update voxel material
        // colors via the engine's material registry.
        //   const anim = wad.createAnimator();
        //   anim.bind("NUKAGE1", (currentFrame) => updateMaterialColor(...));
        //   // in main loop: anim.tick(performance.now());
        TextureAnimator:     animTex.TextureAnimator,
        createAnimator:       (opts) => new animTex.TextureAnimator(opts),
        textureCycles:         animTex.DOOM_TEXTURE_CYCLES,
        cycleForTexture:        animTex.cycleForTextureName,
        isAnimatedTexture:       animTex.isAnimatedTexture,
        // v399 — sector specials (damage floors, secrets, flicker).
        //   const ctrl = new wad.SectorEffectController({
        //     map, getCameraSector: () => 0, onDamage: rate => ...
        //   });
        //   ...each frame: ctrl.tick(performance.now(), dt);
        SECTOR_SPECIAL:                sectorFx.SECTOR_SPECIAL,
        damageRateForSpecial:           sectorFx.damageRateForSpecial,
        isLightSpecial:                  sectorFx.isLightSpecial,
        isSecretSpecial:                  sectorFx.isSecretSpecial,
        SectorEffectController:            sectorFx.SectorEffectController,
        applyLightEffectMaterials:         (map, pal, opts) =>
            sectorFx.ApplyLightEffectMaterials(map, pal,
                { closestPaletteIndex: paletteSwap.closestPaletteIndex, ...opts }),
        // v400 — wall-texture atlas. Pack every wall texture into a
        // single RGBA buffer, register one material per texture into
        // the global registry with atlas UV box as metadata, and
        // return a (texName) → matId function the voxelizer's
        // wallTextureMap option consumes directly.
        //   const atlas = wad.buildWallAtlas(wadFile);
        //   wad.voxelize(map, { wallTextureMap: atlas.matIdFor });
        //   uploadAtlasToGPU(atlas.rgba, atlas.width, atlas.height);
        buildWallAtlas:        (wadFile, pal, opts) =>
            wallAtlas.buildWallAtlas(wadFile, pal ?? tex.extractPalette(wadFile, 0),
                { decodeWallTexture: wtex.decodeWallTexture,
                   wallTextureNames: wtex.listWallTextureNames(wadFile),
                   ...opts }),
    };
})();
window.wad.then(api => { window.wad = api; });

