// v368 — Audio bus (Web Audio API). Replaces the absent JS-side audio
// and bypasses the broken winmm.dll VBA path. 8 synth voices ship in
// code (no asset bundling needed); register URLs for sampled SFX.
//   audio.play("happy")                     — synth voice
//   audio.playSpatial("ping", x, y, z)     — 3D HRTF panning
//   audio.register("door", "/sfx/door.wav")
//   await audio.preload("door")
//   audio.setVolume(0.4); audio.setMuted(true)
window.audio = (async () => {
    const mod = await import("./engine/audioBus.js");
    const bus = mod.getAudioBus();
    return {
        play:        (name, opts) => bus.play(name, opts),
        playSpatial: (name, x, y, z, opts) => bus.playSpatial(name, x, y, z, opts),
        register:    (name, urlOrBuffer) => bus.register(name, urlOrBuffer),
        preload:     (name) => bus.preload(name),
        setVolume:   (v) => bus.setVolume(v),
        getVolume:   () => bus.getVolume(),
        setMuted:    (b) => bus.setMuted(b),
        isMuted:     () => bus.isMuted(),
        listVoices:  () => bus.listVoices(),
        // v913/v914 — play an arbitrary audio file (e.g. a pipeline-generated
        // MusicGen/AudioGen/Bark clip, or any URL/data-URL) through the engine
        // bus. Must register + preload the buffer before play (play() only
        // sounds from loaded buffers, else it falls back to a synth ping).
        playClip:    async (url, opts) => { try { const nm = "_clip_" + Date.now(); await bus.register(nm, url); await bus.preload(nm); return bus.play(nm, opts); } catch (e) { return null; } },
        // v914 — set a clip as the looping ambient track (stops any prior one).
        setAmbientClip: async (url, opts) => { try { const nm = "_amb_" + Date.now(); await bus.register(nm, url); const ok = await bus.preload(nm); if (!ok && !bus._buffers.has(nm)) return false; return bus.loopClip(nm, opts); } catch (e) { return false; } },
        stopAmbient: () => { try { bus.stopAmbient(); } catch {} },
        bus,
    };
})();
window.audio.then(api => { window.audio = api; });

// v376 — Perf dashboard console API. Toggle the live perf HUD.
//   perf.show() / perf.hide() / perf.toggle()
