//   perf.history() — snapshot of frame-time + section history ring buffers
window.perf = {
    show:    () => window._perfDashboard?.show?.(),
    hide:    () => window._perfDashboard?.hide?.(),
    toggle:  () => window._perfDashboard?.toggle?.(),
    sample:  () => window._perfDashboard?._sample?.(),
    history: () => window._perfDashboard?._history?.(),
};

// v1290 — extra metrics line for the live perf HUD (PerfHudLive reads this if present):
// system load (CPU/GPU/mem from systemPerf) + chunk-streamer numbers. Defensive so a
// missing source just drops its line. Returns a small HTML string.
window._perfExtra = () => {
    const parts = [];
    try {
        const s = window.systemPerf?.snapshot?.();
        if (s) {
            const cpu = Math.round((s.cpuLoad01 || 0) * 100);
            const gpu = (s.gpuLoad01 != null) ? Math.round(s.gpuLoad01 * 100) + "%" : "n/a";
            const mem = (s.memUsedMB != null) ? Math.round(s.memUsedMB) + " MB" : "n/a";
            parts.push(`cpu ${cpu}% · gpu ${gpu} · mem ${mem}`);
            if ((s.errorsRecent | 0) || (s.warnsRecent | 0)) parts.push(`err ${s.errorsRecent | 0} · warn ${s.warnsRecent | 0}`);
        }
    } catch (e) {}
    try {
        const cs = (typeof chunkStreamer !== "undefined") ? chunkStreamer.stats?.() : null;
        if (cs && typeof cs === "object") {
            const k = Object.keys(cs).filter(key => typeof cs[key] === "number").slice(0, 5).map(key => `${key} ${cs[key]}`);
            if (k.length) parts.push(k.join(" · "));
        }
    } catch (e) {}
    return parts.map(p => `<div>${p}</div>`).join("");
};

// v349 — OVM (.ovm sparse voxel) integration. Same pattern as splat/p3d:
// multi-entity world renderer + window.ovm console API. Dual-grid offsets
// and AO bitmask carry through; shadow mapping doesn't (main world has
// its own shadow path on TEXTURE3).
import { OvmRenderer }    from "./engine/OvmRenderer.js";          // round 349
import { decodeOVM }      from "./engine/ovmFormat.js";              // round 349
import { computeAOBitmasks as _computeOvmAO } from "./engine/ovmGenerator.js";  // round 349
const _ovmRenderer = new OvmRenderer({ gl });

function _ovmDefaultPosition(opts) {
    if (opts.position) return opts.position.slice();
    return [
        (camera.position?.x ?? 0),
        (camera.position?.y ?? 5),
        (camera.position?.z ?? 0) - 10,
    ];
}

window.ovm = {
    /** Load a .ovm binary from a URL and add as a sparse-voxel world entity. */
    load: async (url, opts = {}) => {
        console.log("[ovm] loading", url);
        const r = await fetch(url, { cache: "no-store" });
        if (!r.ok) throw new Error(`ovm fetch failed: ${r.status} ${url}`);
        const buf = await r.arrayBuffer();
        const asset = decodeOVM(buf);
        // The .ovm format doesn't bake AO into the file (it's purely a
        // function of coords). Compute it once on load so subsequent
        // re-renders use it.
        asset.aoBitmasks = _computeOvmAO(asset.coords, asset.count);
        console.log(`[ovm] parsed ${asset.count} voxels from ${url}, AO computed`);
        const id = _ovmRenderer.add({
            asset,
            position:   _ovmDefaultPosition(opts),
            rotation:   opts.rotation   ?? 0,
            scale:      opts.scale      ?? 1,
            voxelScale: opts.voxelScale ?? 1,
            tint:       opts.tint       ?? [1, 1, 1],
            name:       opts.name       ?? url.split("/").pop(),
        });
        console.log(`[ovm] added id=${id} at`, _ovmRenderer.entities.find(e => e.id === id).position);
        return id;
    },
    /** Add an already-decoded asset object — bypasses fetch. Computes AO
     *  if asset.aoBitmasks is missing. */
    add: (asset, opts = {}) => {
        if (!asset.aoBitmasks) {
            asset.aoBitmasks = _computeOvmAO(asset.coords, asset.count);
        }
        const id = _ovmRenderer.add({
            asset,
            position:   _ovmDefaultPosition(opts),
            rotation:   opts.rotation   ?? 0,
            scale:      opts.scale      ?? 1,
            voxelScale: opts.voxelScale ?? 1,
            tint:       opts.tint       ?? [1, 1, 1],
            name:       opts.name       ?? `inline-${Date.now()}`,
        });
        console.log(`[ovm] added inline asset id=${id} (${asset.count} voxels)`);
        return id;
    },
    list:   () => _ovmRenderer.list(),
    clear:  () => { const n = _ovmRenderer.clear(); console.log(`[ovm] cleared ${n}`); return n; },
    remove: (id) => { const ok = _ovmRenderer.remove(id); console.log(`[ovm] remove(${id}) = ${ok}`); return ok; },
    update: (id, patch) => _ovmRenderer.update(id, patch),
    /** v354 — { drawn, culled, total } from the last render call */
    getCullStats: () => _ovmRenderer.getCullStats(),
    /** v355 — globally toggle LoD on/off for all OVM entities */
    setLodEnabled: (enabled) => _ovmRenderer.setLodEnabled(enabled),
};
console.log("[OVM] ready — load a .ovm: ovm.load('http://127.0.0.1:8188/view?filename=asset.ovm')");

