            const arg = String(m?.args || "").toLowerCase().trim();
            const rawArgs = String(m?.args || "").trim();
            const WEATHER = ["rain", "storm", "mist", "snow"];
            const CLOUDS  = ["cumulus", "cumulonimbus", "stratus", "stratocumulus", "cirrus", "nimbostratus"];
            const TIME    = { day: "noon", night: "midnight", dawn: "dawn", dusk: "dusk", noon: "noon", morning: "morning", evening: "evening" };
            let did = null;
            if (WEATHER.includes(cmd)) { window.weather?.force?.(cmd); did = "weather → " + cmd; }
            else if (cmd === "clear") { window.weather?.clear?.(); window.clouds?.off?.(); did = "cleared"; }
            else if (cmd === "clouds") { if (!arg || arg === "off") { window.clouds?.off?.(); did = "clouds off"; } else if (CLOUDS.includes(arg)) { window.clouds?.set?.(arg); did = "clouds → " + arg; } }
            else if (TIME[cmd]) { window.dayNight?.[TIME[cmd]]?.(); did = "time → " + cmd; }
            else if (cmd === "kaiju") { if (arg === "off") { window.kaijuSim?.stop?.(); did = "kaiju off"; } else { window.kaijuSim?.start?.(); did = "kaiju on"; } }
            else if (["start", "launch", "run", "open"].includes(cmd) && arg) { fetch("/proc/start", { method: "POST", headers: { "Content-Type": "application/json", "x-proc-pin": (localStorage.getItem("voxelengine.procPin") || "") }, body: JSON.stringify({ id: arg }) }).catch(()=>{}); did = "start → " + arg; }
            else if (["stop", "kill", "quit"].includes(cmd) && arg) { fetch("/proc/stop", { method: "POST", headers: { "Content-Type": "application/json", "x-proc-pin": (localStorage.getItem("voxelengine.procPin") || "") }, body: JSON.stringify({ id: arg }) }).catch(()=>{}); did = "stop → " + arg; }
            else if (["restart", "reboot", "relaunch"].includes(cmd) && arg) { fetch("/proc/restart", { method: "POST", headers: { "Content-Type": "application/json", "x-proc-pin": (localStorage.getItem("voxelengine.procPin") || "") }, body: JSON.stringify({ id: arg }) }).catch(()=>{}); did = "restart → " + arg; }
            else if (["starfield", "sf", "game"].includes(cmd) && rawArgs) { fetch("/starfield/command", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ command: rawArgs }) }).catch(()=>{}); did = "starfield ⌘ " + rawArgs; }
