                    x: rampX + rand(-0.3, 0.3), y: cy + rand(1, 2.2), z: rampZ + rand(-1.5, 0.5),
                    vy: rand(-0.3, 0.3), vx: rand(-0.2, 0.2), vz: rand(-0.4, 0.4),
