const debrisRenderer = new DebrisRenderer(gl);
// v523 — in-world video wall on SCREEN(20) voxels, fed by the phone camera.
const screenWall = new ScreenWallRenderer(gl);
window.screenWall = {
    setSource: (s) => screenWall.setSource(s),
    rebuild:   () => screenWall.rebuild(world, Math.round(camera.position.x), Math.round(camera.position.z), 48),
    clear:     () => screenWall.clear(),
    placeWall: (opts = {}) => {
        const w = opts.width ?? 11, h = opts.height ?? 6, dist = opts.dist ?? 8;
        const yaw = camera.yaw || 0;
        const fx = -Math.sin(yaw), fz = -Math.cos(yaw);   // forward (yaw 0 = -Z)
        const rx = Math.cos(yaw), rz = -Math.sin(yaw);    // right
        const baseX = camera.position.x + fx * dist, baseZ = camera.position.z + fz * dist;
        let gy = 1; for (let y = 58; y >= 1; y--) { const v = world.voxelAt(Math.round(baseX), y, Math.round(baseZ)); if (v !== 0 && v !== 10 && v !== 11) { gy = y + 1; break; } }
        let placed = 0;
        for (let i = -(w >> 1); i <= (w >> 1); i++) {
            for (let j = 0; j < h; j++) {
                const wx = Math.round(baseX + rx * i), wz = Math.round(baseZ + rz * i), wy = gy + j;
                try { world.setVoxel(wx, wy, wz, 20); placed++; } catch {}
            }
        }
        const r = screenWall.rebuild(world, Math.round(camera.position.x), Math.round(camera.position.z), 48);
        try { window.kpop?.info?.("Screen wall", `${placed} screens · ${r.quads} faces — point a phone camera at it`); } catch {}
        return { placed, quads: r.quads };
    },
};
// v1056 — push a still picture or a looping video onto the in-world screen wall.
// showImage takes any image URL; showVideo plays a video element and re-uploads
// its frames onto the wall texture (~15fps), mirroring the IP-camera path.
window.screenWall._vid = null; window.screenWall._vloop = null;
window.screenWall.showImage = (url) => { try { window.screenWall.placeWall(); } catch {} screenWall.setSource(String(url || "")); return true; };
window.screenWall.showVideo = (url) => {
    try { window.screenWall.placeWall(); } catch {}
    let v = window.screenWall._vid;
    if (!v) { v = document.createElement("video"); v.crossOrigin = "anonymous"; v.loop = true; v.muted = true; v.playsInline = true; window.screenWall._vid = v; }
    v.src = String(url || ""); v.play().catch(() => {});
    const tick = () => { if (!window.screenWall._vid) return; try { if (v.readyState >= 2) screenWall.setSource(v); } catch {} window.screenWall._vloop = setTimeout(tick, 66); };
    clearTimeout(window.screenWall._vloop); tick();
    return true;
};
window.screenWall.stopVideo = () => { const v = window.screenWall._vid; if (window.screenWall._vloop) { clearTimeout(window.screenWall._vloop); window.screenWall._vloop = null; } if (v) { try { v.pause(); } catch {} v.src = ""; } return true; };
// v1048 — IP camera source. The bridge proxies the camera as a same-origin
// MJPEG stream (/camera/mjpeg); a hidden <img> consumes it and we re-upload the
// live frame onto the screen-wall texture ~12×/sec. window.ipCamera.start()
// also builds a wall in front of you if there isn't one. MJPEG cameras work
// with no extra software; RTSP needs ffmpeg on the bridge (handled server-side).
window.ipCamera = {
    _img: null, _loop: null, on: false,
    start(url) {
        if (!this._img) { this._img = new Image(); }
        try { window.screenWall.placeWall(); } catch {}   // v1152 — ensure a surface exists
        const qs = url ? ("?url=" + encodeURIComponent(url) + "&t=") : "?t=";
        this._img.src = "/camera/mjpeg" + qs + Date.now();
        this.on = true;
        const tick = () => {
            if (!this.on) return;
            try { if (this._img && this._img.naturalWidth > 0) screenWall.setSource(this._img); } catch {}
            this._loop = setTimeout(tick, 80);
        };
        clearTimeout(this._loop); tick();
        try { window.kpop?.info?.("IP camera", "Streaming onto the screen wall — window.ipCamera.stop() to end."); } catch {}
        return true;
    },
    stop() {
        this.on = false;
        if (this._loop) { clearTimeout(this._loop); this._loop = null; }
        if (this._img) this._img.src = "";
        return true;
    },
};
// v1155 — mirror the GPU terminal onto a screen wall in the world. A small
// floating terminal (an iframe of /terminal.html) is the interactive control you
// type into; its live canvas is re-uploaded onto the wall ~11×/sec, same texture
// path as the camera feed. So a real shell runs on a screen inside the 3D world.
window.terminalWall = function () {
    if (window.terminalWall._on) { try { window.terminalWall._box.style.outline = "2px solid #6fe0c8"; setTimeout(() => { if (window.terminalWall._box) window.terminalWall._box.style.outline = ""; }, 600); } catch {} return true; }
    try { window.screenWall.placeWall(); } catch {}
    const box = document.createElement("div");
    box.style.cssText = "position:fixed;right:14px;bottom:14px;width:380px;height:244px;z-index:99999;border:1px solid #2a3a4a;border-radius:8px;overflow:hidden;box-shadow:0 8px 30px rgba(0,0,0,.6);background:#06080c;";
    const hdr = document.createElement("div"); hdr.style.cssText = "height:22px;background:#0c1420;color:#7fd1ff;font:11px ui-monospace,monospace;display:flex;align-items:center;justify-content:space-between;padding:0 8px;";
    hdr.innerHTML = "<span>\u2328 terminal \u2192 wall (type here)</span>";
    const x = document.createElement("span"); x.textContent = "\u2715"; x.style.cssText = "cursor:pointer;color:#f88;"; hdr.appendChild(x);
    const ifr = document.createElement("iframe"); ifr.src = "/terminal.html"; ifr.style.cssText = "width:100%;height:calc(100% - 22px);border:0;display:block;";
    box.append(hdr, ifr); document.body.appendChild(box);
    let loop = null;
    const tick = () => {
        try { const doc = ifr.contentDocument; const cv = doc && (doc.querySelector(".xterm-screen canvas") || doc.querySelector("canvas")); if (cv && cv.width > 0) screenWall.setSource(cv); } catch {}
        loop = setTimeout(tick, 90);
    };
    ifr.addEventListener("load", () => { clearTimeout(loop); setTimeout(tick, 300); });
    const stop = () => { window.terminalWall._on = false; if (loop) clearTimeout(loop); try { box.remove(); } catch {} };
    x.addEventListener("click", stop);
    window.terminalWall._on = true; window.terminalWall._box = box; window.terminalWall._stop = stop;
    try { window.kpop?.info?.("Terminal", "Terminal mirrored onto the wall \u2014 type in the floating panel."); } catch {}
    return true;
};
window.terminalWall._on = false;
window.terminalWall.stop = () => { try { window.terminalWall._stop && window.terminalWall._stop(); } catch {} };
// v528 — build palette: the Builder role places voxels into the world, either
// in front of the Commander's camera (mode-based) or at an explicit x,z from a
// minimap tap. voxel 0 = erase.
window.builder = {
    place: (voxel, mode, at) => {
        voxel = voxel | 0; mode = mode || "block";
        let bx, bz;
        if (at && typeof at.x === "number") { bx = Math.round(at.x); bz = Math.round(at.z); }
        else {
            const yaw = camera.yaw || 0, fx = -Math.sin(yaw), fz = -Math.cos(yaw), d = 6;
            bx = Math.round(camera.position.x + fx * d); bz = Math.round(camera.position.z + fz * d);
        }
        const top = (x, z) => { for (let y = 62; y >= 0; y--) { const v = world.voxelAt(x, y, z); if (v !== 0 && v !== 10 && v !== 11) return y; } return 0; };
        let placed = 0;
        const set = (x, y, z, id) => { try { world.setVoxel(x, y, z, id); placed++; } catch {} };
        if (mode === "clear") {
            for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) set(bx + dx, top(bx + dx, bz + dz), bz + dz, 0);
        } else if (mode === "pillar") {
            const t = top(bx, bz); for (let i = 1; i <= 5; i++) set(bx, t + i, bz, voxel);
        } else if (mode === "platform") {
            for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) set(bx + dx, top(bx + dx, bz + dz) + 1, bz + dz, voxel);
        } else if (mode === "wall") {
            const yaw = camera.yaw || 0, rx = Math.cos(yaw), rz = -Math.sin(yaw);
            for (let i = -2; i <= 2; i++) { const x = Math.round(bx + rx * i), z = Math.round(bz + rz * i), t = top(x, z); for (let j = 1; j <= 3; j++) set(x, t + j, z, voxel); }
        } else {   // block (voxel 0 → erase the top solid)
            const t = top(bx, bz);
            if (voxel === 0) set(bx, t, bz, 0); else set(bx, t + 1, bz, voxel);
        }
        try { window.kpop?.info?.("Build", `${placed} voxel${placed !== 1 ? "s" : ""} @ ${bx},${bz}`); } catch {}
        if (placed) { const sname = voxel === 0 ? "break_dirt" : ({ 1: "place_stone", 2: "place_dirt", 3: "place_grass", 4: "place_sand", 5: "place_snow", 10: "place_water", 12: "place_lava", 20: "place_screen" }[voxel] || "place_stone"); _sfx(sname, 0.55); }   // v531
        return { placed, x: bx, z: bz };
    },
};
// v518 — buoyancy: floating debris drift on the water surface with the current.
