    raftHere: (n = 8, kind = "log") => { for (let i = 0; i < n; i++) floatingDebris.spawn(Math.round(camera.position.x) + (Math.random() * 8 - 4), Math.round(camera.position.z) + (Math.random() * 8 - 4), { kind }); return floatingDebris.count(); },
    clear:    () => floatingDebris.clear(),
