        workers: (() => { try { const w = window.meshPP; const ps = w?.stats?.(); return { enabled: w?.enabled?.() ?? false, workers: ps?.workers ?? 0, pending: ps?.pending ?? 0, jobs: ps?.jobs ?? 0, failures: ps?.failures ?? 0, avgMs: ps ? +(ps.avgMs || 0).toFixed(1) : 0 }; } catch { return null; } })(),
        // v705 — Tamagotchi stats so the phone Listener tab can render
