// v519 — spawn the swirling funnel particles for each active vortex, styled by
// type. Spawned along the whole column each frame so the funnel stays full
// (GPU particles fall under gravity). Visual only.
function _spawnVortexFunnels(dt) {
    const gp = window.gpuParticles; if (!gp?.spawn) return;
    const list = vortexSystem.vortices; if (!list.length) return;
    for (const v of list) {
        let baseY = 8;                                  // water vortices ride the sea
        if (!v.water) { try { const h = world._heightAt(v.x | 0, v.z | 0); if (Number.isFinite(h)) baseY = h + 1; } catch {} }
        const n = Math.max(2, Math.round((v.spawnRate || 30) * dt));
        let col, shape, rise;
        if (v.type === "whirlpool")       { col = [0.95, 0.98, 1.0]; shape = 4; rise = 0.2; }
        else if (v.type === "waterspout") { col = [0.80, 0.90, 1.0]; shape = 0; rise = 1.0; }
        else if (v.type === "cyclone")    { col = [0.62, 0.66, 0.72]; shape = 4; rise = 0.5; }
        else                               { col = [0.55, 0.47, 0.38]; shape = 4; rise = 0.9; }   // tornado dust
        for (let i = 0; i < n; i++) {
            const ang = Math.random() * Math.PI * 2;
            const rr = Math.sqrt(Math.random()) * v.radius;          // denser toward center
            const px = v.x + Math.cos(ang) * rr, pz = v.z + Math.sin(ang) * rr;
            const py = baseY + Math.random() * v.height * (1 - 0.4 * (rr / v.radius));   // taper up + in
            const f = vortexSystem.fieldAt(v, px, pz);
            gp.spawn({
                x: px, y: py, z: pz,
                vx: f.vx * 0.6, vy: rise * (0.4 + Math.random()), vz: f.vz * 0.6,
                life: 0.7 + Math.random() * 0.6, size: v.type === "cyclone" ? 1.1 : 0.6,
                r: col[0], g: col[1], b: col[2], shape,
            });
        }
    }
}
