// Warm the asset cache for all available scene meshes. Server's
// /assets/list endpoint enumerates GPU_Assets/ for *.json mesh files;
// we kick off loads for every one of them in parallel so they're
// ready when renderers ask. Falls back gracefully if the endpoint
// is missing (older servers) by trying mesh_0 directly.
//
// v622 — DEFERRED. The auto-load ran on every boot regardless of which demo
// was active, hammering the console with "71 assets loaded" + reloading
// crappy old generated GLBs that the user doesn't want sitting in memory.
// Now: at boot we resolve which demo will start (from localStorage autostart,
// defaults to blank_sandbox), and if that demo is in LEAN_BOOT_DEMOS we just
// prime the known-set and bail. Demos that genuinely need assets (kaiju,
// civs, ogre, voice lab) trigger the full load on activation via
// window.loadAllAssets() — see demoManager.set / setById entry points.
//
// To force-load anyway (e.g. you're testing the asset pipeline), set
// localStorage.setItem("voxelengine.forceAssetAutoLoad", "1").
const LEAN_BOOT_DEMOS = new Set([
    "blank_sandbox", "sandbox",
    "boids", "life", "centipede", "asteroids",
]);
let _assetsLoadedOnce = false;
window.loadAllAssets = async function loadAllAssets() {
    if (_assetsLoadedOnce) return;
    _assetsLoadedOnce = true;
    let names = [];
    let formats = null;
    try {
        const r = await fetch("/assets/list");
        const j = await r.json();
        names = j.ok ? j.assets : [];
        formats = j.ok ? (j.formats || null) : null;
    } catch (e) {
        console.warn("[main] /assets/list unavailable, falling back to mesh_0:", e.message);
        names = ["mesh_0"];
    }
    try { assetLoader.primeKnownAssets(names, formats); } catch {}
    if (names.length === 0) { console.log("[main] no GPU assets found in GPU_Assets/"); return; }
    console.log(`[main] auto-loading ${names.length} assets: ${names.join(", ")}`);
    let loaded = 0, failed = 0;
    await Promise.all(names.map(name =>
        assetLoader.loadAsset(name).then(m => {
            if (m) { loaded++; console.log(`[main] ${name}: ${m.vertexCount} verts, ${m.indexCount} indices`); }
            else   { failed++; }
        })
    ));
    console.log(`[main] asset auto-load complete: ${loaded} loaded, ${failed} failed`);
};
// v1590 — one-time "engine booted" handshake: tell the bridge we reached the sandbox so it can gate
// the periodic asset/image sync (sync arms only after the peer version check AND this signal).
// v1605 — defer it until the GRID has actually drawn, so the empty sandbox shows first and the bridge's
// image sync doesn't arm ahead of a visible grid. Falls back on a timer if the grid event is missed.
let _bootSignalled = false;
function _signalBooted() { if (_bootSignalled) return; _bootSignalled = true; try { fetch("/boot/ready", { method: "POST", keepalive: true }).catch(() => {}); } catch {} }
function _signalBootedAfterGrid() { if (window.onSwekGridReady) window.onSwekGridReady(_signalBooted); else _signalBooted(); }
(async () => {
    // Decide whether to auto-load at boot or defer.
    let want = "blank_sandbox";
    try { const a = localStorage.getItem("voxelengine.autostart"); if (a) want = a; } catch {}
    const force = (() => { try { return localStorage.getItem("voxelengine.forceAssetAutoLoad") === "1"; } catch { return false; } })();
    if (!force && LEAN_BOOT_DEMOS.has(want)) {
        // Still prime the known-set so later loadAsset() calls for unknown
        // names don't fire 4 HTTP probes each (negative-cache instantly).
        try {
            const r = await fetch("/assets/list");
            const j = await r.json();
            const names = j.ok ? j.assets : [];
            const formats = j.ok ? (j.formats || null) : null;
            assetLoader.primeKnownAssets(names, formats);
            console.log(`[main] lean boot ("${want}") — primed ${names.length} asset names but skipped the load. Call window.loadAllAssets() to load on demand.`);
        } catch (e) { console.warn("[main] prime failed:", e?.message); }
        _signalBootedAfterGrid();
        return;
    }
    // Legacy path — non-lean boot demos trigger the full load now.
    await window.loadAllAssets();
    _signalBootedAfterGrid();

    // v439 — RIGGED & LIVE. Auto-rig the kaiju kinds (and the aquarium
    // creatures that reuse them — its shark is kaiju_water, its mini-kaiju
    // is kaiju_underground) so their bodies undulate instead of sliding as
    // rigid blocks. Each static asset is replaced in place with a spine-
    // rigged version: identical shape + colors at rest, and clip[0] is a
    // gentle living writhe the animator auto-plays. Standalone fish are
    // already covered by rig.fish()/eel()/school().
    try {
        const { buildSpineRigGeometry, registerSpineRig } = await import("./gpu/autoSpineRig.js");
        window._rigLiveKinds = ["kaiju_water", "kaiju_space", "kaiju_tech", "kaiju_hell", "kaiju_cave", "kaiju_underground", "kaiju_ogre_hull"];
        const rigOne = (name, amp) => {
            const src = assetLoader.cache?.get(name);
            if (!src || !src._rawPositions || src.isRigged) return false;
            // Kaiju OBJs are non-indexed triangle soup — synthesize sequential
            // indices so the rigged mesh draws indexed like every other rig.
            let inds = src._rawIndices;
            if (!inds || inds.length === 0) {
                const vc = src._rawPositions.length / 3;
                inds = new Uint32Array(vc);
                for (let i = 0; i < vc; i++) inds[i] = i;
            }
            const geom = buildSpineRigGeometry(src._rawPositions, inds, src._rawNormals,
                { joints: 7, amplitude: amp, waves: 1.0, period: 1.6, tailBias: 1.2 });
            registerSpineRig(assetLoader, name, geom, src._rawColors || null);
            try { assetLoader.notifyMeshSwap?.(name, src, assetLoader.cache.get(name)); } catch {}
            return true;
        };
        window.rigLive = (on = true) => {
            let n = 0;
            if (on) for (const k of window._rigLiveKinds) { if (rigOne(k, k === "kaiju_water" ? 0.22 : 0.14)) n++; }
            console.log(`[rigLive] ${on ? `rigged ${n} creature kinds — their bodies now undulate` : "(reload the page to revert to static)"}`);
            return n;
        };
        const rc = window.rigLive(true);
        console.log(`[main] rigged-and-live: ${rc} kaiju kinds animated on load`);
    } catch (e) {
        console.warn("[main] rig-live retrofit failed:", e.message);
    }
})();

