// PATCH-B2d -- combat outcome capture for the GPU brain's online learner.
// kaiju_ranged_attack tells us what fired (attackName is accurate as of
// PATCH-B9). Beams and AoE apply instantly in this engine, so they are
// outcomes the moment they fire; projectiles wait for their
// projectile_impact event (matched by ownerKaijuId; tree throws produce
// impacts too but never have a pending shot, so they are ignored).
// Outcomes ride the next brain snapshot POST and are dropped if no brain
// is consuming them (capped ring, zero cost when idle).
window._gpuBrainOutcomes = [];
{
    const pendingShots = [];
    civEvents.subscribe((evt) => {
        try {
            if (evt.type === "kaiju_ranged_attack" && evt.attackName) {
                const fam = KAIJU_ATTACKS[evt.attackName]?.family;
                if (fam === "projectile") {
                    pendingShots.push({ id: evt.kaijuId, name: evt.attackName, src: evt.attackSource, t: performance.now() });   // PATCH-B2i
                    if (pendingShots.length > 64) pendingShots.shift();
                } else if (fam) {   // beam / aoe: hitscan or instant
                    window._gpuBrainOutcomes.push({ id: evt.kaijuId, name: evt.attackName, hit: 1, civsHit: 0, kaijuHit: 0,
                                                    src: evt.attackSource });   // PATCH-B2i
                }
            } else if (evt.type === "projectile_impact" && evt.ownerCivId != null) {
                // PATCH-B2f -- civ-bolt outcome: attributed by PATCH-B10.
                // Hit a kaiju = 1, ground splash = 0. Rides the same
                // outcomes channel; the brain routes it by kind.
                // PATCH-B2g -- targeted-shot outcome labels the (civ, kaiju) aim row
                if (evt.targetKaijuId != null) {
                    window._gpuBrainOutcomes.push({ kind: "civtarget", id: evt.ownerCivId,
                        name: String(evt.targetKaijuId),
                        hit: ((evt.kaijuHit ?? 0) > 0) ? 1 : 0, kaijuHit: evt.kaijuHit ?? 0 });
                }
                window._gpuBrainOutcomes.push({ kind: "civdef", id: evt.ownerCivId,
                                                hit: (evt.kaijuHit ?? 0) > 0 ? 1 : 0,
                                                kaijuHit: evt.kaijuHit ?? 0, civsHit: 0 });
            } else if (evt.type === "projectile_impact" && evt.ownerKaijuId != null) {
                const now = performance.now();
                for (let i = 0; i < pendingShots.length; i++) {
                    const s = pendingShots[i];
                    if (s.id !== evt.ownerKaijuId) continue;
                    if (now - s.t > 12000) continue;
                    pendingShots.splice(i, 1);
                    const hits = (evt.civsHit ?? 0) + (evt.kaijuHit ?? 0);
                    window._gpuBrainOutcomes.push({ id: s.id, name: s.name, hit: hits > 0 ? 1 : 0,
                                                    civsHit: evt.civsHit ?? 0, kaijuHit: evt.kaijuHit ?? 0,
                                                    src: s.src });   // PATCH-B2i
                    break;
                }
            }
            if (window._gpuBrainOutcomes.length > 200) window._gpuBrainOutcomes.splice(0, window._gpuBrainOutcomes.length - 200);
        } catch {}
    });
}

// PATCH-B2e -- civ retaliation init MOVED (v2065): it referenced
