// v1081 — bridge real kaiju events to window CustomEvents so the UI + light
// reactions can hook them. kaiju_ranged_attack -> engine:kaijuAttack (carrying
// the attack's registry color); kaiju_death -> engine:kaijuDefeated (referenced
// by the audio map but never actually dispatched before now).
try {
    const _atkHex = (name) => { const a = (typeof KAIJU_ATTACKS !== "undefined") && KAIJU_ATTACKS[name]; const c = a && a.color; if (Array.isArray(c) && c.length >= 3) return c.map(v => Math.round(Math.max(0, Math.min(1, v)) * 255).toString(16).padStart(2, "0")).join(""); return null; };
    civEvents.subscribe((evt) => {
        if (!evt || !evt.type) return;
        if (evt.type === "kaiju_ranged_attack") {
            const hex = _atkHex(evt.attackName) || "ff2020";
            try { window.dispatchEvent(new CustomEvent("engine:kaijuAttack", { detail: { attackName: evt.attackName, kind: evt.kaijuKind, color: hex, target: evt.targetName } })); } catch {}
        } else if (evt.type === "kaiju_death") {
            try { window.dispatchEvent(new CustomEvent("engine:kaijuDefeated", { detail: { kaiju: evt.kaiju } })); } catch {}
        }
    });
    console.log("[kaijuEventBridge] engine:kaijuAttack / engine:kaijuDefeated wired");
} catch (e) { console.warn("[kaijuEventBridge] failed:", e && e.message); }
// Round 27 — civ tech progression: civs need to find kaiju targets,
