// Round 425 — HELLGATES. Lava portals that besiege civilizations with a
// two-sided war AI: hellspawn hunt the nearest civ; panicked civs fire
// retaliation bolts back. Self-contained — reads civ positions, spawns
// its own entities via the router, and emits typed events on civEvents
// so the NarrativeEngine reacts. FX are particle bursts (no projectile
// coupling). Idle cost is zero until a gate is opened.
import { HellgateManager } from "./simulation/HellgateManager.js";
import { terrainTopAt } from "./simulation/cameraGroundClamp.js";
// Ground height at a world column (so gates/hellspawn sit ON the terrain
// instead of floating). +0.5 lifts them just clear of the surface.
function _hellGroundY(x, z) { try { const y = terrainTopAt(world, x, z); return (Number.isFinite(y) ? y : 1) + 0.5; } catch { return 1.5; } }
function _hellBurst(x, z, count, rgb, spread, life, y) {
    if (!gpuParticles?.isSupported?.()) return;
    const cy = (y == null) ? _hellGroundY(x, z) : y;
    for (let i = 0; i < count; i++) {
        const a = (i / count) * Math.PI * 2;
        gpuParticles.spawn({ x, y: cy, z,
            vx: Math.cos(a) * spread, vy: 1 + Math.random() * spread, vz: Math.sin(a) * spread,
            life: life + Math.random() * 0.4, size: 0.4 + Math.random() * 0.4,
            r: rgb[0], g: rgb[1], b: rgb[2], shape: 3 });
    }
}
function _hellStreak(from, to, rgb) {
    if (!gpuParticles?.isSupported?.()) return;
    const n = 10;
    for (let i = 0; i <= n; i++) {
        const t = i / n;
        gpuParticles.spawn({ x: from.x + (to.x - from.x) * t, y: from.y + (to.y - from.y) * t, z: from.z + (to.z - from.z) * t,
            vx: 0, vy: 0, vz: 0, life: 0.4, size: 0.3, r: rgb[0], g: rgb[1], b: rgb[2], shape: 1 });
    }
}
const hellgateManager = new HellgateManager({
    groundY:        (x, z) => _hellGroundY(x, z),
    spawnGate:      (id, x, y, z) => { try { return router.exec({ type: "entity:spawnMesh", assetId: "obelisk", kind: "obelisk", x, y, z, scale: 3.0 })?.id ?? null; } catch { return null; } },
    spawnHellspawn: (id, x, y, z) => { try { return router.exec({ type: "entity:spawnMesh", assetId: "kaiju_underground", kind: "kaiju_underground", x, y, z, scale: 1.2 })?.id ?? null; } catch { return null; } },
    moveEntity:     (id, x, y, z, yaw) => { if (id == null) return; try { router.exec({ type: "entity:move", id, x, y, z, yaw }); } catch {} },
    despawnEntity:  (id) => { if (id == null) return; try { router.exec({ type: "entity:despawn", id }); } catch {} },
    gateOpenFx:  (x, z, y) => _hellBurst(x, z, 90, [1.0, 0.30, 0.05], 2.4, 1.2, y),
    gatePulseFx: (x, z, i) => _hellBurst(x, z, Math.round(6 + 22 * i), [1.0, 0.50, 0.10], 1.2 * i + 0.3, 0.7),
    gateCloseFx: (x, z) => _hellBurst(x, z, 60, [0.40, 0.40, 0.45], 2.0, 1.0),
    deathFx:     (x, z) => _hellBurst(x, z, 24, [0.90, 0.10, 0.05], 1.0, 0.5),
    siegeFx:     (x, z) => _hellBurst(x, z, 6,  [1.0, 0.40, 0.10], 0.6, 0.4),
    civMissile:  (from, to) => _hellStreak(from, to, [0.60, 0.85, 1.0]),
    emit: (e) => { try { civEvents?.publish?.(e); } catch {} },
});
window.hellgate = {
    open:     (x, z) => hellgateManager.open(x ?? (window._camera?.position?.x ?? 0), z ?? (window._camera?.position?.z ?? 0)),
    openNear: () => { const c = civManager.getAll?.()[0]; const cx = c?.center?.x ?? (window._camera?.position?.x ?? 0); const cz = c?.center?.z ?? (window._camera?.position?.z ?? 0); const id = hellgateManager.open(cx + 20, cz); console.log("[hellgate] opened", id, "near a civilization"); return id; },
    wave:     (n = 3) => { const all = civManager.getAll?.() || []; for (let i = 0; i < n; i++) { const c = all[i % Math.max(1, all.length)]; const a = Math.random() * 6.283; const r = 25 + Math.random() * 15; hellgateManager.open((c?.center?.x ?? 0) + Math.cos(a) * r, (c?.center?.z ?? 0) + Math.sin(a) * r); } console.log(`[hellgate] invasion — ${n} gates opened around civilizations`); },
    damage:   (id, n = 25) => hellgateManager.damageGate(id, n),
    close:    (id) => id ? hellgateManager.damageGate(id, 1e9) : hellgateManager.closeAll(),
    closeAll: () => { hellgateManager.closeAll(); console.log("[hellgate] all gates banished"); },
    clear:    () => { hellgateManager.clear(); console.log("[hellgate] cleared all gates + hellspawn instantly"); },
    state:    () => hellgateManager.snapshot(),
};
// Clear hellgate entities on world reset so they don't linger / re-float.
try { router.on?.("world:reset", () => hellgateManager.clear()); } catch {}
console.log("[HELLGATE] hellgate.openNear() to siege a civ · .wave(3) for an invasion · .closeAll() to banish · .state() for the battle");

// Discoverability pass — one-tap triggers for the five "set piece" systems
// that previously only had console handles (or none). Each reuses the proven
// summon / fire / crown / launch paths so a button can never drift from the
// actual sim. Surfaced as World-tab buttons further down. All handles below
// (window.summon, window.kaiju.*) are resolved lazily at click-time, so it's
// fine that some are defined later in the file.
window.kaijuShowcase = {
    // Tech alien invasion — a cluster of tech-race kaiju (metallic, ion-lance;
    // they shed "metal tree" MEMORY pillars as they roam).
    techInvasion: (n = 4) => {
        const out = [];
        for (let i = 0; i < n; i++) { try { const k = window.summon("tech"); if (k) out.push(k.id); } catch {} }
        try { window.kaijuSim?.start?.(); } catch {}
        try { window.kpop?.info?.("Tech invasion", out.length + " tech kaiju landed — watch for metal trees"); } catch {}
        console.log("[showcase] tech invasion →", out);
        return out;
    },
    // Crown a king — promote a live kaiju (or a freshly summoned one) to a
    // cross-kind king: bigger, faster minion cadence, a buff aura for nearby
    // kaiju of ANY kind, and king-tier attack rotations.
    crownKing: () => {
        let k = kaijuManager.kaiju.values().next().value;
        if (!k) { try { k = window.summon("hell"); } catch {} }
        if (!k) { console.warn("[showcase] no kaiju to crown"); return null; }
        try { window.kaiju.crown(k.id); } catch {}
        try { window.kpop?.info?.("A king rises", k.name + " now rules across kinds"); } catch {}
        return k.id;
    },
    // Rivalry duel — two rival-faction kaiju side by side (sky vs hell are
    // classic rivals). KaijuRivalry makes them open fire on each other; we
    // also nudge a first exchange so the duel reads immediately.
    duel: (a = "sky", b = "hell") => {
        let ka = null, kb = null;
        try { ka = window.summon(a); } catch {}
        try { kb = window.summon(b); } catch {}
        try { window.kaijuSim?.start?.(); } catch {}
        if (ka && kb) {
            const atkA = (typeof KIND_TO_ATTACK !== "undefined" && KIND_TO_ATTACK[a]) || "lightning";
            const atkB = (typeof KIND_TO_ATTACK !== "undefined" && KIND_TO_ATTACK[b]) || "fireball";
            setTimeout(() => { try { window.kaiju.fire(ka.id, atkA, kb.position); } catch {} }, 500);
            setTimeout(() => { try { window.kaiju.fire(kb.id, atkB, ka.position); } catch {} }, 950);
        }
        try { window.kpop?.info?.("Kaiju duel", a + " vs " + b + " — rivals open fire"); } catch {}
        return { a: ka?.id ?? null, b: kb?.id ?? null };
    },
    // Hellgate — a lava portal next to a civilization; it besieges them and a
    // hell queen rises to lead the minion wave.
    hellgate: () => { try { return window.hellgate?.openNear?.(); } catch { return null; } },
    // Tree-hurl cinematic — a kaiju uproots and hurls a tree while the camera
    // follows the projectile through its arc.
    throwCinematic: () => {
        let k = kaijuManager.kaiju.values().next().value;
        if (!k) { try { k = window.summon("sky"); } catch {} }
        if (!k) { console.warn("[showcase] no kaiju for throw"); return null; }
        const yaw = camera?.yaw || 0, fx = -Math.sin(yaw), fz = -Math.cos(yaw);
        const to = { x: (camera?.position?.x ?? 0) + fx * 40, y: (camera?.position?.y ?? 20), z: (camera?.position?.z ?? 0) + fz * 40 };
        const from = { x: k.position.x, y: k.position.y + 6, z: k.position.z };
        try {
            try { if (kaijuManager.throwCinematic) kaijuManager.throwCinematic.enabled = true; } catch {}
            const projectile = projectileManager.launch({ from, to, kind: "tree_pine", scale: 1.4, ownerKaijuId: k.id, trail: "ember", trailColor: [0.9, 0.7, 0.35] });
            try { kaijuManager.throwCinematic?.onThrow?.(projectile); } catch {}
            try { window.kpop?.info?.("Tree hurl", k.name + " uproots and hurls a tree"); } catch {}
            return true;
        } catch (e) { console.warn("[showcase] throw failed", e?.message); return false; }
    },
};
console.log("[showcase] window.kaijuShowcase.{techInvasion,crownKing,duel,hellgate,throwCinematic}() — also under \u2699 World");



