// v500 — Snow OGRE plow + on-ice gate (simulation/SnowOgre.js). The plow is
// FUNCTIONAL now: it lays an ICE road ahead via window.freeze. Enforcing the
// speed gate inside the chassis move-loop + registering the ski/plow meshes +
// folding SNOW_OGRE_LOADOUT into OgreScenario's VARIANTS table are the in-app steps.
window.snowOgre = {
    loadout: SNOW_OGRE_LOADOUT,
    plow: null, _timer: null,
    _ensure() { if (!this.plow && window.freeze) this.plow = new SnowOgrePlow(world, window.freeze); return this.plow; },
    _pose() {
        const s = ogreScenario?.ogre || ogreScenario?._ogre || ogreScenario?.state?.ogre;
        if (s && typeof s.x === "number") {
            const tx = s.target?.x ?? s.x, tz = s.target?.z ?? s.z;
            const yaw = (typeof s.yaw === "number") ? s.yaw : Math.atan2(tx - s.x, -(tz - s.z));
            return { x: s.x, z: s.z, yaw };
        }
        return { x: camera.position.x, z: camera.position.z, yaw: camera.yaw };  // fallback: camera
    },
    plowAhead() { const p = this._ensure(); if (!p) { console.warn("[snowOgre] freeze system not ready"); return null; } return p.update(this._pose()); },
    enable(ms = 250) { if (this._timer) return; this._timer = setInterval(() => { try { this.plowAhead(); } catch {} }, ms); console.log("[snowOgre] auto-plow ON — laying an ice road ahead (live OGRE if present, else camera)"); },
    disable() { if (this._timer) { clearInterval(this._timer); this._timer = null; } console.log("[snowOgre] auto-plow off"); },
};
