// Round 296 — wire skeletal IK constraints into kaiju entities. The
// v292/v293/v294 math has been shipped without callers; this is the
// gameplay integration. Each tick the module walks live kaiju, finds
// rigged animators, resolves Head/Spine/Shoulder/Elbow/Hand bones
// (across naming conventions), and registers look-at + arm-aim IK
// constraints. The look-at points the kaiju head at the player while
// the base clip animation plays. Arm IK aims the dominant arm at the
// current attack target when in range. Disabled by default — opt in
// via window.kaijuIK.setEnabled(true).
import { makeKaijuIK } from "./simulation/KaijuIK.js";
const kaijuIK = makeKaijuIK({
    kaijuManager,
    meshRenderer: entityMeshRenderer,
    getPlayerPos: () => camera ? { x: camera.position.x, y: camera.position.y, z: camera.position.z } : null,
});
window.kaijuIK = kaijuIK;

// Round 301 — Ragdoll death physics. When a kaiju enters "dying"
// state, RagdollIntegration spawns a Ragdoll for it. The ragdoll
// hooks into the SkeletalAnimator's onPose callback (v292) and
// overrides the clip pose with PBD-simulated bone positions until
// it auto-disposes after 4 seconds.
//
// Off by default — there's a visible behavior change (kaiju flop
// instead of playing a clean death anim). Toggle:
//   window.ragdoll.setEnabled(true)
import { makeRagdollManager } from "./simulation/Ragdoll.js";
import { makeRagdollIntegration } from "./simulation/RagdollIntegration.js";
const ragdollManager = makeRagdollManager({});
const ragdollIntegration = makeRagdollIntegration({
    kaijuManager,
    ragdollManager,
    meshRenderer: entityMeshRenderer,
    // Round 303 — `world` is declared at module top (line ~247) so it's
    // unconditionally in scope here. Earlier guarded check was defensive
    // against a possible TDZ but `world` is initialized well before this
    // line runs.
    world,
});
// v3236 -- *** THIS LINE IS AN UNEXPLAINED OVERRIDE, AND FINDING THAT OUT WAS THE ROUND. ***
//
// RagdollIntegration's constructor sets `this._enabled = true` (line 40): THE MODULE WAS WRITTEN TO BE ON. This
// line turns it off, carries no reason, and until v3236 the ONLY thing in the entire tree that could turn it
// back on was `window.ragdoll.setEnabled(true)` typed into a browser console -- grep across every .js, .html and
// .mjs outside this file finds ZERO callers. No changelog entry explains it either.
//
// SO THE KAIJU RAGDOLL SYSTEM HAS BEEN OFF AT STARTUP, and with it round 306's limb severance, which four
// separate readings of this subsystem described as "live". It is not live; it is REACHABLE. Round 307's
// RagdollDismember is reachable by nothing. THE HONEST STATEMENT IS THAT BOTH ARE DEAD AND ONE HAS A CONSOLE.
//
// *** THE DEFAULT IS LEFT ALONE ON PURPOSE. *** Flipping it would be a behaviour change on a system whose
// reason for being off nobody can produce -- and every previous confident claim I made about this subsystem was
// wrong. What CAN be fixed without guessing is the reachability: the toggle below gives it a front door, so the
// question "does this look right?" can be answered by somebody looking instead of by somebody who knows this
// line exists. WHEN THE REASON IS FOUND, WRITE IT HERE; if there is no reason, DELETE THE LINE rather than
// leaving a default nobody chose.
ragdollIntegration.setEnabled(false);

// v3236 -- A FRONT DOOR FOR A SYSTEM THAT HAD ONLY A CONSOLE. Keith's law: a module whose only caller is a
// console is unfinished. window.ragdoll.* has carried setEnabled/gore/kick/severLimb since round 304 and NOT
// ONE OF THEM HAD A BUTTON.
addEventListener("DOMContentLoaded", () => {
    const wrap = document.createElement("div");
    wrap.style.cssText = "position:fixed;right:8px;bottom:8px;z-index:99997;display:flex;gap:6px;font:11px system-ui;";
    const mk = (label, title, get, set) => {
        const b = document.createElement("button");
        b.title = title; b.textContent = label;
        b.style.cssText = "padding:5px 9px;border-radius:7px;border:1px solid #4a2a2a;background:#1a0f12;color:#f0b6b6;cursor:pointer;";
        // THE BUTTON REPORTS THE SYSTEM'S STATE RATHER THAN ITS OWN. A toggle that tracked a private boolean
        // would keep saying ON after something else turned the system off, which is the "flag that lies about
        // which code ran" this tree refuses elsewhere.
        const sync = () => { const on = !!get(); b.style.opacity = on ? "1" : "0.5"; b.style.borderColor = on ? "#c06a6a" : "#4a2a2a"; };
        b.addEventListener("click", () => { set(!get()); sync(); });
        sync(); return b;
    };
    wrap.appendChild(mk("\u{1F480} Ragdoll",
        "Kaiju ragdoll physics on death. CONSTRUCTED THEN DISABLED at startup by an unexplained line in main.js -- " +
        "the module itself defaults ON. Nothing but a console could turn it back on before v3236.",
        () => ragdollIntegration.isEnabled(), (on) => ragdollIntegration.setEnabled(on)));
    wrap.appendChild(mk("\u2702 Gore",
        "Limb severance on heavy hits (round 306). Only fires while Ragdoll is ON -- and round 307's better " +
        "implementation, simulation/RagdollDismember.js, is imported by nothing at all.",
        () => ragdollIntegration.isGoreEnabled(), (on) => ragdollIntegration.setGoreEnabled(on)));
    document.body.appendChild(wrap);
});
// v836 — expose ragdollManager on window so RigSystem.severLimb can
// find it without requiring opts.ragdollManager every call. The
// existing window.ragdoll.* API (Round 306) reaches into _active
// directly; v835's severLimb uses the new getRagdoll(id) accessor.
window.ragdollManager = ragdollManager;
window.ragdoll = {
    setEnabled: (on) => ragdollIntegration.setEnabled(on),
    isEnabled:  () => ragdollIntegration.isEnabled(),
    snapshot:   () => ragdollIntegration.snapshot(),
    clear:      () => ragdollIntegration.clear(),
    // Round 304 — wake corpses with an impulse.
    //   ragdoll.kick([x,y,z], [dx,dy,dz], magnitude, radius)
    //   ragdoll.kick(camera.pos, camera.forward, 30, 8)     // 30 m/s punt within 8m
    //   ragdoll.kickEntity(kaijuId, [x,y,z], [dx,dy,dz], 30, 8)
    kick:       (pos, dir, mag, r) => ragdollManager.kick(pos, dir, mag ?? 20, r ?? 6),
    kickEntity: (id, pos, dir, mag, r) => ragdollManager.kickEntity(id, pos, dir, mag ?? 20, r ?? 6),
    // Round 306 — limb severance.
    //   ragdoll.gore(true|false)              — toggle auto-sever on heavy hits
    //   ragdoll.severLimb(kaijuId, dir?)       — force-sever a random limb
    gore:       (on) => { ragdollIntegration.setGoreEnabled(on); return ragdollIntegration.isGoreEnabled(); },
    isGore:     () => ragdollIntegration.isGoreEnabled(),
    severLimb:  (kaijuId, dir, speed) => {
        const r = ragdollManager._active.get(kaijuId);
        if (!r) return null;
        return r.severRandomLimb({
            separationDir: dir ?? { x: 1, y: 0.5, z: 0 },
            separationSpeed: speed ?? 8,
            spinSpeed: 5,
        });
    },
};

