// Round 310 — MediaPipe face tracking. Lazy-loaded, opt-in. Nothing
// fetches or asks for webcam permission until window.face.start() is
// called. After that, 478 face landmarks + computed metrics (mouth
// open, eye blink, head yaw/pitch, eyebrow raise) become available
// for any system that wants to read them. First-round scope is just
// the data plumbing; avatar/kaiju wiring is later rounds.
let _faceTrackerInstance = null;
window.face = {
    async start(opts) {
        if (!_faceTrackerInstance) {
            const mod = await import("./face/MediaPipeFaceTracker.js");
            _faceTrackerInstance = new mod.MediaPipeFaceTracker(opts);
        }
        await _faceTrackerInstance.start();
        return _faceTrackerInstance;
    },
    stop() { _faceTrackerInstance?.stop(); },
    snapshot()    { return _faceTrackerInstance?.snapshot() ?? { active: false }; },
    metrics()     { return _faceTrackerInstance?.metrics() ?? null; },
    onUpdate(fn)  { return _faceTrackerInstance?.onUpdate(fn) ?? (() => {}); },
    showPreview(on) { _faceTrackerInstance?.showPreview(on); },
    isActive()    { return _faceTrackerInstance?.isActive() ?? false; },
};
console.log("[face] type 'await face.start()' to enable webcam face tracking · face.showPreview(true) for the floating preview");

// Hand tracking — sibling of window.face. Lazy, opt-in. Nothing fetches a
// model or asks for the webcam until window.hands.start(). 21 landmarks/hand
// (up to 2) + gesture metrics: cursor, pinch, grab point, fist, point, open
// palm, two-hand spread/roll. Data plumbing; the hand_tracking demo consumes it.
let _handTrackerInstance = null;
window.hands = {
    async start(opts) {
        if (!_handTrackerInstance) {
            const mod = await import("./face/MediaPipeHandTracker.js");
            _handTrackerInstance = new mod.MediaPipeHandTracker(opts);
        }
        await _handTrackerInstance.start();
        return _handTrackerInstance;
    },
    stop()        { _handTrackerInstance?.stop(); },
    snapshot()    { return _handTrackerInstance?.snapshot() ?? { active: false }; },
    metrics()     { return _handTrackerInstance?.metrics() ?? null; },
    onUpdate(fn)  { return _handTrackerInstance?.onUpdate(fn) ?? (() => {}); },
    showPreview(on) { _handTrackerInstance?.showPreview(on); },
    isActive()    { return _handTrackerInstance?.isActive() ?? false; },
};
console.log("[hands] type 'await hands.start()' to enable webcam hand tracking · hands.showPreview(true) for the floating preview");

