// v1157 — platform reach per demo. Nothing is code-locked; every demo renders
// through the same WebGL2 canvas. This captures realistic *usability* by input +
// GPU so the demo picker can badge each one (PC / Phone / TV) and dim the
// keyboard-only ones when the engine is opened on a phone or Android TV. Edit a
// demo's tier here and the badges follow.
const DEMO_PLATFORMS = (() => {
    const ALL = ["pc", "phone", "tv"];           // cinematic or standalone — usable anywhere
    const PCONLY = ["pc"];                          // needs keyboard / mouse / mic
    const m = {};
    const set = (ids, plat, note) => ids.forEach(id => { m[id] = { plat, note }; });
    set(["kaiju", "real_terrain", "ogre", "architecture", "boids", "life", "lorenz", "cruise", "rigtest", "robot", "nrc", "flow", "ovm", "p3d", "mol", "mto", "wnd", "showcase", "engine_saga", "resume_fx"],
        ALL, "Auto-plays \u2014 watch on any device; steer with the phone's analog stick. Heavy scenes (kaiju+terrain) tax a phone GPU.");
    set(["fps", "fp_control", "voice_lab", "build_viewer", "dealer_choice"],
        PCONLY, "Needs keyboard / mouse (voice lab uses the mic) \u2014 PC.");
    set(["asteroids", "missile_command", "centipede", "snake", "tron", "lander"],
        ALL, "Self-runs as a visual on any device; needs a keyboard to actually play \u2014 play on PC.");   // playable=PC, but renders everywhere
    set(["battleship", "slots", "pachinko", "pipboy_models", "credits"],
        ALL, "Opens as its own page \u2014 works in any browser (PC / phone / TV).");
    return m;
})();
// arcade demos render everywhere but are only *playable* on PC — flag for the badge note
const _DEMO_PLAY_PC_ONLY = new Set(["asteroids", "missile_command", "centipede", "snake", "tron", "lander"]);
function _clientKind() {
    const ua = navigator.userAgent || "";
    if (/Android.*TV/i.test(ua) || /\b(SHIELD|BRAVIA|GoogleTV|Web0S|Tizen|HbbTV|VIDAA|AFT[A-Z])\b/i.test(ua)) return "tv";
    if (/Mobi|Android|iPhone|iPad|iPod/i.test(ua)) return "phone";
    return "pc";
}

