// v965 — bare grid-plane blank world. Engaging it flips _demoIsolation to
// "exclusive" (suppresses voxels + sky + atmosphere, dark backdrop) and draws
// a procedural grid floor that follows the camera. off() restores the prior
// isolation. Lazy-constructs the GridFloor on first use.
let _gridRenderHook = null;
let _gridFloor = null;
let _gridPrevIsolation = null;
window.gridWorld = {
    on() {
        try { if (!_gridFloor) _gridFloor = new GridFloor(gl); }
        catch (e) { console.warn("[gridWorld] init failed:", e); return false; }
        if (_gridPrevIsolation == null) _gridPrevIsolation = window._demoIsolation;
        window._demoIsolation = "exclusive";
        try { window._stageBackdrop = [0.04, 0.05, 0.08]; } catch {}   // clean dark grid backdrop
        _gridRenderHook = () => _gridFloor.render(camera.viewProj, camera.position);
        console.log("[gridWorld] ON — bare grid plane (exclusive isolation: voxels/sky/atmosphere hidden).");
        return true;
    },
    off() {
        _gridRenderHook = null;
        window._demoIsolation = (_gridPrevIsolation != null) ? _gridPrevIsolation : "active";
        _gridPrevIsolation = null;
        console.log("[gridWorld] OFF — isolation restored to", window._demoIsolation);
        return true;
    },
    toggle() { return _gridRenderHook ? window.gridWorld.off() : window.gridWorld.on(); },
    status() { return { on: !!_gridRenderHook, isolation: window._demoIsolation, floor: _gridFloor ? _gridFloor.status() : null }; },
};
window._showcaseDemoRenderHook = () => _showcaseDemoRenderHook;
// v360 — retro game demos (HTML canvas overlays).
