window.demoManager = demoManager;   // v519 — used by remote control panel
// v1411 — universal per-demo remote controls. A DEMO_MODES entry may declare
// padControls [{id,label,icon}] (serialized to the phone) + padAction(id) (runs the
// action engine-side). The phone Demo panel renders the active demo's controls and
// sends demo:action; the gamepad face/d-pad buttons map to the same list (v1412).
demoManager.getPadControls = function () {
    try { const d = this.current; if (d && Array.isArray(d.padControls)) return d.padControls.map(c => ({ id: c.id, label: c.label, icon: c.icon || "" })); } catch {}
    return [];
};
demoManager.fireAction = function (id, args) {
    try { const d = this.current; if (d && typeof d.padAction === "function") { d.padAction(id, args || {}); return true; } } catch (e) { console.warn("[demo:action]", e && e.message); }
    return false;
};
window.demoAction = (id, args) => demoManager.fireAction(id, args || {});

// Definable demo order: demos with a numeric `setPos` sort to the front in
// ascending order; everything else keeps its original order behind them. Stable
// (Chrome's sort is stable), so unpositioned demos never reshuffle. Re-syncs the
// active index so an in-flight demo isn't lost when discovered demos re-sort.
function _applyDemoOrder() {
    const curId = demoManager.current && demoManager.current.id;
    DEMO_MODES.sort((a, b) => (a.setPos == null ? 1e9 : a.setPos) - (b.setPos == null ? 1e9 : b.setPos));
    if (curId) { const ni = DEMO_MODES.findIndex(d => d.id === curId); if (ni >= 0) demoManager.modeIdx = ni; }
}
window._applyDemoOrder = _applyDemoOrder;
_applyDemoOrder();
{
    const btn = document.getElementById("demo-mode-button");
    if (btn) {
        btn.addEventListener("click", (e) => {
            e.preventDefault();
            e.stopPropagation();
            demoManager.toggleMenu();
        });
        // Also catch pointer events so clicks don't fall through to canvas
        btn.addEventListener("pointerdown", (e) => e.stopPropagation());
        // v464 — boot straight into a quiet "ENGINE STARTING" void. No kaiju
        // isolation, no terrain, no auto-start timer, no sound. The async demo
        // loader hands off to the blank sandbox (or a configured autostart
        // demo) once everything is ready. Kaiju only runs if explicitly chosen.
        window._engineBooting = true;
        window._demoIsolation = "exclusive";
        window._isolationShowIds = null;
        window._kaijuSimEnabled = false;
        try { chunkStreamer.setEnabled(false); } catch {}
        try { window.muteAllAudio?.(); } catch {}
        demoManager._updateButton();   // "PLEASE WAIT — ENGINE STARTING"
        console.log("[main] engine starting — quiet void until the blank sandbox loads. Kaiju is opt-in.");


        // v450 — demo transport controls embedded INTO the orange DEMO
        // button as a recessed (inset-shadow) compartment at its right end:
        // ▶ play · ⏸ pause · ⏹ stop · ✕ close, active state highlighted. The
        // button is extended with right-padding to make room, so the controls
        // ride on the button instead of floating beside it.
        try {
            const btnEl = document.getElementById("demo-mode-button");
            const transport = document.createElement("div");
            transport.id = "demo-transport";
            Object.assign(transport.style, {
                display: "inline-flex", gap: "3px", alignItems: "center",
                padding: "3px", borderRadius: "7px",
                background: "rgba(0,0,0,0.30)",
                boxShadow: "inset 0 1px 3px rgba(0,0,0,0.6), inset 0 -1px 1px rgba(255,255,255,0.07)",
                pointerEvents: "auto", font: "13px system-ui, sans-serif",
            });
            // Clicking the recessed area (not a button) shouldn't toggle the menu.
            transport.addEventListener("click", (e) => e.stopPropagation());
            transport.addEventListener("pointerdown", (e) => e.stopPropagation());
            const mk = (sym, title, fn) => {
                const b = document.createElement("button");
                b.textContent = sym; b.title = title;
                Object.assign(b.style, {
                    width: "22px", height: "22px", padding: "0", cursor: "pointer",
                    borderRadius: "4px", border: "1px solid rgba(0,0,0,0.35)",
                    background: "rgba(20,20,24,0.7)", color: "#e8eef8", lineHeight: "20px",
                    transition: "background 120ms, box-shadow 120ms", fontSize: "12px",
                });
                b.addEventListener("click", (e) => { e.preventDefault(); e.stopPropagation(); fn(); refreshTransport(); });
                b.addEventListener("pointerdown", (e) => e.stopPropagation());
                transport.appendChild(b); return b;
            };
            const bPlay  = mk("▶", "Play / resume the demo (or restart it if stopped)", () => demoManager.resume());
            const bPause = mk("⏸", "Pause the demo — freeze activity, keep the scene", () => demoManager.pause());
            const bStop  = mk("⏹", "Stop & reset the demo — won't run until you press Play", () => demoManager.stopDemo());
            const bClose = mk("✕", "Close — clear this demo from memory, back to the blank grid world", () => { demoManager.close(); try { window.gridWorld?.on?.(); } catch {} });
            void bClose;
            function refreshTransport() {
                // v463 — the blank sandbox is the base room (and the booting
                // splash); it has no demo to play/pause/stop/close, so the
                // transport is hidden there. You leave it via the demo picker.
                const baseRoom = window._engineBooting || demoManager.current?.id === "blank_sandbox";
                transport.style.display = baseRoom ? "none" : "";
                // v464 — drop the reserved transport space so there's no empty
                // gap on the button when the controls are hidden.
                if (btnEl) btnEl.style.paddingRight = baseRoom ? "" : "118px";
                if (baseRoom) return;
                const stopped = !!demoManager._stopped;
                const paused  = !stopped && !!demoManager._paused;
                const playing = !stopped && !paused;
                const hi = (b, on, col) => {
                    b.style.background = on ? col : "rgba(20,20,24,0.7)";
                    b.style.color = on ? "#021" : "#e8eef8";
                    b.style.boxShadow = on ? `0 0 7px ${col}` : "none";
                };
                hi(bPlay,  playing, "rgba(80,200,120,0.95)");
                hi(bPause, paused,  "rgba(230,190,70,0.95)");
                hi(bStop,  stopped, "rgba(210,90,90,0.95)");
            }
            if (btnEl) {
                if (getComputedStyle(btnEl).position === "static") btnEl.style.position = "relative";
                btnEl.style.paddingRight = "118px";        // extend the button to house the inset
                Object.assign(transport.style, { position: "absolute", right: "8px", top: "50%", transform: "translateY(-50%)" });
                btnEl.appendChild(transport);
            } else {
                Object.assign(transport.style, { position: "fixed", left: "260px", top: "8px", zIndex: "10002" });
                document.body.appendChild(transport);
            }
            refreshTransport();
            setInterval(refreshTransport, 400);
        } catch (e) { console.warn("[demo-transport] setup failed:", e?.message); }
    }
    // Round 42 — global ? key toggles per-demo help overlay
    document.addEventListener("keydown", (e) => {
        if (e.key === "?" || (e.key === "/" && e.shiftKey)) {
            // Don't trigger if user is typing into a text input
            const tgt = e.target;
            const inField = tgt && (tgt.tagName === "INPUT" || tgt.tagName === "TEXTAREA" || tgt.isContentEditable);
            if (!inField) {
                demoManager.toggleHelp();
                e.preventDefault();
            }
        }
    });
}
window.demo = demoManager;

