// Round 50 - kaiju console helpers. Test ranged attacks, list kaiju,
// promote to king for testing king-tier rotations. Useful for QA and
// for triggering specific attacks from screenshots / videos.
window.kaiju = {
    list: () => {
        const out = [];
        for (const k of (kaijuManager?.kaiju?.values?.() ?? [])) {
            out.push({
                id: k.id, name: k.name, kind: k.kind,
                king: !!k.becameKing,
                x: k.position.x.toFixed(1), y: k.position.y.toFixed(1), z: k.position.z.toFixed(1),
                hp: k.energy ? k.energy.toFixed(2) : "?",
                state: k.state,
            });
        }
        console.table(out);
        return out;
    },
    // Force a specific kaiju (by id, name, or "first") to fire a named
    // attack at the world target XYZ. Bypasses cooldown + target check.
    // Examples:
    //   kaiju.fire(3, "hell_curse", { x: 0, y: 20, z: 0 })
    //   kaiju.fire("first", "tremor")     // uses last-attacked target
    fire: (idOrName, attackName, targetXYZ) => {
        if (!kaijuManager) return;
        let k = null;
        if (idOrName === "first") {
            k = kaijuManager.kaiju.values().next().value || null;
        } else if (typeof idOrName === "number") {
            k = kaijuManager.kaiju.get(idOrName) || null;
        } else if (typeof idOrName === "string") {
            for (const cand of kaijuManager.kaiju.values()) {
                if (cand.name === idOrName) { k = cand; break; }
            }
        }
        if (!k) { console.warn("[kaiju.fire] no kaiju found:", idOrName); return; }
        const attack = KAIJU_ATTACKS[attackName];
        if (!attack) { console.warn("[kaiju.fire] unknown attack:", attackName); return; }
        const t = targetXYZ ?? k._lastAttackTarget ?? { x: k.position.x + 10, y: k.position.y, z: k.position.z };
        const target = {
            x: t.x, y: t.y, z: t.z,
            applyDamage: () => {},   // QA mode: don't actually deal damage to civs
        };
        if (attack.family === "beam")           kaijuManager._executeBeam(k, attack, target);
        else if (attack.family === "projectile") kaijuManager._executeProjectileAttack(k, attack, target);
        else if (attack.family === "aoe")        kaijuManager._executeAoEAttack(k, attack, target);
        console.log(`[kaiju.fire] ${k.name} (${k.kind}) → ${attackName} at (${t.x.toFixed(1)}, ${t.y.toFixed(1)}, ${t.z.toFixed(1)})`);
    },
    // Promote a kaiju to king for testing the king-tier rotation.
    crown: (idOrName) => {
        if (!kaijuManager) return;
        let k = null;
        if (typeof idOrName === "number") k = kaijuManager.kaiju.get(idOrName);
        else if (idOrName === "first") k = kaijuManager.kaiju.values().next().value;
        else for (const cand of kaijuManager.kaiju.values()) if (cand.name === idOrName) { k = cand; break; }
        if (!k) { console.warn("[kaiju.crown] not found"); return; }
        k.becameKing = true;
        k._kingAttackRotIdx = 0;
        console.log(`[kaiju.crown] ${k.name} is now king of the ${k.kind}`);
    },
    attacks: () => Object.keys(KAIJU_ATTACKS),
    // Round 274 — absorb mechanic controls. Console helpers for
    // testing the tier ramp + termination events.
    // Usage:
    //   kaiju.absorb("first", "energy")    — set affinity on a kaiju
    //   kaiju.absorbHit("first", "energy") — apply one absorbed hit (grows by 1 tier)
    //   kaiju.absorbStatus()               — table of all kaiju with their tier
    absorb: (idOrName, type) => {
        let k = null;
        if (typeof idOrName === "number") k = kaijuManager.kaiju.get(idOrName);
        else if (idOrName === "first") k = kaijuManager.kaiju.values().next().value;
        else for (const cand of kaijuManager.kaiju.values()) if (cand.name === idOrName) { k = cand; break; }
        if (!k) { console.warn("[kaiju.absorb] not found"); return null; }
        const allowed = ["energy", "nuclear", "kinetic", "fire", "cold", null];
        if (!allowed.includes(type)) { console.warn(`[kaiju.absorb] type must be one of ${allowed.filter(Boolean).join(",")} or null`); return null; }
        k.absorbsType = type;
        console.log(`[kaiju.absorb] ${k.name} now absorbs ${type ?? "nothing"}`);
        return k.absorbsType;
    },
    absorbHit: (idOrName, type) => {
        let k = null;
        if (typeof idOrName === "number") k = kaijuManager.kaiju.get(idOrName);
        else if (idOrName === "first") k = kaijuManager.kaiju.values().next().value;
        else for (const cand of kaijuManager.kaiju.values()) if (cand.name === idOrName) { k = cand; break; }
        if (!k) { console.warn("[kaiju.absorbHit] not found"); return null; }
        const applied = k.applyTypedDamage?.(0.25, type ?? k.absorbsType ?? "energy") ?? 0;
        console.log(`[kaiju.absorbHit] ${k.name} tier=${k.absorbTier} scale=${k.absorbScale.toFixed(2)} energyApplied=${applied.toFixed(2)} terminating=${k._terminating ?? "no"}`);
        return { tier: k.absorbTier, scale: k.absorbScale, terminating: k._terminating };
    },
    absorbStatus: () => {
        const rows = [];
        for (const k of kaijuManager.kaiju.values()) {
            if (!k.absorbsType && k.absorbTier === 0) continue;
            rows.push({
                id: k.id, name: k.name, kind: k.kind,
                absorbs: k.absorbsType ?? "—",
                tier: k.absorbTier,
                scale: k.absorbScale?.toFixed(2),
                terminating: k._terminating ?? "—",
            });
        }
        console.table(rows);
        return rows;
    },
};
console.log("[KAIJU] type 'kaiju.list()' to see active kaiju, 'kaiju.fire(id, attackName)' to test");

