// Round 30/31 — POV keyboard + mouse bindings
window.addEventListener("keydown", (ev) => {
    if (ev.repeat) return;
    if (ev.target && /^(INPUT|TEXTAREA|SELECT)$/.test(ev.target.tagName)) return;
    const key = ev.key.toLowerCase();
    if (key === "f" && !ev.ctrlKey && !ev.metaKey) {
        if (ogreScenario.povActive) ogreScenario.povStop();
        else ogreScenario.povStart();
        ev.preventDefault();
    } else if (key === "n" && ogreScenario.povActive) {
        ogreScenario.povNext();
        ev.preventDefault();
    } else if (key === "b" && ogreScenario.povActive) {
        ogreScenario.povPrev();
        ev.preventDefault();
    } else if (key === "v" && ogreScenario.povActive) {
        ogreScenario.povToggleFreeLook();
        ev.preventDefault();
    } else if (key === "c" && ogreScenario.povActive) {
        ogreScenario.povToggleControl();
        ev.preventDefault();
    } else if (key === "[" && ogreScenario.active) {
        // Round 43n - sell selected defender
        const def = ogreScenario.selectedDefender;
        if (def) {
            // find the slot containing this defender
            const slot = ogreScenario.slots?.find(s =>
                s.filled &&
                Math.abs(s.x - def.x) < 0.5 &&
                Math.abs(s.z - def.z) < 0.5
            );
            if (slot) ogreScenario.sellTurretAtSlot(slot);
        }
        ev.preventDefault();
    } else if (key === "]" && ogreScenario.active) {
        // Round 43n - repair selected defender
        ogreScenario.repairDefender();
        ev.preventDefault();
    }
});
// Round 31 — left click fires when in POV control mode
canvas.addEventListener("mousedown", (ev) => {
    if (ev.button !== 0) return;
    if (ogreScenario.povActive && ogreScenario.povInControl) {
        ogreScenario.povTryFire();
    }
});

