// Shared Ollama client — one probe/availability state across all agents.
// Auto-starts in "unknown" state; first agent observe() that triggers an
// async narrative call will probe and set available=true|false.
//
// Declared HERE (rather than after router.register below) because
// router.register references `ollama`, and `let`/`const` enforce a
// temporal dead zone — referencing before this line throws.
const ollama = new OllamaClient();   // Round 166 — drop hardcoded model. The constructor pulls voxelengine.ollamaModel from localStorage when present, so the user's auto-assigned pick persists across reloads.
window._ollama = ollama;        // Round 162 — exposed for the AI Chain demo

// v919 — local-LLM dialect toggle. Ollama (native /api/*) is the default;
// LlamaStash / LM Studio / raw llama-server speak OpenAI /v1/* on the same
// :11434. Flip without touching the URL; the choice persists across reloads.
//   llm.useLlamaStash()  ·  llm.useOllama()  ·  llm.status()
window.llm = {
    useLlamaStash: () => { ollama.setDialect("openai"); console.log("[LLM] dialect → openai (LlamaStash / OpenAI-compatible). Run `llamastash start <model>`."); return ollama.getDialect(); },
    useOllama:     () => { ollama.setDialect("ollama"); console.log("[LLM] dialect → ollama (native /api/*)."); return ollama.getDialect(); },
    setUrl:        (u) => ollama.setBaseUrl(u),
    status:        async () => ({ dialect: ollama.getDialect(), baseUrl: ollama.baseUrl, reachable: await ollama.probe(), models: await ollama.listModels() }),
};
console.log("[LLM] local LLM dialect:", ollama.getDialect(), "— `llm.useLlamaStash()` to switch to an OpenAI-compatible server (LlamaStash).");

