let cinematicsEnabled = true;
const eventBinder = new EventScriptBinder({
    events: civEvents,
    civManager,
    applyDemo,
    options: { enabled: cinematicsEnabled },
});

// Round 91 — VariantExpander hooks into SettingsPanel's two new buttons.
// Construct it here so it has both the ollama client and asset loader.
const variantExpander = new VariantExpander({
    ollama,
    assetLoader,
});
// Round 96 — expose globally so the auto-grow startup scan (declared
// much earlier in the file) can reach it via window.variantExpander
