console.log("[KAIJU-MODE] type 'kaiju.activate(12)' to trigger · pickup kind: 'kaiju'");

// Round 253 — Kaiju Sandbox game mode. Standalone game mode where the
// player IS a giant monster destroying a procedural city. Start with
// window.kaijuCity.start(). Take damage with window.kaijuCity.damage(n)
// to test the shrink mechanic.
const cityGen = new CityGen(world);
const kaijuSandbox = new KaijuSandbox({
    camera,
    world,
    particles,
    audio: audio?.audio ?? null,
    kpop,
    cityGen,
    botManager: null,     // round 254 — patched after botManager construction
    fpsShooter: null,     // round 254/258 — patched after FPSShooter construction (TDZ-safe)
    router,               // round 256 — for civilian entity:spawnMesh / move / despawn
});
window.kaijuCity = {
    start:   (opts) => { window.kaijuSim?.start?.(); return kaijuSandbox.start(opts || {}); },
    stop:    () => kaijuSandbox.stop(),
    damage:  (n) => kaijuSandbox.takeDamage(n ?? 1),
    // Round 275 — manual building damage for testing crumble + topple.
    // Pass world (wx, wz) coords + an amount; or "auto" to pick the
    // building nearest the camera and apply enough damage to topple it.
    hitBuilding: (wx, wz, amount = 50) => {
        const cg = cityGen;
        if (!cg) { console.warn("[kaijuCity] no cityGen — start the sandbox first"); return null; }
        const r = cg.damageAt(wx, wz, amount);
        if (!r) { console.log("[kaijuCity] no building at that coord"); return null; }
        console.log(`[kaijuCity] hit ${r.building.h}u building, hp=${r.building.hp.toFixed(1)}/${r.building.maxHp}, crumbled=${r.crumbled}, toppled=${r.toppled}`);
        return r;
    },
    toppleNearest: () => {
        const cg = cityGen;
        if (!cg?.buildings?.length) return null;
        const cam = window._camera;
        let nearest = null, bestD = Infinity;
        const cx = cam?.position?.x ?? 0, cz = cam?.position?.z ?? 0;
        for (const b of cg.buildings) {
            if (b.state === "toppled") continue;
            const d = Math.hypot((b.x + b.w/2) - cx, (b.z + b.d/2) - cz);
            if (d < bestD) { bestD = d; nearest = b; }
        }
        if (!nearest) { console.log("[kaijuCity] no standing buildings"); return null; }
        const r = cg.damageAt(nearest.x + nearest.w/2, nearest.z + nearest.d/2, nearest.maxHp + 1);
        console.log(`[kaijuCity] toppled ${nearest.h}u building at (${nearest.x},${nearest.z})`);
        if (window.kaijuBox3d && window.kaijuBox3d.enabled) window.kaijuBox3d.topple(nearest, [(Math.random()-0.5)*40, 6, (Math.random()-0.5)*40]);   // v2259 — rigid collapse when box3d is on
        return r;
    },
    stats:   () => kaijuSandbox.getStats(),
    isActive:() => kaijuSandbox.isActive(),
    city:    () => cityGen.buildings,
    unbuildCity: () => cityGen.unbuild(),
};
console.log("[KAIJU-CITY] type 'kaijuCity.start()' to begin · '.damage(5)' to shrink · '.stats()' for status");

// Round 340 (v2259) — box3d rigid-body DESTRUCTION layer for the kaiju city. OPT-IN and defensive: when off
// (default) kaijuCity behaves exactly as before. When on (kaijuBox3d.enable(), needs a built WASM +
// box3d.setEnabled(true)) it runs the PHYSICS -- buildings as boxes, the kaiju as a kinematic collider,
// topple/debris/throw -- and hands back transforms via .bodies(). Drawing the toppled/debris meshes at those
// transforms is the renderer's job (RIG): each frame, kaijuBox3d.driveKaiju(kaijuWorldPos); kaijuBox3d.step();
// then draw kaijuBox3d.bodies() as [{ref,pos,quat,kind}]. Everything no-ops until enabled, so it cannot break
// the existing kaiju sim.
window.kaijuBox3d = (() => {
    let scene = null, on = false;
    const remote = new Map();     // v2260 — receiver-side ghost store (id -> {kind,pos,quat})
    return {
        get enabled() { return on && !!scene && scene.ready === true; },
        async enable(opts = {}) {
            try {
                const s = await createSceneFromLoader(box3d, opts);
                if (!s || s.ready !== true) { console.warn("[kaijuBox3d] " + (s && s.reason || "box3d not ready")); return false; }
                s.addBuildings((cityGen && cityGen.buildings) || []);
                scene = s; on = true;
                try { if (!window.box3dOverlay) { const _m = await import("./physics/box3dMeshOverlay.js"); window.box3dOverlay = _m.createBox3dOverlay(); } window.box3dOverlay.start(); } catch (e) { console.warn("[kaijuBox3d] mesh overlay:", e && e.message); }
                console.log(`[kaijuBox3d] ON — ${scene.buildingCount()} buildings as rigid bodies; mesh overlay drawing kaijuBox3d.bodies().`);
                return true;
            } catch (e) { console.warn("[kaijuBox3d] enable failed:", e && e.message); return false; }
        },
        disable() { try { scene && scene.destroy(); } catch {} scene = null; on = false; try { window.box3dOverlay && window.box3dOverlay.stop(); } catch {} },
        driveKaiju(pos, quat) { if (this.enabled) scene.driveKaiju(pos, quat); },
        topple(b, impulse) { return this.enabled ? scene.topple(b, impulse) : null; },
        spawnDebris(pos, n, o) { return this.enabled ? scene.spawnDebris(pos, n, o) : null; },
        throwProp(pos, v, spin, half) { return this.enabled ? scene.throwProp(pos, v, spin, half) : null; },
        step(dt) { if (this.enabled) return scene.step(dt); },
        bodies() { return this.enabled ? scene.activeBodies() : []; },
        // --- v2260: fleet-share. OWNER: broadcast pack() every tick. RECEIVER: applyRemote(packet) then draw remoteBodies().
        pack() { return this.enabled ? packBodies(scene) : null; },
        applyRemote(packet) { applyBodies(remote, packet); return remote.size; },
        remoteBodies() { return [...remote.values()]; },
        lockstep(remoteHash) { return this.enabled ? lockstepStatus(scene.stateHash(), remoteHash) : null; },
        stats() { return this.enabled ? { buildings: scene.buildingCount(), standing: scene.standingCount(), active: scene.activeCount(), hash: scene.stateHash().toString(16) } : { enabled: false }; },
    };
})();
console.log("[kaijuBox3d] rigid destruction layer available (opt-in): box3d.setEnabled(true) then kaijuBox3d.enable() — needs the box3d WASM built");

// Round 341 (v2268) -- one-click kaiju box3d demo. index.html?box3ddemo=1 auto-runs the destruction, so the
// Box3D info-page button and render QA can launch it without the console. Gated on the param; fully defensive
// (no-ops if anything isn't ready); topples a building every ~1.5s for a lively sequence.
try {
    const _bd = new URLSearchParams(location.search);
    if (_bd.get("box3ddemo") === "1" || _bd.get("demo") === "box3d") {
        const _runBox3dDemo = async () => {
            try {
                box3d.setEnabled(true);
                if (window.kaijuBox3d) { try { await window.kaijuBox3d.enable(); } catch {} }
                if (window.kaijuCity) { try { window.kaijuCity.start(); } catch {} }
                let _n = 0; const _iv = setInterval(() => { try { window.kaijuCity && window.kaijuCity.toppleNearest(); } catch {} if (++_n > 40) clearInterval(_iv); }, 1500);
                console.log("[box3ddemo] auto-running kaiju destruction (box3d substrate + kaijuCity topple loop)");
            } catch (e) { console.warn("[box3ddemo]", e && e.message); }
        };
        if (document.readyState === "complete") setTimeout(_runBox3dDemo, 2500);
        else window.addEventListener("load", () => setTimeout(_runBox3dDemo, 2500));
    }
} catch {}

// Round 285 — SandboxGameplay: civilian variety + score pickups +
