// Round 280 — throw cinematic. Subscribes to kaiju_throws events and
// briefly cuts the camera into a "follow the projectile" tracking
// shot, then restores the previous camera state. Cooldown so a
// throw-spamming kaiju doesn't keep yanking the camera away.
// Round 298 — DEAD WIRING REMOVED. There used to be a second
// ThrowCinematic instance here (from simulation/ThrowCinematic.js)
// that duplicated render/ThrowCinematic.js's responsibility. Both
// declared `const throwCinematic`, which caused a SyntaxError once
// the codebase converged on the render/ version below at ~line 5042.
// The render/ version is canonical: KaijuManager calls
// this.throwCinematic?.onThrow() directly into it.
// Patch sandbox.start to also start the fleet
const _origSandboxStart = kaijuSandbox.start.bind(kaijuSandbox);
kaijuSandbox.start = (opts) => {
    const r = _origSandboxStart(opts);
    const c = cityGen?._lastStamp;
    satelliteFleet.start({
        cityCenterX: c?.centerX ?? 0,
        cityCenterZ: c?.centerZ ?? 0,
    });
    return r;
};
const _origSandboxStop = kaijuSandbox.stop.bind(kaijuSandbox);
kaijuSandbox.stop = () => { satelliteFleet.stop(); return _origSandboxStop(); };
console.log("[SATELLITES] cities will launch satellites during kaiju city sandbox; type 'satellites.launch(\"laser\")' to force one");

// Round 257 — PIP avatars. Two iframe-hosted character windows in the
