let _csKitPickups = [];              // v541 — [{id,x,y,z}] defuse-kit pickups currently on the map

// v541 — clear all kit pickup props from the map
function _csClearKits() {
    for (const k of _csKitPickups) { try { router.exec({ type: "entity:despawn", id: k.id }); } catch {} }
    _csKitPickups = [];
}
// v541 — scatter a couple of defuse-kit pickups near CT spawn each round
function _csSpawnKits(layout) {
    _csClearKits();
    const ct = layout?.rooms?.find((r) => r.id === "ct_spawn");
    if (!ct) return;
    const cx = ct.x + (ct.w ?? 4) / 2, cz = ct.z + (ct.d ?? 4) / 2;
    for (const off of [[-2, 0], [2, 0]]) {
        const x = cx + off[0], z = cz + off[1];
        const y = (world?._heightAt?.(x, z) ?? 5) + 0.5;
        try {
            const r = router.exec({ type: "entity:spawnMesh", assetId: "wad_prop_chest", kind: "wad_prop_chest", x, y, z, scale: 0.32 });
            if (r?.id != null) _csKitPickups.push({ id: r.id, x, y, z });
        } catch {}
    }
    if (_csKitPickups.length) console.log(`[cs] spawned ${_csKitPickups.length} defuse-kit pickup(s) near CT spawn`);
}
let _csBombThrow = null;             // v537 — active throw-arc animation {id,t,dur,x0,y0,z0,x1,y1,z1,peak}

// v537 — throw the bomb forward in an arc instead of dropping it at your feet.
// Computes a forward landing from the camera's aim (wall-clamped so it doesn't
// sail through geometry), asks the round manager to drop it there, then snaps
// the just-spawned prop back to the player's hands and arcs it to the landing.
// Returns false when not carrying so the G key can fall through to the shop.
function _csThrowBomb() {
    const cam = window.camera;
    if (!cam) return false;
    const yaw = cam.yaw || 0, pitch = cam.pitch || 0;
    const fx = Math.sin(yaw), fz = Math.cos(yaw);            // horizontal forward (matches shooter aim)
    const px = cam.position.x, pz = cam.position.z, eyeY = cam.position.y;
    // Distance scales with look angle: aim up → throw farther. Clamp 2..9.
    let maxDist = Math.max(2, Math.min(9, 6 - pitch * 4));
    // March forward, stop short of a wall (terrain rising above the hands).
    let dist = maxDist;
    for (let d = 1; d <= maxDist; d++) {
        const gy = world?._heightAt?.(px + fx * d, pz + fz * d) ?? 0;
        if (gy > eyeY - 0.5) { dist = Math.max(1, d - 1); break; }
        dist = d;
    }
    const lx = px + fx * dist, lz = pz + fz * dist;
    if (!csRoundManager.requestDrop({ x: lx, z: lz })) return false;   // not carrying / not live
    // Arc the freshly-spawned prop from the hands to the landing.
    const groundY = (world?._heightAt?.(lx, lz) ?? 5) + 0.5;
    const startY = eyeY - 0.4;
    if (_csDroppedBombEntityId != null) {
        _csBombThrow = { id: _csDroppedBombEntityId, t: 0, dur: 0.6,
            x0: px, y0: startY, z0: pz, x1: lx, y1: groundY, z1: lz,
            peak: Math.max(startY, groundY) + 3 };
        try { router.exec({ type: "entity:move", id: _csBombThrow.id, x: px, y: startY, z: pz }); } catch {}
    }
    try { window._sfx?.("break_water", 0.35); } catch {}   // a short toss whoosh
    return true;
}
window._csThrowBomb = _csThrowBomb;
