csBotManager.roundManager = csRoundManager;
console.log("[CS] type 'cs.preview()' for overview · 'cs.play({side:\"t\"|\"ct\"})' to enter FPS · 'cs.clear()' to wipe");
console.log("[CS] hold E in plant zone (T) or near bomb (CT) to plant/defuse");
console.log("[CS] v326 — 2 T bots + 2 CT bots spawn on cs.play(); 'cs.bots()' to list");

