window.fps.stopAutoplay    = () => fpsAutopilot.disengage();
window.fps.toggleAutoplay  = () => fpsAutopilot.toggle();
window.fps.autoplayStats   = () => fpsAutopilot.getStats();
console.log("[AUTOPLAY] type 'fps.autoplay()' to let the AI play the FPS; press any key to take over");

