// Round 228 — unified perf dashboard for the three concurrency surfaces:
// the biome-decoration worker pool (v214), the bot pathfinding worker
// pool (v216), and the cooperative idle scheduler (running densifier,
// mesh post-processor, biome ambience, automata, etc.). Hidden by
// default. Toggle via Ctrl+Shift+P or `perf.toggle()`.
// Round 239 — all three references are late-bound. Direct references
// here would hit TDZ for botPathfinderPool (declared 60 lines below)
// and the others live in inner try-blocks. Pass null at construction
// and patch via queueMicrotask + setTimeout once they exist.
const perfDashboard = new PerfDashboard({
    biomeDecorPool:    null,     // patched in once decorPool is mounted (see below)
    botPathfinderPool: null,     // patched in once BotPathfinderPool is constructed
    scheduler:         null,     // patched in via window.scheduler post-init
    chunkRebuildDispatcher: null,   // round 250 — patched below if available
});
window.perf = {
    show:    () => perfDashboard.show(),
    hide:    () => perfDashboard.hide(),
    toggle:  () => perfDashboard.toggle(),
    isOpen:  () => perfDashboard.isVisible(),
};
// Late-bind biomeDecorPool + scheduler + botPathfinderPool since they
// live in inner try-blocks or come later in module load order.
queueMicrotask(() => {
    if (window.biomeDecorPool)    perfDashboard.biomeDecorPool = window.biomeDecorPool;
    if (window.scheduler)         perfDashboard.scheduler = window.scheduler;
    if (window.botPathfinderPool) perfDashboard.botPathfinderPool = window.botPathfinderPool;
});
// Re-check on a delay too in case those try-blocks finish later
setTimeout(() => {
    if (window.biomeDecorPool)    perfDashboard.biomeDecorPool = window.biomeDecorPool;
    if (window.scheduler)         perfDashboard.scheduler = window.scheduler;
    if (window.botPathfinderPool) perfDashboard.botPathfinderPool = window.botPathfinderPool;
}, 1500);
console.log("[PERF] type 'perf.show()' or press Ctrl+Shift+P to open the worker-pool dashboard");

// ----------------------------------------------------------------------
// v433 — CONSOLIDATED SETTINGS HUB
// One Windows-control-panel-style tabbed panel that gathers the engine's
// scattered runtime toggles (graphics / world / audio / AI / perf) into
// categories. Graphics drive gfxSettings (the render-loop source of
// truth); the rest drive the live window.* APIs defined above. All
// bindings resolve lazily at interaction time, so order is safe.
// ----------------------------------------------------------------------
const _PERIOD_TO_HOUR = { dawn: 6, day: 12, dusk: 18, night: 0 };
let _voxelDetailOn = false;   // voxelDetail has on/off but mix-based state; track locally
const _settingsCtx = {
    gfx: gfxSettings,
    renderer: renderer,
    _preset: "high",
    vegetation: {
        getDensity: () => vegetation.density,
        setDensity: (n) => { try { vegetation.setDensity(n); } catch {} },
    },
    voxelDetail: {
        isOn: () => _voxelDetailOn,
        on:   () => { _voxelDetailOn = true;  try { window.voxelDetail.on(); } catch {} },
        off:  () => { _voxelDetailOn = false; try { window.voxelDetail.off(); } catch {} },
    },
    streamer: { enabled: () => { try { return window.streamer.enabled(); } catch { return false; } },
                setEnabled: (v) => { try { window.streamer.setEnabled(v); } catch {} } },
    gridGrow: { isEnabled: () => { try { return dynamicGridRadius?.isEnabled?.(); } catch { return false; } },
                setEnabled: (v) => { try { dynamicGridRadius?.setEnabled?.(v); } catch {} } },
    weather:  { current: () => { try { return weatherSystem.state; } catch { return "clear"; } },
                force:   (s) => { try { window.weather.force(s); } catch {} } },
    time:     { periodName: () => { try { return window.time.period(); } catch { return "day"; } },
                setPeriod:  (p) => { try { window.time.set(_PERIOD_TO_HOUR[p] ?? 12); } catch {} } },
    clouds:   { current: () => { try { return window.clouds.current(); } catch { return "off"; } },
                set: (v) => { try { window.clouds.set(v); } catch {} },
                off: () => { try { window.clouds.off(); } catch {} } },
    mute:     { isMuted: () => !!window._muteState?.muted,
                setMuted: (v) => { try { v ? window.muteAllAudio() : window.unmuteAllAudio(); } catch {} } },
    visibility: { getMuteWhenHidden: () => !!visibility.muteAudioWhenHidden,
                  setMuteAudioWhenHidden: (v) => { try { visibility.setMuteAudioWhenHidden(v); } catch {} } },
    perf:     { toggle: () => { try { window.perf.toggle(); } catch {} } },
    flags:    { get: (k) => { try { return localStorage.getItem(k); } catch { return null; } },
                set: (k, v) => { try { localStorage.setItem(k, v); } catch {} } },
    resetWorld: () => { try { window.freshWorld(); } catch { try { location.reload(); } catch {} } },
};
// v491 — ONE settings panel. The old left-side LCARS SettingsPanel is retired;
// every control it had is migrated into this consolidated Hub as schema tabs,
// alongside the new Erosion/Flooding sim controls. The Hub render wraps every
// get/set/action in try/catch, so lazy/guarded bindings here are safe and a
// missing dependency degrades gracefully instead of breaking the panel.
// v1055 — Presence: greet on arrival / note departures from an HA person entity.
// Client-side (only acts while the engine is open). Config in localStorage.
window.presence = (() => {
    const LS = "voxelengine.presence";
    const def = { enabled: false, person: "person.keith_swerling", greet: true, greetText: "Welcome home, Keith.", announceLeave: false, intervalMs: 30000 };
    let cfg = (() => { try { return Object.assign({}, def, JSON.parse(localStorage.getItem(LS) || "{}")); } catch { return { ...def }; } })();
    let last = null, timer = null;
    const save = () => { try { localStorage.setItem(LS, JSON.stringify(cfg)); } catch {} };
    const isHome = (st) => st === "home";
    async function tick() {
        if (!cfg.enabled || !cfg.person) return;
        try {
            const r = await fetch("/ha/states?domain=person", { cache: "no-store" });
            if (!r.ok) return;
            const arr = await r.json(); if (!Array.isArray(arr)) return;
            const p = arr.find(e => e.entity_id === cfg.person); if (!p) return;
            const st = p.state;
            if (last !== null && st !== last) {
                if (isHome(st) && !isHome(last)) onArrive();
                else if (!isHome(st) && isHome(last)) onLeave();
            }
            last = st;
        } catch (e) {}
    }
    function onArrive() {
        try { window._toaster && window._toaster.show({ title: "\uD83C\uDFE0 Home", msg: cfg.greetText || "Welcome home.", type: "info" }); } catch {}
        if (cfg.greet) { try { window.pipAvatar && window.pipAvatar.speak({ Text: cfg.greetText || "Welcome home." }); } catch {} }
        try { window.dispatchEvent(new CustomEvent("engine:presence", { detail: { state: "home" } })); } catch {}
    }
    function onLeave() {
        if (cfg.announceLeave) { try { window._toaster && window._toaster.show({ title: "\uD83D\uDC4B Away", msg: "See you later.", type: "info" }); } catch {} }
        try { window.dispatchEvent(new CustomEvent("engine:presence", { detail: { state: "away" } })); } catch {}
    }
    function start() { if (timer) { clearInterval(timer); timer = null; } if (cfg.enabled) { timer = setInterval(tick, Math.max(10000, cfg.intervalMs)); tick(); } }
    start();
    return {
        config() { return { ...cfg }; },
        set(c) { cfg = Object.assign(cfg, c || {}); save(); last = null; start(); return { ...cfg }; },
        now: tick, testArrive: onArrive, status: () => ({ last }),
    };
})();

// v1055 — HA weather -> engine sky, GATED. Off by default. You choose what it
// drives (weather and/or day-night), follow-continuously vs manual-sync, and it
// disables in one click. Only touches the main-world sky (weather.html panel is
// independent). Config in localStorage.
window.haSky = (() => {
    const LS = "voxelengine.hasky";
    const def = { enabled: false, driveWeather: true, driveDayNight: false, mode: "follow", intervalMin: 10, weatherEntity: "weather.forecast_home", sunEntity: "sun.sun" };
    let cfg = (() => { try { return Object.assign({}, def, JSON.parse(localStorage.getItem(LS) || "{}")); } catch { return { ...def }; } })();
    let timer = null, lastMap = null;
    const save = () => { try { localStorage.setItem(LS, JSON.stringify(cfg)); } catch {} };
    const condMap = { sunny: "clear", "clear-night": "clear", exceptional: "clear", windy: "clear", "windy-variant": "cloudy", partlycloudy: "cloudy", cloudy: "cloudy", fog: "cloudy", hail: "storm", lightning: "storm", "lightning-rainy": "storm", pouring: "rain", rainy: "rain", "snowy-rainy": "snow", snowy: "snow" };
    async function syncNow() {
        try {
            const r = await fetch("/ha/states", { cache: "no-store" });
            if (!r.ok) return { ok: false, error: "HA " + r.status };
            const arr = await r.json(); if (!Array.isArray(arr)) return { ok: false };
            const out = { ok: true };
            if (cfg.driveWeather) {
                const w = arr.find(e => e.entity_id === cfg.weatherEntity);
                if (w) { const state = condMap[String(w.state).toLowerCase()] || "clear"; out.condition = w.state; out.weather = state; try { window.weather && window.weather.setState(state); } catch {} }
            }
            if (cfg.driveDayNight) {
                const sun = arr.find(e => e.entity_id === cfg.sunEntity);
                const now = new Date(); const frac = (now.getHours() + now.getMinutes() / 60) / 24;
                out.dayNight = (sun && sun.state) || ((frac < 0.25 || frac > 0.78) ? "below_horizon" : "above_horizon");
                try { window.dayNight && window.dayNight.setTime(frac); } catch {}
            }
            lastMap = out; return out;
        } catch (e) { return { ok: false, error: String(e && e.message || e) }; }
    }
    function start() {
        if (timer) { clearInterval(timer); timer = null; }
        if (cfg.enabled && cfg.mode === "follow") { timer = setInterval(syncNow, Math.max(2, cfg.intervalMin) * 60000); syncNow(); }
    }
    start();
    return {
        config() { return { ...cfg }; },
        set(c) { cfg = Object.assign(cfg, c || {}); save(); start(); return { ...cfg }; },
        syncNow, last: () => lastMap,
    };
})();

// v1060 — Motion / doorbell -> engine reaction. The bridge already detects HA
// motion sensors (incl. doorbells) and pushes {type:"motion"} over SSE /ha/stream;
// this subscribes and reacts. Client-side, localStorage cfg.
window.haMotion = (() => {
    const LS = "voxelengine.hamotion";
    const def = { enabled: false, react: "announce", onlyDoorbell: false, cooldownMs: 20000 };
    let cfg = (() => { try { return Object.assign({}, def, JSON.parse(localStorage.getItem(LS) || "{}")); } catch { return { ...def }; } })();
    let es = null, lastFire = {}, lastEvent = null;
    const save = () => { try { localStorage.setItem(LS, JSON.stringify(cfg)); } catch {} };
    const pretty = (id, name) => name || String(id || "").replace(/^binary_sensor\./, "").replace(/_/g, " ");
    function react(ev) {
        const id = ev.entity_id || ""; const name = pretty(id, ev.name);
        if (cfg.onlyDoorbell && !/doorbell|door|bell/i.test(id)) return;
        const now = Date.now();
        if (lastFire[id] && now - lastFire[id] < (cfg.cooldownMs || 20000)) return;
        lastFire[id] = now; lastEvent = { id, name, at: now };
        try { window._toaster?.show({ title: "\uD83D\uDEA8 Motion", msg: name, type: "system", duration: 4000 }); } catch {}
        if (cfg.react === "announce" || cfg.react === "all") { try { window.pipAvatar?.speak?.({ Text: "Motion detected at " + name + "." }); } catch {} }
        if (cfg.react === "kaiju" || cfg.react === "all") { try { window.kaijuSim?.start?.(); } catch {} }
        if (cfg.react === "wall" || cfg.react === "all") { try { const cam = String(id).replace(/^binary_sensor\./, "camera.").replace(/_motion$/, ""); window.screenWall?.showImage?.("/ha/camera_snapshot?entity=" + encodeURIComponent(cam) + "&t=" + now); } catch {} }
        try { window.dispatchEvent(new CustomEvent("engine:haMotion", { detail: { id, name } })); } catch {}
    }
    function connect() {
        if (es) { try { es.close(); } catch {} es = null; }
        if (!cfg.enabled || typeof EventSource === "undefined") return;
        try {
            es = new EventSource("/ha/stream");
            es.onmessage = (m) => { let d; try { d = JSON.parse(m.data); } catch { return; } if (d && d.type === "motion" && d.state === "on") react(d); };
            es.onerror = () => { /* SSE auto-reconnects */ };
        } catch (e) {}
    }
    connect();
    return {
        config() { return { ...cfg }; },
        set(c) { cfg = Object.assign(cfg, c || {}); save(); connect(); return { ...cfg }; },
        test() { react({ entity_id: "binary_sensor.front_doorbell_motion", name: "Front Doorbell", state: "on" }); },
        status: () => ({ connected: !!es, last: lastEvent }),
    };
})();

// v1062 — Fallout 4 live state -> engine reactions. Polls /fallout/state (the
// bridge taps the Pip-Boy Companion App protocol) and edge-triggers reactions:
// connect, level-up, death, VATS, radio change, low-HP avatar alarm. The
// Pip-Boy effect color is exposed via window.fallout.color().
window.fallout = (() => {
    let timer = null, prev = null, started = false, lastLowHp = 0, color = null;
    const toast = (t, m, type) => { try { window._toaster?.show({ title: t, msg: m, type: type || "system", duration: 4500 }); } catch {} };
    const speak = (t) => { try { window.pipAvatar?.speak?.({ Text: t }); } catch {} };
    const vatsOf = (st) => !!(st && (st.IsInVats != null ? st.IsInVats : st.IsInVATS));
    const lvlOf = (p) => p ? (p.XPLevel != null ? p.XPLevel : p.Level) : null;
    function react(s) {
        if (!s || !s.ready) { prev = s; return; }
        const p = s.player || {}, st = s.status || {};
        const lvl = lvlOf(p), hp = p.CurrHP, mhp = p.MaxHP;
        const dead = !!st.IsPlayerDead, vats = vatsOf(st);
        const radio = s.radio && s.radio.active;
        if (Array.isArray(st.EffectColor)) color = st.EffectColor;
        const pv = (prev && prev.ready) ? prev : null;
        if (!pv) {
            toast("\u2622 Pip-Boy linked", (p.PlayerName || "Vault Dweller") + (lvl != null ? (" \u00b7 level " + lvl) : ""));
        } else {
            const plvl = lvlOf(pv.player);
            const _emit = (n, d) => { try { window.dispatchEvent(new CustomEvent(n, { detail: d || {} })); } catch {} };
            if (lvl != null && plvl != null && lvl > plvl) { toast("\u2B50 Level up", "Level " + lvl); speak("Level up. Level " + lvl + "."); _emit("engine:falloutLevelUp", { level: lvl }); }
            if (dead && !(pv.status && pv.status.IsPlayerDead)) { toast("\uD83D\uDC80 You died", "War never changes."); _emit("engine:falloutDeath", {}); }
            if (vats && !vatsOf(pv.status)) { toast("\uD83C\uDFAF VATS", "Targeting engaged"); _emit("engine:falloutVats", {}); }
            const pradio = pv.radio && pv.radio.active;
            if (radio && radio !== pradio) { toast("\uD83D\uDCFB Radio", radio); _emit("engine:falloutRadio", { station: radio }); }
        }
        if (hp != null && mhp) { const frac = hp / mhp; if (frac > 0 && frac < 0.25 && Date.now() - lastLowHp > 30000) { lastLowHp = Date.now(); toast("\u2764 Low HP", Math.round(frac * 100) + "%", "warn"); speak("Warning. Health critical."); } }
        prev = s;
    }
    async function tick() { try { const r = await fetch("/fallout/state", { cache: "no-store" }); if (r.ok) react(await r.json()); } catch {} }
    function startPolling() { if (started) return; started = true; tick(); timer = setInterval(tick, 2000); }
    function stopPolling() { started = false; if (timer) { clearInterval(timer); timer = null; } prev = null; }
    fetch("/fallout/status", { cache: "no-store" }).then(r => r.json()).then(j => { if (j && j.enabled) startPolling(); }).catch(() => {});
    return {
        startPolling, stopPolling,
        color: () => color,
        async setEnabled(on, host, autoDetect) { const body = { enabled: !!on, host: host || "auto" }; if (autoDetect != null) body.autoDetect = !!autoDetect; const j = await (await fetch("/fallout/config", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) })).json(); if (on || autoDetect) startPolling(); else stopPolling(); return j; },
        async state() { try { return await (await fetch("/fallout/state", { cache: "no-store" })).json(); } catch (e) { return { error: String(e) }; } },
        async status() { try { return await (await fetch("/fallout/status", { cache: "no-store" })).json(); } catch (e) { return { error: String(e) }; } },
    };
})();

// v1063 — Starfield live state -> engine reactions. Polls /starfield/state (the
// bridge talks to the SFSE Console API plugin). Edge-triggered: connect, level-up,
// taking damage (health drop), low oxygen.
window.starfield = (() => {
    let timer = null, prev = null, started = false, lastO2 = 0;
    const toast = (t, m, type) => { try { window._toaster?.show({ title: t, msg: m, type: type || "system", duration: 4500 }); } catch {} };
    const speak = (t) => { try { window.pipAvatar?.speak?.({ Text: t }); } catch {} };
    function react(s) {
        if (!s || !s.ready) { prev = s; return; }
        const p = s.player || {};
        const pv = (prev && prev.ready) ? (prev.player || {}) : null;
        if (!pv) {
            toast("\uD83D\uDE80 Starfield linked", "Level " + (p.level != null ? p.level : "?"));
        } else {
            if (p.level != null && pv.level != null && p.level > pv.level) { toast("\u2B50 Level up", "Level " + p.level); speak("Level up. Level " + p.level + "."); }
            if (p.health != null && pv.health != null && (pv.health - p.health) > 25) { toast("\uD83D\uDCA5 Taking damage", "HP " + Math.round(p.health)); }
        }
        if (p.o2 != null && p.o2 < 20 && Date.now() - lastO2 > 30000) { lastO2 = Date.now(); toast("\uD83E\uDEC1 Low oxygen", Math.round(p.o2) + "%", "warn"); speak("Warning. Oxygen low."); }
        prev = s;
    }
    async function tick() { try { const r = await fetch("/starfield/state", { cache: "no-store" }); if (r.ok) react(await r.json()); } catch {} }
    function startPolling() { if (started) return; started = true; tick(); timer = setInterval(tick, 3000); }
    function stopPolling() { started = false; if (timer) { clearInterval(timer); timer = null; } prev = null; }
    fetch("/starfield/status", { cache: "no-store" }).then(r => r.json()).then(j => { if (j && j.enabled) startPolling(); }).catch(() => {});
    // v1129 — auto-switch: poll a lightweight "is Starfield running?" probe; when the
    // game appears, flip Starfield mode on by itself (and optionally off when it quits).
    let _watchTimer = null, _wasRunning = false;
    async function _watchTick() {
        try {
            const j = await fetch("/starfield/detect", { cache: "no-store" }).then(r => r.json());
            const running = !!(j && j.running);
            if (running && !_wasRunning) {
                if (!started) { await api.setEnabled(true); try { window._toaster?.show({ title: "\uD83D\uDE80 Starfield detected", msg: "switching into Starfield mode", type: "system", duration: 4000 }); } catch {} }
            } else if (!running && _wasRunning) {
                if (localStorage.getItem("voxelengine.sfAutoOff") === "1" && started) { await api.setEnabled(false); try { window._toaster?.show({ title: "Starfield closed", msg: "left Starfield mode", type: "system", duration: 3000 }); } catch {} }
            }
            _wasRunning = running;
        } catch {}
    }
    function setAutoWatch(on) {
        localStorage.setItem("voxelengine.sfAutoWatch", on ? "1" : "0");
        if (_watchTimer) { clearInterval(_watchTimer); _watchTimer = null; }
        if (on) { _watchTick(); _watchTimer = setInterval(_watchTick, 6000); }
    }
    const api = {
        startPolling, stopPolling, setAutoWatch,
        autoWatchOn: () => localStorage.getItem("voxelengine.sfAutoWatch") === "1",
        async detect() { try { return await (await fetch("/starfield/detect", { cache: "no-store" })).json(); } catch (e) { return { ok: false, error: String(e) }; } },
        async setEnabled(on, host, port) { const b = { enabled: !!on }; if (host) b.host = host; if (port) b.port = port; const j = await (await fetch("/starfield/config", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(b) })).json(); if (on) startPolling(); else stopPolling(); return j; },
        async command(c) { return await (await fetch("/starfield/command", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ command: c }) })).json(); },
        async state() { try { return await (await fetch("/starfield/state", { cache: "no-store" })).json(); } catch (e) { return { error: String(e) }; } },
        async status() { try { return await (await fetch("/starfield/status", { cache: "no-store" })).json(); } catch (e) { return { error: String(e) }; } },
    };
    if (localStorage.getItem("voxelengine.sfAutoWatch") === "1") setAutoWatch(true);
    return api;
})();

// v1244 — X4: Foundations live state -> engine reactions. Polls /x4/state (the bridge
// reads a community mod feed in push or poll mode). Edge-triggered: link, big credit
// swings, hull/shield drops. Auto-watch flips the connector on when X4 appears.
window.x4 = (() => {
    let timer = null, prev = null, started = false, lastWarn = 0;
    const toast = (t, m, type) => { try { window._toaster?.show({ title: t, msg: m, type: type || "system", duration: 4500 }); } catch {} };
    const speak = (t) => { try { window.pipAvatar?.speak?.({ Text: t }); } catch {} };
    function react(s) {
        if (!s || !s.ready || !s.data) { prev = s; return; }
        const d = s.data, pv = (prev && prev.ready) ? prev.data : null;
        if (!pv) { toast("\uD83D\uDEF0\uFE0F X4 linked", d.player ? ("Pilot " + d.player) : "telemetry online"); }
        else {
            if (d.money != null && pv.money != null && (d.money - pv.money) >= 100000) toast("\uD83D\uDCB0 Big payout", "+" + (d.money - pv.money).toLocaleString() + " Cr");
            if (d.shipHull != null && pv.shipHull != null && (pv.shipHull - d.shipHull) > 15 && Date.now() - lastWarn > 20000) { lastWarn = Date.now(); toast("\uD83D\uDCA5 Hull damage", Math.round(d.shipHull) + "%", "warn"); speak("Warning. Hull integrity dropping."); }
        }
        prev = s;
    }
    async function tick() { try { const r = await fetch("/x4/state", { cache: "no-store" }); if (r.ok) react(await r.json()); } catch {} }
    function startPolling() { if (started) return; started = true; tick(); timer = setInterval(tick, 3000); }
    function stopPolling() { started = false; if (timer) { clearInterval(timer); timer = null; } prev = null; }
    fetch("/x4/status", { cache: "no-store" }).then(r => r.json()).then(j => { if (j && j.enabled) startPolling(); }).catch(() => {});
    let _watchTimer = null, _wasRunning = false;
    async function _watchTick() {
        try {
            const j = await fetch("/x4/detect", { cache: "no-store" }).then(r => r.json());
            const running = !!(j && j.running);
            if (running && !_wasRunning && !started) { await api.setEnabled(true); toast("\uD83D\uDEF0\uFE0F X4 detected", "switching into X4 mode", "system"); }
            else if (!running && _wasRunning && localStorage.getItem("voxelengine.x4AutoOff") === "1" && started) { await api.setEnabled(false); toast("X4 closed", "left X4 mode", "system"); }
            _wasRunning = running;
        } catch {}
    }
    function setAutoWatch(on) {
        localStorage.setItem("voxelengine.x4AutoWatch", on ? "1" : "0");
        if (_watchTimer) { clearInterval(_watchTimer); _watchTimer = null; }
        if (on) { _watchTick(); _watchTimer = setInterval(_watchTick, 6000); }
    }
    const api = {
        startPolling, stopPolling, setAutoWatch,
        autoWatchOn: () => localStorage.getItem("voxelengine.x4AutoWatch") === "1",
        async detect() { try { return await (await fetch("/x4/detect", { cache: "no-store" })).json(); } catch (e) { return { ok: false, error: String(e) }; } },
        async setEnabled(on, opts) { const b = Object.assign({ enabled: !!on }, opts || {}); const j = await (await fetch("/x4/config", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(b) })).json(); if (on) startPolling(); else stopPolling(); return j; },
        async state() { try { return await (await fetch("/x4/state", { cache: "no-store" })).json(); } catch (e) { return { error: String(e) }; } },
        async status() { try { return await (await fetch("/x4/status", { cache: "no-store" })).json(); } catch (e) { return { error: String(e) }; } },
    };
    if (localStorage.getItem("voxelengine.x4AutoWatch") === "1") setAutoWatch(true);
    return api;
})();

// v1247 — EVE Online pilot link. Polls /eve/state (bridge talks to ESI via SSO).
// Cloud API + OAuth, so "enabled" + auth happen via /eve/config + /eve/login; here we
// just surface state + a link toast. window.eve.state()/status()/detect().
window.eve = (() => {
    let timer = null, prev = null, started = false;
    const toast = (t, m, type) => { try { window._toaster?.show({ title: t, msg: m, type: type || "system", duration: 4500 }); } catch {} };
    function react(s) {
        if (!s || !s.ready || !s.data) { prev = s; return; }
        const d = s.data, pv = (prev && prev.ready) ? prev.data : null;
        if (!pv) toast("\uD83D\uDEF0\uFE0F EVE linked", d.character ? ("Pilot " + d.character) : "pilot online");
        else if (d.system && pv.system && d.system !== pv.system) toast("\uD83C\uDF0C Jumped", d.system);
        prev = s;
    }
    async function tick() { try { const r = await fetch("/eve/state", { cache: "no-store" }); if (r.ok) react(await r.json()); } catch {} }
    function startPolling() { if (started) return; started = true; tick(); timer = setInterval(tick, 6000); }
    function stopPolling() { started = false; if (timer) { clearInterval(timer); timer = null; } prev = null; }
    fetch("/eve/status", { cache: "no-store" }).then(r => r.json()).then(j => { if (j && j.enabled) startPolling(); }).catch(() => {});
    return {
        startPolling, stopPolling,
        async detect() { try { return await (await fetch("/eve/detect", { cache: "no-store" })).json(); } catch (e) { return { ok: false, error: String(e) }; } },
        async state() { try { return await (await fetch("/eve/state", { cache: "no-store" })).json(); } catch (e) { return { error: String(e) }; } },
        async status() { try { return await (await fetch("/eve/status", { cache: "no-store" })).json(); } catch (e) { return { error: String(e) }; } },
        async setConfig(cfg) { return await (await fetch("/eve/config", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(cfg || {}) })).json(); },
        loginUrl: () => "/eve/login",
    };
})();

