// v1065 — Game telemetry HUD on the avatar + Pip-Boy green display theme.
// When a game connector (Fallout 4 or Starfield) is delivering data, auto-show a
// compact HP/secondary HUD pinned to the avatar's demo-chrome (so it travels with
// the avatar wherever the chrome is shown), and optionally green-theme the in-engine
// view (CSS CRT filter on #glCanvas + scanlines). All client-side, localStorage cfg.
window.gameHud = (() => {
    const LS = "voxelengine.gamehud";
    const def = { hud: "auto", theme: "auto", avatar: "auto" };   // hud/theme/avatar: "auto" | "on" | "off"
    let cfg = (() => { try { return Object.assign({}, def, JSON.parse(localStorage.getItem(LS) || "{}")); } catch { return { ...def }; } })();
    const save = () => { try { localStorage.setItem(LS, JSON.stringify(cfg)); } catch {} };
    let timer = null, el = null, scan = null, styled = false, lastActive = false;

    function injectStyle() {
        if (styled) return; styled = true;
        const st = document.createElement("style");
        st.textContent =
            "html.pipboy-theme #glCanvas{filter:brightness(.95) sepia(.55) hue-rotate(60deg) saturate(2.3) contrast(1.06);}" +
            "#pipboyScan{position:fixed;inset:0;pointer-events:none;z-index:3;display:none;" +
            "background:repeating-linear-gradient(0deg,rgba(0,0,0,0) 0 2px,rgba(0,45,18,.16) 3px,rgba(0,0,0,0) 4px);}" +
            "html.pipboy-theme #pipboyScan{display:block;}" +
            // v1074 — when the real GL phosphor pass is on, drop the CSS filter +
            // CSS scanline overlay so the look isn't applied twice.
            "html.gl-phosphor #glCanvas{filter:none!important;}" +
            "html.gl-phosphor #pipboyScan{display:none!important;}" +
            "#gameHud{font:11px/1.2 ui-monospace,Consolas,monospace;color:#2bff88;background:rgba(4,20,10,.82);" +
            "border:1px solid #1aa257;border-radius:8px;padding:6px 8px;margin:6px 0 0;min-width:150px;" +
            "text-shadow:0 0 5px rgba(43,255,136,.5);box-shadow:0 0 12px rgba(0,0,0,.4);}" +
            "#gameHud .ghL{font-size:10px;letter-spacing:1px;text-transform:uppercase;opacity:.85;margin-bottom:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}" +
            "#gameHud .ghBar{height:13px;border:1px solid currentColor;border-radius:3px;position:relative;margin-top:4px;overflow:hidden;background:rgba(0,0,0,.35);}" +
            "#gameHud .ghBar>i{position:absolute;left:0;top:0;bottom:0;background:currentColor;opacity:.55;transition:width .35s ease;}" +
            "#gameHud .ghBar>b{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;}" +
            "#gameHud .ghVal{font-size:14px;font-weight:700;margin-top:2px;}" +
            // v1068 — Fallout 4 display mode: green-skin the avatar panel (#demoChrome).
            "html.pipboy-avatar #demoChrome{background:linear-gradient(180deg,rgba(4,22,12,.93),rgba(2,8,5,.93))!important;border:1px solid var(--game-color, #1aa257)!important;border-radius:10px!important;box-shadow:0 0 16px rgba(43,255,136,.22),inset 0 0 22px rgba(0,40,15,.45)!important;}" +
            "html.pipboy-avatar #demoChrome canvas{filter:brightness(.95) sepia(.55) hue-rotate(60deg) saturate(2.3) contrast(1.06);}" +
            "html.pipboy-avatar #demoChrome *{color:#2bff88!important;text-shadow:0 0 4px rgba(43,255,136,.4)!important;}" +
            "html.pipboy-avatar #demoChrome::after{content:\'\';position:absolute;inset:0;pointer-events:none;border-radius:10px;z-index:60;background:repeating-linear-gradient(0deg,rgba(0,0,0,0) 0 2px,rgba(0,45,18,.18) 3px,rgba(0,0,0,0) 4px);}" +
            // v1072 — Starfield display mode: blue-skin the avatar panel.
            "html.starfield-avatar #demoChrome{background:linear-gradient(180deg,rgba(6,18,34,.93),rgba(2,6,14,.93))!important;border:1px solid var(--game-color, #2b6e9e)!important;border-radius:10px!important;box-shadow:0 0 16px rgba(125,211,255,.22),inset 0 0 22px rgba(8,30,55,.5)!important;}" +
            "html.starfield-avatar #demoChrome canvas{filter:brightness(.95) sepia(.45) hue-rotate(165deg) saturate(2.2) contrast(1.05);}" +
            "html.starfield-avatar #demoChrome *{color:#8ff0ff!important;text-shadow:0 0 4px rgba(125,211,255,.4)!important;}" +
            "html.starfield-avatar #demoChrome::after{content:\'\';position:absolute;inset:0;pointer-events:none;border-radius:10px;z-index:60;background:repeating-linear-gradient(0deg,rgba(0,0,0,0) 0 2px,rgba(8,30,55,.18) 3px,rgba(0,0,0,0) 4px);}";
        document.head.appendChild(st);
        scan = document.createElement("div"); scan.id = "pipboyScan"; document.body.appendChild(scan);
    }

    // Normalize whichever connector is live into one shape.
    function normalize(fo, sf) {
        if (fo && fo.ready) {
            const p = fo.player || {}, st = fo.status || {};
            const lvl = p.XPLevel != null ? p.XPLevel : p.Level;
            let color = null;
            if (Array.isArray(st.EffectColor) && st.EffectColor.length >= 3) { const c = st.EffectColor.map(x => Math.round(Math.max(0, Math.min(1, x)) * 255)); color = "rgb(" + c[0] + "," + c[1] + "," + c[2] + ")"; }
            return { source: "fallout", icon: "\u2622", color: color || "#2bff88",
                label: (p.PlayerName || "Vault Dweller") + (lvl != null ? "  L" + lvl : ""),
                bars: [ { name: "HP", cur: p.CurrHP, max: p.MaxHP }, { name: "AP", cur: p.CurrAP, max: p.MaxAP } ] };
        }
        if (sf && sf.ready) {
            const p = sf.player || {};
            return { source: "starfield", icon: "\uD83D\uDE80", color: "#7dd3ff",
                label: "Starfield" + (p.level != null ? "  L" + p.level : ""),
                bars: [ { name: "HP", cur: p.health, max: null }, { name: "O2", cur: p.o2, max: 100 } ] };
        }
        return null;
    }

    function mount() {
        if (!el) {
            el = document.createElement("div"); el.id = "gameHud";
            const lab = document.createElement("div"); lab.className = "ghL"; el.appendChild(lab);
            el._lab = lab; el._bars = [];
        }
        const chrome = document.getElementById("demoChrome");
        const parent = chrome || document.body;
        if (el.parentElement !== parent) {
            if (!chrome) Object.assign(el.style, { position: "fixed", left: "12px", top: "12px", zIndex: 6, margin: "0" });
            else el.style.position = "";
            parent.appendChild(el);
        }
    }
    function paint(n) {
        mount();
        el.style.color = n.color; el.style.borderColor = n.color;
        el._lab.textContent = n.icon + "  " + n.label;
        // (re)build bars to match
        while (el._bars.length < n.bars.length) {
            const bar = document.createElement("div"); bar.className = "ghBar";
            const i = document.createElement("i"); const b = document.createElement("b");
            bar.appendChild(i); bar.appendChild(b); el.appendChild(bar); el._bars.push({ bar, i, b });
        }
        n.bars.forEach((m, idx) => {
            const w = el._bars[idx]; w.bar.style.display = (m.cur == null) ? "none" : "block";
            if (m.cur == null) { w.b.textContent = ""; return; }
            if (m.max && m.max > 0) { w.i.style.width = Math.max(0, Math.min(100, (m.cur / m.max) * 100)) + "%"; w.b.textContent = Math.round(m.cur) + " / " + Math.round(m.max) + " " + m.name; }
            else { w.i.style.width = "100%"; w.b.textContent = Math.round(m.cur) + " " + m.name; }
        });
        el.style.display = "block";
    }
    function applyTheme(active, n) {
        injectStyle();
        const want = cfg.theme === "on" || (cfg.theme === "auto" && active && n && n.source === "fallout");
        document.documentElement.classList.toggle("pipboy-theme", !!want);
    }
    function applyAvatar(active, n) {
        let mode = null;
        if (cfg.avatar === "on") mode = (n && n.source === "starfield") ? "starfield" : "fallout";
        else if (cfg.avatar === "auto" && active && n) mode = n.source === "starfield" ? "starfield" : (n.source === "fallout" ? "fallout" : null);
        const cl = document.documentElement.classList;
        cl.toggle("pipboy-avatar", mode === "fallout");
        cl.toggle("starfield-avatar", mode === "starfield");
    }

    async function tick() {
        if (typeof window !== "undefined" && window.__swekPollsPaused) return;   // v1870 — hold while Settings is open
        let fo = null, sf = null;
        try { fo = await (await fetch("/fallout/state", { cache: "no-store" })).json(); } catch {}
        try { sf = await (await fetch("/starfield/state", { cache: "no-store" })).json(); } catch {}
        const n = normalize(fo, sf);
        const active = !!n;
        const showHud = cfg.hud === "on" || (cfg.hud === "auto" && active);
        if (showHud && n) paint(n); else if (el) el.style.display = "none";
        applyTheme(active, n);
        applyAvatar(active, n);
        try { if (n && n.color) document.documentElement.style.setProperty("--game-color", n.color); else document.documentElement.style.removeProperty("--game-color"); } catch {}
        lastActive = active;
    }
    function start() { injectStyle(); if (timer) return; tick(); timer = setInterval(tick, 2000); }
    function stop() { if (timer) { clearInterval(timer); timer = null; } if (el) el.style.display = "none"; document.documentElement.classList.remove("pipboy-theme"); document.documentElement.classList.remove("pipboy-avatar"); document.documentElement.classList.remove("starfield-avatar"); }

    // Only run the poller if something might use it (hud or theme not fully off).
    if (cfg.hud !== "off" || cfg.theme !== "off" || cfg.avatar !== "off") start();

    return {
        config: () => ({ ...cfg }),
        set(c) { cfg = Object.assign(cfg, c || {}); save(); if (cfg.hud === "off" && cfg.theme === "off" && cfg.avatar === "off") stop(); else { start(); tick(); } return { ...cfg }; },
    };
})();

