// --- migrate volume sliders into the existing Audio tab ---
{
    const am = () => window.audioManager;
    const vol = (id, label, group, prop) => ({
        id, label, hint: "Volume 0–100%", type: "slider", min: 0, max: 1, step: 0.05,
        get: () => { const a = am(); return a?.currentVolume?.(group) ?? a?.[prop] ?? 1.0; },
        set: (v) => { const a = am(); try { a?.setVolume?.(group, v); if (a) a[prop] = v; } catch {} },
    });
    _tab("audio")?.controls.push(
        vol("volMaster", "Master volume", "master", "masterVolume"),
        vol("volSfx",    "SFX volume",    "sfx",    "sfxVolume"),
        vol("volMusic",  "Music volume",  "music",  "musicVolume"),
        // v855 — music toggle. Persists to localStorage. When ON, music
        // starts on next user gesture (or immediately if context is
        // already resumed). When OFF, stops any playing music + skips
        // the auto-start hook.
        {
            id: "musicEnabled", label: "Music", hint: "Ambient pad loop (procedural — no asset files needed)", type: "toggle",
            get: () => {
                try {
                    const raw = localStorage.getItem("voxelEngine.musicEnabled");
                    return raw === null ? true : raw === "1";
                } catch { return true; }
            },
            set: (v) => {
                try { localStorage.setItem("voxelEngine.musicEnabled", v ? "1" : "0"); } catch {}
                Promise.resolve(window.audio).then(audio => {
                    if (!audio) return;
                    if (v) {
                        try { audio.startMusic("ambient_pad"); } catch {}
                    } else {
                        try { audio.stopMusic(); } catch {}
                    }
                });
            },
        },
    );
}

