          const runBtn = mkBtn("Run once", "#2a4d3a", "#4a7d5a"), dryBtn = mkBtn("Preview (dry run)", "#3a4a6a", "#5a6a8a"), forgetBtn = mkBtn("Forget processed", "#5a3a3a", "#8a5a5a");
