          dryBtn.addEventListener("click", async () => { msg.textContent = "previewing\u2026"; msg.style.color = "#8b97a8"; showResults(await petfbi("process", Object.assign(cfgFromUI(), { dryRun: true }))); msg.textContent = "preview"; });
