          instPyBtn.addEventListener("click", async () => { instPyBtn.disabled = true; pyStatus.style.color = "#9fb3cc"; pyStatus.textContent = "installing Python\u2026 (several minutes \u2014 watch the bridge console)"; const j = await fetch("/rules/install-python", { method: "POST" }).then(r => r.json()).catch(e => ({ ok: false, error: e.message })); instPyBtn.disabled = false; if (j && j.ok) { pyStatus.style.color = "#9fe88f"; pyStatus.textContent = "\u2713 Python installed via " + (j.via || "installer") + " \u2014 restart the bridge, then Install openpyxl."; } else { pyStatus.style.color = "#f0a85a"; pyStatus.textContent = "\u26A0 " + ((j && j.error) || "couldn't auto-install"); dlLink.style.display = ""; if (j && j.downloadUrl) dlLink.href = j.downloadUrl; } });
