          createBtn.addEventListener("click", async () => { let pth = xlsIn.value.trim(); if (!pth && _assetsBase) { pth = joinXls(_assetsBase); xlsIn.value = pth; } if (!pth) { msg.style.color = "#f88"; msg.textContent = "set a path or pick a folder first"; return; } msg.style.color = "#9fb3cc"; msg.textContent = "creating workbook\u2026"; const j = await fetch("/rules/template", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ path: pth }) }).then(r => r.json()).catch(e => ({ ok: false, error: e.message })); if (j && j.ok) { if (j.path) xlsIn.value = j.path; await api("config", cfg()); msg.style.color = "#9fe88f"; msg.textContent = "\u2713 created " + String(j.path || pth).split(/[\\/]/).pop(); refreshWbStatus(); } else { const why = (j && j.error) || ""; const se = (j && j.stderr) ? (" \u2014 " + j.stderr.slice(0, 140)) : ""; msg.style.color = "#f88"; msg.textContent = "\u2717 " + (why || "create failed") + se + (/openpyxl|module/i.test(why + se) ? "  (needs Python + openpyxl)" : ""); } });
