          host.append(owner, token, engRepo);
          const cfgRow = document.createElement("div"); cfgRow.style.cssText = "display:flex; gap:6px; align-items:center; flex-wrap:wrap;";
          const saveBtn = mkBtn("Save", "#2a4d3a", "#4a7d5a");
