              const url = document.createElement("input"); url.type = "text"; url.value = h.url || ""; url.placeholder = "https://prod-XX.westus.logic.azure.com/workflows/.../triggers/manual/paths/invoke?..."; url.style.cssText = "padding:6px 8px;background:#0c0f14;color:#e8eef8;border:1px solid #2a3340;border-radius:6px;font:10.5px ui-monospace,monospace;width:100%;box-sizing:border-box;";
              card.appendChild(url);
