          const btn = (t) => { const b = document.createElement("button"); b.textContent = t; b.style.cssText = "padding:4px 9px;background:#26384f;color:#cde;border:1px solid #3a557a;border-radius:5px;cursor:pointer;font-size:11px;"; return b; };
          const inp = (ph, val) => { const i = document.createElement("input"); i.type = "text"; i.placeholder = ph || ""; if (val) i.value = val; i.style.cssText = "flex:1;min-width:90px;padding:3px 6px;background:#0b1422;border:1px solid #356;color:#cde;font-size:11px;border-radius:4px;"; return i; };
          const hostIp = (location.hostname || "127.0.0.1");

