          const fzAuto = document.createElement("label"); fzAuto.style.cssText = "display:flex;gap:6px;align-items:center;font-size:11px;color:#cde;margin-top:5px;cursor:pointer;"; const fzChk = document.createElement("input"); fzChk.type = "checkbox"; fzAuto.append(fzChk, document.createTextNode("Auto-show a camera on its wall when a person is detected"));
          const fzRow = document.createElement("div"); fzRow.style.cssText = "display:flex;gap:5px;margin-top:4px;"; const fzScan = btn("Scan Frigate"); const g2b = inp("go2rtc base (for walls)", "http://" + hostIp + ":1984"); fzRow.append(fzScan, g2b);
          fz.append(fzMsg, fzGrid, fzAuto, fzRow); host.appendChild(fz);
