          const go = document.createElement("button"); go.textContent = "Make Gmail-safe zip"; go.style.cssText = "padding:6px 14px;background:#2a4d3a;color:#cfe;border:1px solid #4a7d5a;border-radius:6px;cursor:pointer;font-size:12px;";
          // v1567 — second path: convert an EXISTING engine .zip into a Gmail-safe zip in My Documents.
          const fromZip = document.createElement("button"); fromZip.textContent = "\uD83D\uDCE6 From a .zip \u2192 My Documents"; fromZip.title = "Pick an existing engine .zip; it's extracted, converted to a Gmail-safe zip in your Documents folder, and the temp files are cleaned up."; fromZip.style.cssText = "padding:6px 14px;background:#2a3a5a;color:#cfe;border:1px solid #4a5a8a;border-radius:6px;cursor:pointer;font-size:12px;";
