// v504 — thunderstorm: forces the storm weather (which already screen-flashes)
// and periodically strikes the ground — charring the hit voxel to ASH + a bolt/
// spark burst. Lightning favours high ground.
let _thunderTimer = null;
const _thunderBolt = (x, y, z) => {
    const g = window.gpuParticles; if (!g?.spawn) return;
    try { window._sfx?.("ogre_internal_explosion", 0.5); } catch {}   // v531 — thunder clap
    for (let i = 0; i < 10; i++) g.spawn({ x: x + 0.5, y: y + 1 + i * 1.6, z: z + 0.5, vx: 0, vy: 0, vz: 0, life: 0.22, size: 0.5, r: 0.92, g: 0.96, b: 1.0, shape: 0 });
    for (let i = 0; i < 14; i++) g.spawn({ x: x + 0.5, y: y + 0.8, z: z + 0.5, vx: (Math.random() - 0.5) * 4, vy: Math.random() * 3, vz: (Math.random() - 0.5) * 4, life: 0.5, size: 0.3, r: 1, g: 0.9, b: 0.55, shape: 0 });
};
const _thunderTick = () => {
    try { weatherSystem.state = "storm"; weatherSystem._stateAge = 0; } catch {}
    if (Math.random() < 0.45) {
        try {
            const p = pickStrike(world, Math.round(camera.position.x), Math.round(camera.position.z), 42);
            if (p) {
                const fireOn = window._wildfireOn?.();
                const hit = lightningStrike(world, p.x, p.z, { char: !fireOn });   // don't char if we're igniting
                if (fireOn && hit) { try { if (!window.fire?.ignite?.(hit.x, hit.y, hit.z)) window.fire?.igniteArea?.({ centerX: p.x, centerZ: p.z, radius: 1 }); } catch {} }
                _thunderBolt(p.x, hit?.y ?? 20, p.z);
            }
        } catch {}
    }
};
const _setThunder = (on) => {
    if (on && !_thunderTimer) _thunderTimer = setInterval(_thunderTick, 600);
    else if (!on && _thunderTimer) { clearInterval(_thunderTimer); _thunderTimer = null; try { weatherSystem.state = "rain"; weatherSystem._stateAge = 0; } catch {} }
};
window.thunderstorm = (on = true) => _setThunder(!!on);
