                  const card = document.createElement("div"); card.style.cssText = "border:1px solid #2a3340;border-radius:7px;padding:7px 8px;background:#0a0e14;display:flex;flex-direction:column;gap:5px;";
                  const top = document.createElement("div"); top.style.cssText = "display:flex;align-items:center;gap:8px;";
                  const on = document.createElement("input"); on.type = "checkbox"; on.checked = !!cur.on; on.onchange = () => setAcc(slot, "on", on.checked);
                  const title = document.createElement("span"); title.textContent = LBL[slot]; title.style.cssText = "font:600 12px ui-monospace,monospace;color:#cde;flex:1;";
                  top.append(on, title); card.appendChild(top);
                  const sel = document.createElement("select"); sel.style.cssText = "background:#0c0f14;color:#cde;border:1px solid #2a3340;border-radius:5px;padding:4px;";
                  const txt = document.createElement("input"); txt.type = "text"; txt.value = cur.url || ""; txt.placeholder = "/assets/glb?id=...  or  /GPU_Assets/Hat.glb"; txt.style.cssText = "padding:5px 8px;background:#0c0f14;color:#cde;border:1px solid #2a3340;border-radius:5px;font:11px ui-monospace,monospace;";
                  const fill = () => { sel.innerHTML = ""; const ph = document.createElement("option"); ph.value = ""; ph.textContent = "\u2014 pick an accessory-tagged GLB \u2014"; sel.appendChild(ph); for (const o of taggedOpts) { const op = document.createElement("option"); op.value = o.value; op.textContent = o.label; if (o.value === txt.value) op.selected = true; sel.appendChild(op); } };
                  _fills.push(fill); fill();
                  sel.onchange = () => { if (sel.value) { txt.value = sel.value; setAcc(slot, "url", sel.value); } };
                  txt.onchange = () => setAcc(slot, "url", txt.value.trim());
                  card.append(sel, txt);
                  const knobs = document.createElement("div"); knobs.style.cssText = "display:flex;gap:6px;flex-wrap:wrap;";
                  const mkNum = (key, label, step) => { const w = document.createElement("label"); w.style.cssText = "display:flex;flex-direction:column;gap:2px;font:10px ui-monospace,monospace;color:#8b97a8;flex:1;min-width:60px;"; const sp = document.createElement("span"); sp.textContent = label; const n = document.createElement("input"); n.type = "number"; n.step = String(step); n.value = String(cur[key]); n.style.cssText = "padding:4px 6px;background:#0c0f14;color:#cde;border:1px solid #2a3340;border-radius:5px;font:11px ui-monospace,monospace;"; n.onchange = () => { const v = parseFloat(n.value); if (Number.isFinite(v)) setAcc(slot, key, v); }; w.append(sp, n); return w; };
                  knobs.append(mkNum("scale", "scale", 0.05), mkNum("lift", "lift", 0.01), mkNum("fwd", "fwd", 0.01));
                  if (slot !== "head") { const w = document.createElement("label"); w.style.cssText = "display:flex;flex-direction:column;gap:2px;font:10px ui-monospace,monospace;color:#8b97a8;flex:1;min-width:60px;"; const sp = document.createElement("span"); sp.textContent = "side"; const sd = document.createElement("select"); sd.style.cssText = "padding:4px 6px;background:#0c0f14;color:#cde;border:1px solid #2a3340;border-radius:5px;"; for (const v of ["right","left"]) { const o = document.createElement("option"); o.value = v; o.textContent = v; if (v === (cur.side || "right")) o.selected = true; sd.appendChild(o); } sd.onchange = () => setAcc(slot, "side", sd.value); w.append(sp, sd); knobs.appendChild(w); }
                  card.appendChild(knobs);
