          const mk = (labelText, ph, listId, tag) => { const w = document.createElement("label"); w.style.cssText = "display:flex; flex-direction:column; gap:2px; font-size:11px; color:#cde;"; const l = document.createElement("span"); l.textContent = labelText; l.style.cssText = "color:#9bb0c8;"; const el = document.createElement(tag || "input"); if (tag !== "select") { el.placeholder = ph; if (listId) el.setAttribute("list", listId); } el.style.cssText = "width:100%;padding:6px 8px;background:#0c0f14;color:#e8eef8;border:1px solid #2a3340;border-radius:6px;font:11px ui-monospace,monospace;"; w.append(l, el); host.appendChild(w); return el; };
          const where = mk("Where", "", null, "select");
