          const doSave = () => window.haMotion.set({ enabled: enChk.checked, react: react.value, onlyDoorbell: dbChk.checked, cooldownMs: (parseInt(cd.value,10)||20)*1000 });
          save.addEventListener("click", () => { try { doSave(); const st = window.haMotion.status(); msg.textContent = "\u2713 saved" + (enChk.checked ? (st.connected ? " \u00b7 listening" : " \u00b7 connecting\u2026") : " \u00b7 disabled"); msg.style.color = "#9fe88f"; } catch (e) { msg.textContent = "error"; msg.style.color = "#f88"; } });
