          const open = document.createElement("a"); open.textContent = "open stream \u25B8"; open.target = "_blank"; open.rel = "noopener"; open.href = "/spectator/mjpeg"; open.style.cssText = "font-size:11px;color:#9bd6ff;text-decoration:none;";
          const cst = document.createElement("span"); cst.style.cssText = "font-size:11px; color:#8b97a8;";
          castRow.append(startBtn, stopBtn, open, cst); host.appendChild(castRow);
          const tgt = document.createElement("input"); tgt.placeholder = "media_player.living_room_tv_3"; tgt.setAttribute("list", "liveMpList"); tgt.style.cssText = "width:100%;padding:6px 8px;background:#0c0f14;color:#e8eef8;border:1px solid #2a3340;border-radius:6px;font:11px ui-monospace,monospace;"; host.appendChild(tgt);
          const mpList = document.createElement("datalist"); mpList.id = "liveMpList"; host.appendChild(mpList);
          const row2 = document.createElement("div"); row2.style.cssText = "display:flex; gap:6px; flex-wrap:wrap; align-items:center;";
