          const castTv = document.createElement("button"); castTv.textContent = "\uD83D\uDCFA Cast to TV"; castTv.style.cssText = "padding:4px 12px;background:#3a4a6a;color:#cde;border:1px solid #5a6a8a;border-radius:5px;cursor:pointer;font-size:11px;";
          const msg = document.createElement("span"); msg.style.cssText = "font-size:11px; color:#8b97a8; flex:1; min-height:14px;";
          row2.append(detect, castTv, msg); host.appendChild(row2);
          const refresh = () => { try { cst.textContent = spectatorCast && spectatorCast.isRunning && spectatorCast.isRunning() ? "casting" : "idle"; cst.style.color = spectatorCast && spectatorCast.isRunning && spectatorCast.isRunning() ? "#9fe88f" : "#8b97a8"; } catch {} };
          refresh();
          startBtn.addEventListener("click", () => { try { spectatorCast.start({ fps: 6, quality: 0.5 }); cst.textContent = "casting"; cst.style.color = "#9fe88f"; } catch (e) { cst.textContent = "error"; } });
          stopBtn.addEventListener("click", () => { try { spectatorCast.stop(); cst.textContent = "idle"; cst.style.color = "#8b97a8"; } catch {} });
