          loadStatus();
          save.addEventListener("click", async () => { msg.textContent = "saving\u2026"; msg.style.color = "#8b97a8"; try { const j = await window.fallout.setEnabled(enChk.checked, hostIn.value.trim() || "auto", adChk.checked); msg.textContent = j.ok ? (enChk.checked ? "\u2713 enabled" : "\u2713 disabled") : "failed"; msg.style.color = j.ok ? "#9fe88f" : "#f88"; setTimeout(async () => paint(await window.fallout.state()), 1200); } catch (e) { msg.textContent = "error"; msg.style.color = "#f88"; } });
          refresh.addEventListener("click", async () => { paint(await window.fallout.state()); });
