                      const nudge = async (d) => { let t = (e.temperature || 0) + d * step; if (e.min_temp != null) t = Math.max(e.min_temp, t); if (e.max_temp != null) t = Math.min(e.max_temp, t); set.textContent = t + "\u00b0"; e.temperature = t; await window.ha.call("climate", "set_temperature", { entity_id: e.entity_id, temperature: t }); };
