          const bApply = mkBtn("Apply to selected", "#9fe88f"), bAll = mkBtn("⚡ Broadcast to ALL", "#ffe08a"), bOffSel = mkBtn("Off selected"), bOffAll = mkBtn("Off all", "#ffb4b4");
          actRow.append(bApply, bAll, bOffSel, bOffAll); host.appendChild(actRow);
