                  const cb = document.createElement("input"); cb.type = "checkbox"; checks.set(String(d.id), cb);
                  const swatch = document.createElement("button"); swatch.title = "apply current color to just this one"; swatch.style.cssText = "width:16px;height:16px;border-radius:3px;border:1px solid #2a3340;background:#222;cursor:pointer;";
                  swatch.onclick = async (ev) => { ev.preventDefault(); const r = await window.rgb.set(d.id, picker.value); setMsg(r.ok ? ("set " + (d.name || d.id)) : (r.error || "failed"), r.ok); };
