          const addBtn = document.createElement("button"); addBtn.textContent = "Add to avatar choices"; addBtn.style.cssText = "padding:5px 12px;background:#16202c;color:#cde;border:1px solid #2a3340;border-radius:6px;cursor:pointer;font-size:12px;";
          const useBtn = document.createElement("button"); useBtn.textContent = "Add + use as my avatar"; useBtn.style.cssText = "padding:5px 12px;background:#2a4d3a;color:#cfe;border:1px solid #4a7d5a;border-radius:6px;cursor:pointer;font-size:12px;";
          row.append(addBtn, useBtn); host.appendChild(row);
          const msg = document.createElement("span"); msg.style.cssText = "font-size:11px; color:#8b97a8; min-height:14px;"; host.appendChild(msg);
