                  const nm = document.createElement("span"); nm.textContent = f.label || f.url; nm.style.flex = "1"; nm.style.fontFamily = "ui-monospace,monospace";
                  const use = document.createElement("button"); use.textContent = "use"; use.style.cssText = "padding:2px 8px;background:#16202c;color:#9fe88f;border:1px solid #2a3340;border-radius:5px;cursor:pointer;font-size:10px;";
                  const del = document.createElement("button"); del.textContent = "✕"; del.style.cssText = "padding:2px 7px;background:#16202c;color:#f88;border:1px solid #2a3340;border-radius:5px;cursor:pointer;font-size:10px;";
