          const target = document.createElement("select"); target.style.cssText = "padding:5px 8px;background:#0c0f14;color:#e8eef8;border:1px solid #2a3340;border-radius:6px;font-size:12px;flex:1;min-width:160px;";
          const optSelf = document.createElement("option"); optSelf.value = ""; optSelf.textContent = "This PC (local)"; target.appendChild(optSelf);
          const rescan = document.createElement("button"); rescan.textContent = "\u21bb peers"; rescan.title = "rescan the LAN for peer engines"; rescan.style.cssText = "padding:5px 10px;background:#16202c;color:#cde;border:1px solid #2a3340;border-radius:6px;cursor:pointer;font-size:11px;";
          tRow.append(tLbl, target, rescan); host.appendChild(tRow);

          // --- image list for the current target ---
          const imgWrap = document.createElement("div"); imgWrap.style.cssText = "display:flex;flex-direction:column;gap:6px;";
          host.appendChild(imgWrap);
          const status = document.createElement("div"); status.style.cssText = "font-size:11px;color:#8b97a8;min-height:15px;";
          host.appendChild(status);
          const say = (t, ok) => { status.textContent = t; status.style.color = ok === false ? "#f88" : ok === true ? "#9fe88f" : "#8b97a8"; };
          const baseNow = () => target.value || "";

          function imageRow(img) {
              const row = document.createElement("div"); row.style.cssText = "display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:5px 7px;background:#0c1118;border:1px solid #1f2733;border-radius:7px;";
              const dot = document.createElement("span"); dot.style.cssText = "width:9px;height:9px;border-radius:50%;background:#666;flex:0 0 auto;";
              const nm = document.createElement("span"); nm.textContent = img.name; nm.style.cssText = "font-size:12.5px;color:#e8eef8;font-weight:600;min-width:90px;";
              const pth = document.createElement("span"); pth.textContent = img.vmx; pth.title = img.vmx; pth.style.cssText = "font-size:10px;color:#5c6675;font-family:ui-monospace,monospace;flex:1;min-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;";
              const mk = (txt, col) => { const b = document.createElement("button"); b.textContent = txt; b.style.cssText = "padding:4px 9px;background:#16202c;color:" + (col || "#cde") + ";border:1px solid #2a3340;border-radius:5px;cursor:pointer;font-size:11px;"; return b; };
              const bS = mk("Start", "#9fe88f"), bX = mk("Stop", "#f4b58f"), bR = mk("Restart", "#9fd0ff");
              // v1585 — optional GUI start: watch the VM boot in a real VMware window (default is headless nogui).
              const guiWrap = document.createElement("label"); guiWrap.title = "Start with the VMware window visible (default is headless nogui). Handy to watch an HA VM boot."; guiWrap.style.cssText = "display:flex;align-items:center;gap:3px;font-size:10.5px;color:#8b97a8;cursor:pointer;user-select:none;";
              const guiCk = document.createElement("input"); guiCk.type = "checkbox"; guiCk.style.cssText = "margin:0;cursor:pointer;";
              guiWrap.append(guiCk, document.createTextNode("window"));
              // v1585 — readiness phase (off / booting / ready), separate from the raw power dot.
              const phEl = document.createElement("span"); phEl.style.cssText = "font-size:10.5px;font-family:ui-monospace,monospace;min-width:56px;";
              row.append(dot, nm, pth, phEl, guiWrap, bS, bX, bR);
              const PH = { off: ["#777", "off", "#8b97a8"], running: ["#4ad07a", "on", "#9fe88f"], booting: ["#e3c552", "booting\u2026", "#e3c552"], ready: ["#4ad07a", "ready \u2713", "#9fe88f"] };
              const refresh = () => window.vm.status(img.vmx, baseNow()).then(s => {
                  if (!s || !s.ok) { dot.style.background = "#a33"; phEl.textContent = ""; phEl.title = (s && s.error) || ""; return; }
                  const phase = s.phase || (s.running ? "running" : "off");
                  const p = PH[phase] || PH.off;
                  dot.style.background = p[0]; phEl.textContent = p[1]; phEl.style.color = p[2];
                  phEl.title = "tools: " + (s.tools || "n/a") + (s.ip ? " \u00b7 ip " + s.ip : "");
                  bS.disabled = !!s.running; bX.disabled = !s.running;
                  bS.style.opacity = s.running ? .5 : 1; bX.style.opacity = s.running ? 1 : .5;
              }).catch(() => { dot.style.background = "#a33"; phEl.textContent = ""; });
              // v1585 — start/restart kick off a guest boot; re-poll a few times so the phase climbs to "ready".
              const act = (fn, label) => { say(img.name + ": " + label + "\u2026"); fn().then(r => { say((r && r.ok ? "\u2713 " : "\u2717 ") + img.name + " " + label + (r && r.error ? ": " + r.error : ""), !!(r && r.ok)); [1500, 6000, 16000, 32000].forEach(t => setTimeout(refresh, t)); }).catch(() => say(img.name + " " + label + " failed", false)); };
              bS.onclick = () => act(() => window.vm.start(img.vmx, baseNow(), guiCk.checked), "start" + (guiCk.checked ? " (window)" : ""));
              bX.onclick = () => act(() => window.vm.stop(img.vmx, "soft", baseNow()), "stop");
              bR.onclick = () => act(() => window.vm.restart(img.vmx, "soft", baseNow()), "restart");
              refresh();
              return row;
          }

          function loadImages() {
              imgWrap.innerHTML = "";
              const loading = document.createElement("div"); loading.textContent = "loading VMs\u2026"; loading.style.cssText = "font-size:11px;color:#8b97a8;"; imgWrap.appendChild(loading);
              window.vm.images(baseNow()).then(j => {
                  imgWrap.innerHTML = "";
                  const list = (j && j.images) || [];
                  if (!list.length) { const e = document.createElement("div"); e.textContent = baseNow() ? "(peer has no VM images configured)" : "(no VM images configured \u2014 add one below)"; e.style.cssText = "font-size:11px;color:#8b97a8;"; imgWrap.appendChild(e); }
                  else for (const img of list) imgWrap.appendChild(imageRow(img));
                  manageBox.style.display = baseNow() ? "none" : "block";   // edit images on the LOCAL box only
              }).catch(() => { imgWrap.innerHTML = ""; const e = document.createElement("div"); e.textContent = "(target unreachable)"; e.style.cssText = "font-size:11px;color:#f88;"; imgWrap.appendChild(e); });
          }

