          const manageBox = document.createElement("div"); manageBox.style.cssText = "display:block;border-top:1px solid #1f2733;margin-top:6px;padding-top:8px;";
          const mTitle = document.createElement("div"); mTitle.textContent = "Manage this PC\u2019s VM images"; mTitle.style.cssText = "font-size:11px;color:#7a8290;margin-bottom:6px;";
          const mList = document.createElement("div"); mList.style.cssText = "display:flex;flex-direction:column;gap:5px;";
          manageBox.append(mTitle, mList);
