// v1050 — group the Connectors section by topic with full-width header rows,
// reordering related controls together (Discord, Twitch, Camera, AI/data keys,
// Sheets). Done by id post-build so each control keeps its closure; all groups
// stay visible in one scrollable panel (no hide-others sub-tabs yet).
(() => {
    const sec = _schema.find(s => s && s.id === "discord");   // the Connectors section
    if (!sec || !Array.isArray(sec.controls)) return;
    const byId = {}; for (const c of sec.controls) if (c && c.id) byId[c.id] = c;
    const hdr = (title, key) => ({ id: "_grp_" + key, type: "custom", label: title, render(host) {
        host.style.cssText = "padding:0; border:0;";
        const d = document.createElement("div"); d.textContent = title;
        d.style.cssText = "margin:16px 0 2px; padding:5px 6px; font-size:11px; font-weight:700; letter-spacing:1.5px; text-transform:uppercase; color:#9bd6ff; border-top:1px solid rgba(120,180,255,0.18); border-bottom:1px solid rgba(120,180,255,0.28);";
        host.appendChild(d);
    } });
    const groups = [
        { title: "🔗 Get started", key: "start", ids: ["setupLinks"] },
        { title: "💬 Discord", key: "discord", ids: ["discordWebhook", "discordVoice"] },
        { title: "🟣 Twitch", key: "twitch", ids: ["twitchChat", "twitchEvents"] },
        { title: "📷 Camera", key: "camera", ids: ["ipCamera"] },
        { title: "🔑 AI & service keys", key: "keys", ids: ["geminiKey", "otherKey", "fmpKey", "aiKeyStatus", "genAsset"] },
        { title: "📊 Google Sheets", key: "sheets", ids: ["sheetsCreds", "sheetsTest"] },
    ];
    const out = [], used = new Set();
    for (const g of groups) {
        const members = g.ids.map(id => byId[id]).filter(Boolean);
        if (!members.length) continue;
        out.push(hdr(g.title, g.key));
        for (const m of members) { out.push(m); used.add(m.id); }
    }
    for (const c of sec.controls) if (c && c.id && !used.has(c.id) && !/^_grp_/.test(c.id)) out.push(c);   // keep any uncategorised control
    sec.controls = out;
})();

// v1093 — split the World/terrain tabs into their own "Terrain Settings" panel.
// _schema stays the full list (remote phone control + describe/apply still use it);
// each PC hub renders a filtered view of it.
// v1494 — consolidate Settings categories (from Geek's screenshots): dedupe the tabs that
// shared an id (so their 2nd tab was unreachable) and merge related tabs together, recovering
// any controls that were stranded. Runs on _schema before the terrain/main split + the sort.
(function consolidateSettingsSchema() {
    const all = (id) => _schema.filter((s) => s && s.id === id);
    const first = (id) => _schema.find((s) => s && s.id === id);
    const drop = (sec) => { const i = _schema.indexOf(sec); if (i >= 0) _schema.splice(i, 1); };
    const mergeDupes = (id, prepend) => {
        const dl = all(id); if (dl.length < 2) return;
        const keep = dl[0];
        for (let k = 1; k < dl.length; k++) {
            keep.controls = prepend ? (dl[k].controls || []).concat(keep.controls || []) : (keep.controls || []).concat(dl[k].controls || []);
            drop(dl[k]);
        }
    };
    const mergeInto = (srcId, dstId) => {
        const src = first(srcId), dst = first(dstId);
        if (src && dst && src !== dst) { dst.controls = (dst.controls || []).concat(src.controls || []); drop(src); }
    };
    mergeDupes("assets", true);            // two "Assets" -> one (folder + gmail-safe controls to the front)
    mergeDupes("kpopListener", false);     // two "KPop Listener" -> one (recovers the clipboard-listener control)
    { const s = first("autostart"); if (s) s.label = "Demo list"; }                 // Auto-start -> Demo list
    mergeInto("avatarGaugeToggles", "avatar");                                       // Avatar Gauges -> Avatar Settings
    mergeInto("customAvatar", "avatar");                                             // Custom Avatar (GLB) -> Avatar Settings
    // v1560 — PalChat (M1<->M2) is an avatar feature: move it from Assets into Avatar Settings.
    try { const _s = first("assets"), _d = first("avatar"); if (_s && _d && Array.isArray(_s.controls)) { const _i = _s.controls.findIndex(c => c && c.id === "palChat"); if (_i >= 0) { const [_c] = _s.controls.splice(_i, 1); (_d.controls = _d.controls || []).push(_c); } } } catch {}
    // v1560 — markitdown / Firecrawl / Immich became standalone Applications (Markdown, Immich);
    // drop their controls from Settings -> Assets so they live in one place.
    try { const _a = first("assets"); if (_a && Array.isArray(_a.controls)) _a.controls = _a.controls.filter(c => !c || !["docToMarkdown", "webToMarkdown", "immichPhotos"].includes(c.id)); } catch {}
    { const s = first("sttVoice"); if (s) s.label = "Speech (STT) / Voice (TTS)"; }  // Speech (STT) + Voice (TTS) merge
    mergeInto("ttsVoice", "sttVoice");
})();

