// v615 — Picker input switch. Mouse + phone both feed a single cursor NDC and
// a click event bus. SandboxMode subscribes. Phone messages from phone.html
// route here via WSBridge type listeners.
const _phoneGravity = new DeviceGravity({ tau: 0.25 });
let _phoneGravityLast = 0;
try {
    const pickerInput = new PickerInput();
    window._pickerInput = pickerInput;
    // phone:picker:arm   — phone entered picker mode → next orient sample calibrates
    bridge.on("phone:picker:arm",    () => { pickerInput.phoneArm();    });
    bridge.on("phone:picker:disarm", () => { pickerInput.phoneDisarm(); });
    // phone:picker:orient — { alpha, beta, gamma } from deviceorientation event
    bridge.on("phone:picker:orient", (m) => {
        pickerInput.setPhoneOrient(m.alpha ?? 0, m.beta ?? 0, m.gamma ?? 0);
        // v4230 — THE SAME MESSAGE, READ AS A DIRECTION RATHER THAN AS A CURSOR. The relay has carried
        // alpha/beta/gamma at 30 Hz since v618 and every consumer treated the angles as a UI control:
        // thresholded steering on the phone, a cursor here. input/deviceGravity.mjs turns them into which way
        // is DOWN, in the screen frame, in m/s^2 -- so physics/sph's tilt work has a real tilt to read
        // instead of a `deg` the code hands itself. Nothing is forced to use it; it is published and idle.
        const now = performance.now();
        const dt = _phoneGravityLast ? (now - _phoneGravityLast) / 1000 : 0;
        _phoneGravityLast = now;
        const unit = _phoneGravity.orientation(m.alpha ?? 0, m.beta ?? 0, m.gamma ?? 0);
        window.phoneGravity = _phoneGravity.step(unit, dt);
    });
    // phone:picker:tap    — screen tap on phone → click
    bridge.on("phone:picker:tap",    () => { pickerInput.firePhoneTap(); });
    // v618 — long-press on the phone overlay = right-click (despawn entity).
    // phone.html sends this after a 500ms hold without release.
    bridge.on("phone:picker:longpress", () => { pickerInput.firePhoneRightClick(); });
    // phone:picker:recalibrate — phone explicitly asked to reset baseline
    bridge.on("phone:picker:recalibrate", () => { pickerInput.recalibrate(); });
    console.log("[picker] PickerInput ready — listening for phone:picker:* WS messages from phone.html");
} catch (e) { console.warn("[picker] PickerInput init failed:", e?.message); }

