        const h = document.createElement("div"); h.style.cssText = "font-size:21px;color:#2bff88;font-weight:bold;letter-spacing:.5px;margin-bottom:4px;"; h.textContent = "Welcome to SweK Engine";
        const intro = document.createElement("div"); intro.style.cssText = "color:#9fcbb4;font-size:12.5px;margin-bottom:18px;"; intro.textContent = "Two quick choices to set things up. You can change either later in Settings \u2014 or skip and decide as you go.";
