        const s1d = document.createElement("div"); s1d.style.cssText = "color:#9fcbb4;font-size:12px;margin-bottom:8px;"; s1d.innerHTML = "Some demos need a small helper (a PDF engine, a camera server\u2026). Install the small ones automatically as needed? Dev tools (Bun, OpenRGB) are never installed silently.";
        const choices = document.createElement("div"); choices.style.cssText = "display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px;";
